def days_until_empty(quantity, daily_sales):
    if daily_sales <= 0:
        return float("inf")
    return quantity / daily_sales


def validate_entry(entry):
    if len(entry) != 3:
        raise ValueError("each inventory entry needs a name, quantity and daily sales")
    name, quantity, daily_sales = entry
    if not isinstance(name, str) or not name.strip():
        raise ValueError("item name must be a non-empty string")
    for value in (quantity, daily_sales):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError("quantity and daily sales for %r must be numbers" % name)
        if value < 0:
            raise ValueError("quantity and daily sales for %r cannot be negative" % name)
    return name.strip(), quantity, daily_sales


def restock(inventory):
    orders = []
    for entry in inventory:
        name, quantity, daily_sales = validate_entry(entry)
        if days_until_empty(quantity, daily_sales) < 7:
            needed = 30 * daily_sales - quantity
            if needed > 0:
                orders.append((name, needed))
    return orders


def format_report(inventory):
    orders = restock(inventory)
    if not orders:
        return "All items have at least a week of stock remaining."
    width = max(len(name) for name, _amount in orders)
    lines = ["Restock to a 30-day supply:"]
    for name, amount in orders:
        if float(amount).is_integer():
            amount_text = "%d units" % int(amount)
        else:
            amount_text = "%.1f units" % amount
        lines.append("  %-*s  %s" % (width, name, amount_text))
    return "\n".join(lines)


def urgency_order(inventory):
    ranked = []
    for entry in inventory:
        name, quantity, daily_sales = validate_entry(entry)
        ranked.append((days_until_empty(quantity, daily_sales), name))
    ranked.sort()
    return [name for _days, name in ranked]


def main():
    inventory = [
        ("widgets", 12, 5),
        ("bolts", 400, 10),
        ("gaskets", 3, 1),
        ("display case", 2, 0),
        ("grommets", 18, 4.5),
    ]
    print(format_report(inventory))
    print("Watch list:", ", ".join(urgency_order(inventory)[:3]))
    try:
        restock([("hinges", -4, 2)])
    except ValueError as error:
        print("Rejected batch:", error)


if __name__ == "__main__":
    main()

