import sys


def parse_rolls(tokens):
    """Convert text tokens into a list of pin counts."""
    rolls = []
    for token in tokens:
        text = token.strip().rstrip(",")
        if not text:
            continue
        if not text.isdigit():
            raise ValueError("rolls must be non-negative integers: %r" % token)
        rolls.append(int(text))
    return rolls


def validate_rolls(rolls):
    """Check the roll sequence and return the index where the tenth frame starts."""
    for pins in rolls:
        if pins < 0 or pins > 10:
            raise ValueError("roll out of range: %d" % pins)
    index = 0
    for frame in range(9):
        if index >= len(rolls):
            raise ValueError("frame %d has no rolls" % (frame + 1))
        if rolls[index] == 10:
            index += 1
        else:
            if index + 1 >= len(rolls):
                raise ValueError("frame %d is missing its second roll" % (frame + 1))
            if rolls[index] + rolls[index + 1] > 10:
                raise ValueError("frame %d knocks down more than ten pins" % (frame + 1))
            index += 2
    tenth = rolls[index:]
    if len(tenth) < 2:
        raise ValueError("the tenth frame needs at least two rolls")
    if tenth[0] != 10 and tenth[0] + tenth[1] > 10:
        raise ValueError("the tenth frame knocks down more than ten pins")
    if tenth[0] == 10 or tenth[0] + tenth[1] == 10:
        if len(tenth) != 3:
            raise ValueError("a strike or spare in the tenth frame earns exactly one bonus roll")
    elif len(tenth) != 2:
        raise ValueError("an open tenth frame earns no bonus roll")
    return index


def score(rolls):
    """Total score of a complete tenpin bowling game."""
    validate_rolls(rolls)
    total = 0
    index = 0
    for _ in range(10):
        if rolls[index] == 10:
            total += 10 + rolls[index + 1] + rolls[index + 2]
            index += 1
        elif rolls[index] + rolls[index + 1] == 10:
            total += 10 + rolls[index + 2]
            index += 2
        else:
            total += rolls[index] + rolls[index + 1]
            index += 2
    return total


def format_frame(frame_rolls):
    marks = []
    for position, pins in enumerate(frame_rolls):
        previous = frame_rolls[position - 1] if position else None
        if pins == 10:
            marks.append("X")
        elif previous is not None and previous != 10 and previous + pins == 10:
            marks.append("/")
        elif pins == 0:
            marks.append("-")
        else:
            marks.append(str(pins))
    return "".join(marks)


def frame_breakdown(rolls):
    """Per-frame marks together with the running total after each frame."""
    validate_rolls(rolls)
    breakdown = []
    index = 0
    running = 0
    for frame in range(10):
        if frame == 9:
            frame_rolls = rolls[index:]
        elif rolls[index] == 10:
            frame_rolls = rolls[index:index + 1]
        else:
            frame_rolls = rolls[index:index + 2]
        if rolls[index] == 10:
            running += 10 + rolls[index + 1] + rolls[index + 2]
        elif rolls[index] + rolls[index + 1] == 10:
            running += 10 + rolls[index + 2]
        else:
            running += rolls[index] + rolls[index + 1]
        breakdown.append((frame + 1, format_frame(frame_rolls), running))
        index += len(frame_rolls)
    return breakdown


def format_scorecard(rolls):
    lines = []
    for number, marks, running in frame_breakdown(rolls):
        lines.append("frame %2d  %-3s  %3d" % (number, marks, running))
    return "\n".join(lines)


def main(argv):
    tokens = argv[1:]
    if not tokens:
        tokens = sys.stdin.read().split()
    try:
        rolls = parse_rolls(tokens)
        card = format_scorecard(rolls)
    except ValueError as error:
        print("invalid game: %s" % error)
        return 1
    print(card)
    print("total: %d" % score(rolls))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

