PAIRS = {")": "(", "]": "[", "}": "{"}
OPENERS = set(PAIRS.values())


def balance(expression):
    """Return True if all brackets in the expression are properly nested."""
    stack = []
    for char in expression:
        if char in OPENERS:
            stack.append(char)
        elif char in PAIRS:
            if not stack or stack.pop() != PAIRS[char]:
                return False
    return not stack


def first_error(expression):
    """Locate the first offending bracket, as (index, character), or None."""
    stack = []
    for index, char in enumerate(expression):
        if char in OPENERS:
            stack.append((index, char))
        elif char in PAIRS:
            if not stack or stack[-1][1] != PAIRS[char]:
                return index, char
            stack.pop()
    if stack:
        return stack[0]
    return None


def bracket_counts(expression):
    """Count how often each bracket character occurs in the expression."""
    counts = {}
    for char in expression:
        if char in OPENERS or char in PAIRS:
            counts[char] = counts.get(char, 0) + 1
    return counts


def describe(expression):
    """Build a one-line human readable verdict for the expression."""
    if balance(expression):
        summary = "balanced"
    else:
        position, char = first_error(expression)
        summary = "unbalanced at index {0} ({1!r})".format(position, char)
    counts = bracket_counts(expression)
    if counts:
        parts = []
        for char in sorted(counts):
            parts.append("{0}x{1}".format(char, counts[char]))
        summary += " [" + " ".join(parts) + "]"
    else:
        summary += " [no brackets]"
    return summary


def main():
    samples = [
        "(a + [b * c] - {d / e})",
        "plain text without brackets",
        "([)]",
        "function(arg) { return list[0]; }",
        "{{unclosed",
        "closed too many))",
    ]
    width = 0
    for sample in samples:
        if len(sample) > width:
            width = len(sample)
    for sample in samples:
        print("{0:<{1}}  ->  {2}".format(repr(sample), width + 2, describe(sample)))


if __name__ == "__main__":
    main()

