RANKS = "23456789TJQKA"
SUITS = "cdhs"


def parse_card(card):
    """Turn a two character card such as 'Th' into a (rank index, suit) pair."""
    text = card.strip()
    if len(text) != 2:
        raise ValueError("card %r must have exactly two characters" % card)
    rank, suit = text[0].upper(), text[1].lower()
    if rank not in RANKS:
        raise ValueError("unknown rank %r in card %r" % (rank, card))
    if suit not in SUITS:
        raise ValueError("unknown suit %r in card %r" % (suit, card))
    return RANKS.index(rank), suit


def parse_hand(hand):
    if len(hand) != 5:
        raise ValueError("a hand needs five cards, got %d" % len(hand))
    cards = [parse_card(card) for card in hand]
    seen = set()
    for card in cards:
        if card in seen:
            raise ValueError("duplicate card in hand: %s%s" % (RANKS[card[0]], card[1]))
        seen.add(card)
    return cards


def rank_counts(cards):
    counts = {}
    for value, _suit in cards:
        counts[value] = counts.get(value, 0) + 1
    return sorted(counts.values(), reverse=True)


def is_flush(cards):
    suits = {suit for _value, suit in cards}
    return len(suits) == 1


def is_straight(cards):
    values = sorted({value for value, _suit in cards})
    if len(values) != 5:
        return False
    if values == [0, 1, 2, 3, 12]:
        return True
    return values[4] - values[0] == 4


def evaluate(hand):
    """Score a five card hand from 1 (high card) to 5 (straight flush)."""
    cards = parse_hand(hand)
    flush = is_flush(cards)
    straight = is_straight(cards)
    if flush and straight:
        return 5
    if flush or straight:
        return 4
    counts = rank_counts(cards)
    if counts[0] == 3:
        return 3
    if counts[0] == 2:
        return 2
    return 1


def score_name(score):
    names = {
        5: "straight flush",
        4: "flush or straight",
        3: "three of a kind",
        2: "pair",
        1: "high card",
    }
    return names[score]


def main():
    hands = [
        ["9h", "Th", "Jh", "Qh", "Kh"],
        ["2c", "5c", "9c", "Jc", "Ac"],
        ["4d", "5h", "6s", "7c", "8d"],
        ["7d", "7h", "7s", "2c", "9d"],
        ["Ad", "Ah", "4s", "9c", "Td"],
        ["2d", "6h", "8s", "Jc", "Kd"],
    ]
    for hand in hands:
        score = evaluate(hand)
        print("%s -> %d (%s)" % (" ".join(hand), score, score_name(score)))


if __name__ == "__main__":
    main()

