import string
from collections import Counter


def clean_text(text):
	"""Lowercase the text and strip punctuation, returning the bare words."""
	if not isinstance(text, str):
		raise TypeError("text must be a string")
	cleaned = []
	for char in text.lower():
		if char in string.punctuation:
			cleaned.append(" ")
		else:
			cleaned.append(char)
	return "".join(cleaned).split()


def histogram(text):
	"""Return (word, count) pairs sorted by count desc, then alphabetically."""
	words = clean_text(text)
	counts = Counter(words)
	return sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))


def top_words(pairs, limit):
	"""Return at most `limit` entries, keeping every word tied at the cutoff."""
	if limit <= 0:
		return []
	if limit >= len(pairs):
		return list(pairs)
	cutoff = pairs[limit - 1][1]
	result = []
	for word, count in pairs:
		if count < cutoff:
			break
		result.append((word, count))
	return result


def format_histogram(pairs, bar_char="#"):
	"""Render the histogram as aligned text lines with proportional bars."""
	if not pairs:
		return "(no words found)"
	width = max(len(word) for word, _ in pairs)
	lines = []
	for word, count in pairs:
		bar = bar_char * count
		lines.append("{0:<{1}}  {2:>3}  {3}".format(word, width, count, bar))
	return "\n".join(lines)


def summarize(text, limit=5):
	"""Build a short report: totals plus the most frequent words."""
	pairs = histogram(text)
	total = sum(count for _, count in pairs)
	header = "{0} words, {1} distinct".format(total, len(pairs))
	return header + "\n" + format_histogram(top_words(pairs, limit))


def main():
	paragraph = (
		"The rain in Spain falls mainly on the plain. "
		"The plain, however, is dry; the rain fell on the hills! "
		"Rain, rain -- go away?"
	)
	print(summarize(paragraph))
	print()
	for word, count in histogram(paragraph):
		if count == 1:
			print("hapax:", word)
		else:
			print("repeated:", word, "x", count)


if __name__ == "__main__":
	main()

