def validate_square(matrix):
    """Check that matrix is a non-empty square matrix of integers."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of lists")
    size = len(matrix)
    for row in matrix:
        if not isinstance(row, list):
            raise ValueError("every row must be a list")
        if len(row) != size:
            raise ValueError("matrix must be square")
        for value in row:
            if not isinstance(value, int) or isinstance(value, bool):
                raise ValueError("matrix entries must be integers")
    return size


def transpose(matrix):
    """Return the transpose of a square matrix."""
    size = len(matrix)
    result = []
    for j in range(size):
        new_row = []
        for i in range(size):
            new_row.append(matrix[i][j])
        result.append(new_row)
    return result


def multiply(left, right):
    """Multiply two square matrices with row by column multiplication."""
    size = len(left)
    product = []
    for i in range(size):
        row = []
        for j in range(size):
            total = 0
            for k in range(size):
                total += left[i][k] * right[k][j]
            row.append(total)
        product.append(row)
    return product


def transform(matrix):
    """Return the product of matrix and its transpose."""
    validate_square(matrix)
    return multiply(matrix, transpose(matrix))


