def validate(address):
    """Return True if the given string is a well-formed IPv4 dotted-quad."""
    if not isinstance(address, str):
        return False
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False
    return True


def octets(address):
    """Return the four octets of a valid address as a list of integers."""
    return [int(part) for part in address.split(".")]


def classify(address):
    """Describe the range an address belongs to, per the usual IPv4 blocks."""
    first, second, third, fourth = octets(address)
    if first == 10:
        return "private"
    if first == 172 and 16 <= second <= 31:
        return "private"
    if first == 192 and second == 168:
        return "private"
    if first == 127:
        return "loopback"
    if first == 169 and second == 254:
        return "link-local"
    if 224 <= first <= 239:
        return "multicast"
    if first == 0 or (third == 0 and fourth == 0 and first > 239):
        return "reserved"
    return "public"


def describe(address):
    """Build a one-line report for a candidate address string."""
    if validate(address):
        return "{0:<20} valid    ({1})".format(address, classify(address))
    return "{0:<20} invalid".format(address)


def summarize(candidates):
    """Count how many of the candidates are valid addresses."""
    valid = 0
    for candidate in candidates:
        if validate(candidate):
            valid += 1
    return valid, len(candidates) - valid


