def build_graph(dependencies):
    """Return adjacency map and in-degree map from (task, dependency) pairs."""
    successors = {}
    indegree = {}
    for task, requirement in dependencies:
        for name in (task, requirement):
            if name not in successors:
                successors[name] = []
                indegree[name] = 0
        successors[requirement].append(task)
        indegree[task] += 1
    return successors, indegree


def resolve(dependencies):
    """Topologically sort tasks; return [] when a cycle makes them impossible."""
    successors, indegree = build_graph(dependencies)
    ready = sorted(name for name, count in indegree.items() if count == 0)
    order = []
    while ready:
        current = ready.pop(0)
        order.append(current)
        for follower in successors[current]:
            indegree[follower] -= 1
            if indegree[follower] == 0:
                ready.append(follower)
        ready.sort()
    if len(order) != len(successors):
        return []
    return order


def find_cycle(dependencies):
    """Return one cycle as a list of task names, or [] if the graph is acyclic."""
    successors, _ = build_graph(dependencies)
    state = {name: 0 for name in successors}
    stack = []

    def visit(node):
        state[node] = 1
        stack.append(node)
        for follower in successors[node]:
            if state[follower] == 1:
                return stack[stack.index(follower):] + [follower]
            if state[follower] == 0:
                cycle = visit(follower)
                if cycle:
                    return cycle
        stack.pop()
        state[node] = 2
        return []

    for name in sorted(successors):
        if state[name] == 0:
            cycle = visit(name)
            if cycle:
                return cycle
    return []


def report(dependencies):
    """Format a human readable summary of the resolution attempt."""
    order = resolve(dependencies)
    if order:
        lines = ["Execution order:"]
        for position, task in enumerate(order, start=1):
            lines.append("  {0}. {1}".format(position, task))
    else:
        lines = ["Cannot resolve: cycle detected"]
        cycle = find_cycle(dependencies)
        if cycle:
            lines.append("  " + " -> ".join(cycle))
    return "\n".join(lines)


def main():
    builds = [
        [("deploy", "test"), ("test", "compile"), ("compile", "fetch"), ("docs", "fetch")],
        [("a", "b"), ("b", "c"), ("c", "a")],
    ]
    for dependencies in builds:
        print(report(dependencies))
        print()


if __name__ == "__main__":
    main()

