from collections import defaultdict


def normalize(word):
    """Return the anagram key of a word: its letters, sorted, without punctuation."""
    letters = []
    for char in word.lower():
        if char in string.ascii_lowercase:
            letters.append(char)
    return "".join(sorted(letters))


def group(words):
    """Group words that are anagrams of each other, ignoring punctuation."""
    buckets = defaultdict(list)
    for word in words:
        key = normalize(word)
        if key:
            buckets[key].append(word)
    groups = []
    for key in buckets:
        members = buckets[key]
        if len(members) > 1:
            groups.append(members)
