def split_components(path):
    """Split a path on slashes, dropping empty segments caused by repeats."""
    components = []
    for piece in path.split("/"):
        if piece:
            components.append(piece)
    return components


def simplify(path):
    """Return the canonical form of the absolute path `path`."""
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not path.startswith("/"):
        raise ValueError("path must be absolute (start with '/')")
    stack = []
    for name in split_components(path):
        if name == ".":
            continue
        if name == "..":
            if stack:
                stack.pop()
            continue
        stack.append(name)
    return "/" + "/".join(stack)


def depth(path):
    """Number of directory levels in the canonical form of `path`."""
    return len(split_components(simplify(path)))


def parent(path):
    """Canonical path of the parent directory, clamped at the root."""
    canonical = simplify(path)
    if canonical == "/":
        return "/"
    cut = canonical.rindex("/")
    if cut == 0:
        return "/"
    return canonical[:cut]


def report(paths):
    """Build aligned report lines for every path in `paths`."""
    rows = []
    for raw in paths:
        try:
            canonical = simplify(raw)
        except (TypeError, ValueError) as error:
            rows.append((repr(raw), "error: " + str(error), "", ""))
            continue
        rows.append((raw, canonical, str(depth(raw)), parent(raw)))
    widths = [0, 0, 0, 0]
    for row in rows:
        for index, cell in enumerate(row):
            if len(cell) > widths[index]:
                widths[index] = len(cell)
    lines = []
    for row in rows:
        cells = []
        for index, cell in enumerate(row):
            cells.append(cell.ljust(widths[index]))
        lines.append("  ".join(cells).rstrip())
    return lines


