def validate(intervals):
    """Return a list of (start, end) tuples, rejecting malformed meeting times."""
    cleaned = []
    for index, interval in enumerate(intervals):
        if len(interval) != 2:
            raise ValueError("meeting %d must have exactly a start and an end" % index)
        start, end = interval
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError("meeting %d must use integer minutes" % index)
        if start < 0 or end > 24 * 60:
            raise ValueError("meeting %d falls outside a single day" % index)
        if end <= start:
            raise ValueError("meeting %d ends before it starts" % index)
        cleaned.append((start, end))
    return cleaned


def schedule(intervals):
    """Minimum number of conference rooms needed for all the given meetings."""
    meetings = validate(intervals)
    starts = sorted(start for start, _ in meetings)
    ends = sorted(end for _, end in meetings)
    rooms = 0
    peak = 0
    next_end = 0
    for start in starts:
        while next_end < len(ends) and ends[next_end] <= start:
            rooms -= 1
            next_end += 1
        rooms += 1
        if rooms > peak:
            peak = rooms
    return peak


def assign_rooms(intervals):
    """Place every meeting in a concrete room, reusing rooms as soon as they free up."""
    meetings = sorted(validate(intervals))
    free_at = []
    assignment = []
    for start, end in meetings:
        chosen = None
        for room, busy_until in enumerate(free_at):
            if busy_until <= start:
                chosen = room
                break
        if chosen is None:
            chosen = len(free_at)
            free_at.append(end)
        else:
            free_at[chosen] = end
        assignment.append((chosen, start, end))
    return assignment


def clock(minutes):
    return "%02d:%02d" % divmod(minutes, 60)


def report(intervals):
    lines = ["Rooms required: %d" % schedule(intervals)]
    per_room = {}
    for room, start, end in assign_rooms(intervals):
        per_room.setdefault(room, []).append((start, end))
    for room in sorted(per_room):
        slots = ", ".join("%s-%s" % (clock(s), clock(e)) for s, e in per_room[room])
        lines.append("Room %d: %s" % (room + 1, slots))
    return "\n".join(lines)


def main():
    day = [(540, 600), (555, 645), (600, 660), (630, 700), (720, 780), (735, 765)]
    print(report(day))
    for candidate in ([], [(480, 540), (540, 600)], [(0, 1440), (60, 120)]):
        print("%-34s -> %d rooms" % (candidate, schedule(candidate)))


if __name__ == "__main__":
    main()

