VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

REPEATABLE = {"I", "X", "C", "M"}


def validate(numeral):
    """Raise ValueError unless numeral is a well formed roman numeral."""
    if not numeral:
        raise ValueError("empty roman numeral")
    run_char = ""
    run_length = 0
    for index, char in enumerate(numeral):
        if char not in VALUES:
            raise ValueError("invalid roman character: {0}".format(char))
        if char == run_char:
            run_length += 1
            if run_length > 3 or char not in REPEATABLE:
                raise ValueError("too many repeats of {0}".format(char))
        else:
            run_char = char
            run_length = 1
        if index + 2 < len(numeral):
            small = VALUES[char]
            if small < VALUES[numeral[index + 1]] and small < VALUES[numeral[index + 2]]:
                raise ValueError("ambiguous subtraction near {0}".format(char))


def convert(numeral):
    """Return the base ten value of a roman numeral up to three thousand."""
    cleaned = numeral.strip().upper()
    validate(cleaned)
    total = 0
    for index, char in enumerate(cleaned):
        value = VALUES[char]
        if index + 1 < len(cleaned) and value < VALUES[cleaned[index + 1]]:
            total -= value
        else:
            total += value
    if total > 3000:
        raise ValueError("value above three thousand: {0}".format(total))
    return total


def describe(numeral):
    """Format one numeral and its value, or the reason it was rejected."""
    try:
        return "{0:>10} = {1}".format(numeral, convert(numeral))
    except ValueError as error:
        return "{0:>10} ! {1}".format(numeral, error)


def report(numerals):
    """Print a line per numeral and return how many converted successfully."""
    converted = 0
    for numeral in numerals:
        line = describe(numeral)
        print(line)
        if " = " in line:
            converted += 1
    return converted


def main():
    samples = ["IX", "iv", "MMXXIV", "XLII", "MMM", "CDXCIX", "IIII", "IL", "MMMI"]
    converted = report(samples)
    print("converted {0} of {1} numerals".format(converted, len(samples)))
    running = 0
    for numeral in samples:
        if " = " in describe(numeral):
            running += convert(numeral)
    print("sum of valid numerals: {0}".format(running))


if __name__ == "__main__":
    main()

