import sys


def tokenize(expression):
	"""Split an expression string into integer and operator tokens."""
	tokens = []
	digits = ""
	for char in expression:
		if char.isdigit():
			digits += char
		else:
			if digits:
				tokens.append(int(digits))
				digits = ""
			if not char.isspace():
				tokens.append(char)
	if digits:
		tokens.append(int(digits))
	return tokens


def fold_signs(tokens):
	"""Attach leading '+'/'-' signs to the numbers they qualify."""
	folded = []
	sign = 1
	for token in tokens:
		if isinstance(token, int):
			folded.append(sign * token)
			sign = 1
		elif folded and isinstance(folded[-1], int):
			folded.append(token)
		elif token == "-":
			sign = -sign
	return folded


def apply_operator(left, right, operator):
	"""Combine two integers, truncating division toward zero."""
	if operator == "+":
		return left + right
	if operator == "-":
		return left - right
	if operator == "*":
		return left * right
	quotient = abs(left) // abs(right)
	if (left < 0) != (right < 0):
		return -quotient
	return quotient


def reduce_pass(tokens, operators):
	"""Evaluate every occurrence of the given operators, left to right."""
	reduced = [tokens[0]]
	index = 1
	while index < len(tokens):
		operator = tokens[index]
		operand = tokens[index + 1]
		if operator in operators:
			reduced[-1] = apply_operator(reduced[-1], operand, operator)
		else:
			reduced.append(operator)
			reduced.append(operand)
		index += 2
	return reduced


def calculate(expression):
	tokens = fold_signs(tokenize(expression))
	if not tokens:
		raise ValueError("no expression to evaluate")
	tokens = reduce_pass(tokens, ("*", "/"))
	tokens = reduce_pass(tokens, ("+", "-"))
	return tokens[0]


def main():
	for line in sys.stdin:
		expression = line.strip()
		if expression:
			print("{} = {}".format(expression, calculate(expression)))


if __name__ == "__main__":
