def validate(words, width):
    """Check that the input can actually be justified to the given width."""
    if not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width <= 0:
        raise ValueError("width must be positive")
    for word in words:
        if not isinstance(word, str):
            raise TypeError("every word must be a string")
        if not word:
            raise ValueError("empty words cannot be placed on a line")
        if len(word) > width:
            raise ValueError("word %r is longer than width %d" % (word, width))


def group_words(words, width):
    """Greedily pack words into lines that fit within width."""
    lines = []
    current = []
    letters = 0
    for word in words:
        if current and letters + len(current) + len(word) > width:
            lines.append(current)
            current = []
            letters = 0
        current.append(word)
        letters += len(word)
    if current:
        lines.append(current)
    return lines


def spread(line, width):
    """Pad a single line of words to exactly width, extras on the left."""
    if len(line) == 1:
        return line[0].ljust(width)
    gaps = len(line) - 1
    base, extra = divmod(width - sum(len(word) for word in line), gaps)
    pieces = []
    for index, word in enumerate(line[:-1]):
        pieces.append(word)
        if index < extra:
            pieces.append(" " * (base + 1))
        else:
            pieces.append(" " * base)
    pieces.append(line[-1])
    return "".join(pieces)


def justify(words, width):
    """Return the list of fully justified lines; the last line is left aligned."""
    validate(words, width)
    lines = group_words(words, width)
    result = []
    for position, line in enumerate(lines):
        if position == len(lines) - 1:
            result.append(" ".join(line).ljust(width))
        else:
            result.append(spread(line, width))
    return result


def format_report(lines, width):
    """Frame the justified text so the exact column width is visible."""
    border = "+" + "-" * width + "+"
    rows = [border]
    for line in lines:
        rows.append("|" + line + "|")
    rows.append(border)
    return "\n".join(rows)


def main():
    text = "The quick brown fox jumps over the lazy dog while the programmer justifies text one greedy line at a time"
    words = text.split()
    for width in (20, 34):
        print(format_report(justify(words, width), width))
        print()


if __name__ == "__main__":
    main()

