import heapq


def build_graph(flights):
    """Turn a list of (origin, destination, price, minutes) into an adjacency map."""
    graph = {}
    for entry in flights:
        if len(entry) != 4:
            raise ValueError("each flight needs origin, destination, price and duration")
        origin, destination, price, minutes = entry
        if price < 0 or minutes < 0:
            raise ValueError("price and duration must not be negative")
        graph.setdefault(origin, []).append((destination, price, minutes))
        graph.setdefault(destination, [])
    return graph


def cheapest_route(graph, start, goal):
    """Dijkstra on (price, duration); price dominates, duration breaks ties."""
    if start not in graph or goal not in graph:
        return (-1, -1)
    best = {start: (0, 0)}
    queue = [(0, 0, start)]
    while queue:
        price, minutes, city = heapq.heappop(queue)
        if city == goal:
            return (price, minutes)
        if best.get(city) != (price, minutes):
            continue
        for neighbour, leg_price, leg_minutes in graph[city]:
            candidate = (price + leg_price, minutes + leg_minutes)
            if neighbour not in best or candidate < best[neighbour]:
                best[neighbour] = candidate
                heapq.heappush(queue, (candidate[0], candidate[1], neighbour))
    return (-1, -1)


def optimize(flights, requests):
    """Return (price, duration) for each requested trip, or (-1, -1) when unreachable."""
    graph = build_graph(flights)
    results = []
    for request in requests:
        if len(request) != 2:
            raise ValueError("each request needs a start and a destination")
        start, goal = request
        if start == goal:
            results.append((0, 0))
        else:
            results.append(cheapest_route(graph, start, goal))
    return results


def format_report(requests, results):
    lines = []
    for (start, goal), (price, minutes) in zip(requests, results):
        if price < 0:
            lines.append("{} -> {}: no route available".format(start, goal))
        else:
            hours, remainder = divmod(minutes, 60)
            lines.append("{} -> {}: ${} in {}h{:02d}m".format(start, goal, price, hours, remainder))
    return "\n".join(lines)


def main():
    flights = [
        ("Seattle", "Boston", 300, 360),
        ("Seattle", "Chicago", 120, 200),
        ("Chicago", "Boston", 180, 150),
        ("Chicago", "Denver", 90, 110),
        ("Denver", "Boston", 210, 240),
        ("Boston", "Miami", 150, 180),
    ]
    requests = [
        ("Seattle", "Boston"),
        ("Seattle", "Miami"),
        ("Miami", "Denver"),
        ("Chicago", "Chicago"),
    ]
    results = optimize(flights, requests)
    print(results)
    print(format_report(requests, results))


if __name__ == "__main__":
    main()

