def _sign(value):
    return (value > 0) - (value < 0)


def validate_calls(calls, floors):
    """Check the request list against the building and return it as tuples."""
    if floors < 1:
        raise ValueError("a building needs at least one floor")
    checked = []
    for position, call in enumerate(calls):
        if len(call) != 3:
            raise ValueError("call %d must be (time, origin, destination)" % position)
        moment, origin, destination = call
        if moment < 0:
            raise ValueError("call %d has a negative time" % position)
        if not 1 <= origin <= floors:
            raise ValueError("call %d starts outside the building" % position)
        if not 1 <= destination <= floors:
            raise ValueError("call %d ends outside the building" % position)
        if origin == destination:
            raise ValueError("call %d does not go anywhere" % position)
        checked.append((moment, origin, destination))
    return sorted(checked)


def simulate(calls, floors):
    """Return the second at which the last passenger reaches their floor."""
    pending = validate_calls(calls, floors)
    onboard = []
    time = 0
    floor = 1
    direction = 0
    last_arrival = 0
    while pending or onboard:
        available = [call for call in pending if call[0] <= time]
        if not onboard and not available:
            time = pending[0][0]
            continue
        dropped = floor in onboard
        if dropped:
            onboard = [target for target in onboard if target != floor]
        if direction == 0:
            if onboard:
                direction = _sign(onboard[0] - floor)
            elif available[0][1] == floor:
                direction = _sign(available[0][2] - floor)
            else:
                direction = _sign(available[0][1] - floor)
        boarded = False
        for call in available:
            if call[1] == floor and _sign(call[2] - call[1]) == direction:
                onboard.append(call[2])
                pending.remove(call)
                boarded = True
        if dropped or boarded:
            time += 2
            if dropped:
                last_arrival = time
            continue
        ahead = [target for target in onboard if _sign(target - floor) == direction]
        ahead += [call[1] for call in available if _sign(call[1] - floor) == direction]
        if not ahead:
            behind = [target for target in onboard if _sign(target - floor) == -direction]
            behind += [call[1] for call in available if _sign(call[1] - floor) == -direction]
            direction = -direction if behind else 0
            continue
        floor += direction
        time += 1
    return last_arrival


def describe(calls, floors, total):
    lines = ["Building with %d floors, elevator idle on floor 1" % floors]
    for moment, origin, destination in sorted(calls):
        heading = "up" if destination > origin else "down"
        lines.append("  t=%ds: floor %d -> floor %d (%s)" % (moment, origin, destination, heading))
    lines.append("  last passenger arrives at t=%ds" % total)
    return "\n".join(lines)


def main():
    scenarios = [
        ([(0, 1, 4)], 6),
        ([(0, 2, 5), (1, 3, 5), (4, 6, 1)], 6),
        ([(0, 5, 1), (2, 4, 2), (30, 1, 8)], 8),
    ]
    for calls, floors in scenarios:
        total = simulate(calls, floors)
        print(describe(calls, floors, total))


if __name__ == "__main__":
    main()

