import string

NEGATIONS = {"not", "never"}


def tokenize(text):
    """Split text into lowercase words with punctuation stripped."""
    tokens = []
    for raw in text.split():
        word = raw.strip(string.punctuation).lower()
        if word:
            tokens.append(word)
    return tokens


def build_lexicon(pairs):
    """Turn a list of (word, value) pairs into a validated dictionary."""
    table = {}
    for word, value in pairs:
        if not -5 <= value <= 5:
            raise ValueError("sentiment value out of range for %r: %d" % (word, value))
        table[word.lower()] = value
    return table


def score_tokens(tokens, table):
    """Sum sentiment values, inverting the word after a negation."""
    total = 0
    negate = False
    for token in tokens:
        if token in table:
            value = table[token]
            if negate:
                total -= value
            else:
                total += value
            negate = False
        else:
            negate = token in NEGATIONS
    return total


def score(reviews, lexicon):
    """Return the sentiment score of each review in reviews."""
    table = build_lexicon(lexicon)
    results = []
    for review in reviews:
        results.append(score_tokens(tokenize(review), table))
    return results


def report(reviews, scores):
    """Format each review with its score and a verdict label."""
    lines = []
    for review, value in zip(reviews, scores):
        if value > 0:
            verdict = "positive"
        elif value < 0:
            verdict = "negative"
        else:
            verdict = "neutral"
        lines.append("%+3d  %-9s %s" % (value, verdict, review))
    return lines


def main():
    lexicon = [
        ("bad", -3),
        ("good", 2),
        ("great", 4),
        ("broke", -4),
        ("love", 3),
        ("slow", -2),
    ]
    reviews = [
        "Not bad at all!",
        "Great sound, and I love the design.",
        "It broke after a week; very bad quality.",
        "Never good, always slow.",
        "Arrived on Tuesday.",
    ]
    for line in report(reviews, score(reviews, lexicon)):
        print(line)


if __name__ == "__main__":
    main()

