def group_fragments(fragments):
    groups = {}
    for fragment in fragments:
        msg_id, index, total, payload = fragment
        bucket = groups.setdefault(msg_id, {"total": total, "pieces": {}})
        if index not in bucket["pieces"]:
            bucket["pieces"][index] = payload
    return groups


def is_complete(bucket):
    expected = bucket["total"]
    received = bucket["pieces"]
    if len(received) != expected:
        return False
    for index in range(expected):
        if index not in received:
            return False
    return True


def join_pieces(bucket):
    pieces = bucket["pieces"]
    ordered = []
    for index in sorted(pieces):
        ordered.append(pieces[index])
    return "".join(ordered)


def reassemble(fragments):
    groups = group_fragments(fragments)
    messages = []
    for msg_id in sorted(groups):
        bucket = groups[msg_id]
        if is_complete(bucket):
            messages.append((msg_id, join_pieces(bucket)))
    return messages


def missing_indices(fragments):
