FIELDS = ("first", "last", "email", "phone")


def _normalize(record):
    if not isinstance(record, dict):
        raise TypeError("each contact must be a dictionary")
    clean = {}
    for field in FIELDS:
        value = record.get(field, "")
        if value is None:
            value = ""
        if not isinstance(value, str):
            raise TypeError("field %r must be a string" % field)
        clean[field] = value.strip()
    return clean


def _find(parent, index):
    root = index
    while parent[root] != root:
        root = parent[root]
    while parent[index] != root:
        parent[index], index = root, parent[index]
    return root


def _union(parent, left, right):
    left_root = _find(parent, left)
    right_root = _find(parent, right)
    if left_root != right_root:
        parent[max(left_root, right_root)] = min(left_root, right_root)


def _best(values):
    candidates = [value for value in values if value]
    if not candidates:
        return ""
    return min(candidates, key=lambda text: (-len(text), text))


def merge(contacts):
    records = [_normalize(record) for record in contacts]
    parent = list(range(len(records)))
    seen = {}
    for position, record in enumerate(records):
        for field in ("email", "phone"):
            key = (field, record[field].lower())
            if not record[field]:
                continue
            if key in seen:
                _union(parent, seen[key], position)
            else:
                seen[key] = position
    groups = {}
    for position in range(len(records)):
        groups.setdefault(_find(parent, position), []).append(position)
    merged = []
    for root in sorted(groups):
        members = [records[position] for position in groups[root]]
        merged.append({field: _best([m[field] for m in members]) for field in FIELDS})
    return merged


def format_contact(record):
    parts = []
    for field in FIELDS:
        value = record[field]
        if value:
            parts.append("%s=%s" % (field, value))
    if not parts:
        return "<empty record>"
    return ", ".join(parts)


