def mean(values):
    return sum(values) / len(values)


def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def stddev(values):
    average = mean(values)
    total = 0.0
    for value in values:
        total += (value - average) ** 2
    return (total / len(values)) ** 0.5


def validate(readings, window):
    if not isinstance(window, int) or isinstance(window, bool):
        raise TypeError("window must be an integer")
    if window < 2:
        raise ValueError("window must be at least 2")
    cleaned = []
    for reading in readings:
        if isinstance(reading, bool) or not isinstance(reading, (int, float)):
            raise TypeError("readings must contain numbers")
        cleaned.append(float(reading))
    return cleaned


def filter(readings, window):
    corrected = validate(readings, window)
    for index in range(window, len(corrected)):
        history = corrected[index - window:index]
        spread = stddev(history)
        if spread == 0.0:
            continue
        if abs(corrected[index] - mean(history)) > 2 * spread:
            corrected[index] = median(history)
    return corrected


def report(original, corrected):
    lines = []
    for index in range(len(original)):
        raw = float(original[index])
        clean = corrected[index]
        if raw != clean:
            lines.append("{0:3d}  {1:8.2f} -> {2:8.2f}  ANOMALY".format(index, raw, clean))
        else:
            lines.append("{0:3d}  {1:8.2f}".format(index, raw))
    return lines


def main():
    series = [20.1, 20.4, 20.2, 20.3, 20.5, 20.2, 45.0, 20.6,
              20.4, 20.5, 20.3, -12.0, 20.4, 20.7, 20.6, 20.5]
    window = 5
    corrected = filter(series, window)
    print("window size: {0}".format(window))
    for line in report(series, corrected):
        print(line)
    anomalies = 0
    for index in range(len(series)):
        if series[index] != corrected[index]:
            anomalies += 1
    print("anomalies corrected: {0}".format(anomalies))
    print("mean before: {0:.3f}".format(mean(series)))
    print("mean after:  {0:.3f}".format(mean(corrected)))


if __name__ == "__main__":
    main()

