def validate(items, capacity):
    """Check that the weights and capacity form a solvable packing problem."""
    if not isinstance(capacity, int) or capacity <= 0:
        raise ValueError("capacity must be a positive integer")
    for weight in items:
        if not isinstance(weight, int):
            raise TypeError("item weights must be integers")
        if weight <= 0:
            raise ValueError("item weights must be positive")
        if weight > capacity:
            raise ValueError("item of weight %d exceeds capacity %d" % (weight, capacity))


def fill_bins(items, capacity):
    """Return the list of bin loads produced by first-fit decreasing packing."""
    loads = []
    for weight in sorted(items, reverse=True):
        placed = False
        for index in range(len(loads)):
            if loads[index] + weight <= capacity:
                loads[index] += weight
                placed = True
                break
        if not placed:
            loads.append(weight)
    return loads


def classify(loads, capacity):
    """Count bins that are full, at least half full, and less than half full."""
    full = 0
    half = 0
    sparse = 0
    for load in loads:
        if load == capacity:
            full += 1
        elif load * 2 >= capacity:
            half += 1
        else:
            sparse += 1
    return full, half, sparse


def pack(items, capacity):
    validate(items, capacity)
    return classify(fill_bins(items, capacity), capacity)


def format_report(items, capacity):
    """Build a human readable summary of one packing run."""
    full, half, sparse = pack(items, capacity)
    loads = fill_bins(items, capacity)
    lines = ["capacity %d, %d items, %d bins used" % (capacity, len(items), len(loads))]
    for index, load in enumerate(loads, start=1):
        percent = 100.0 * load / capacity
        lines.append("    bin %d: load %d (%.1f%%)" % (index, load, percent))
    lines.append("    full=%d half=%d sparse=%d" % (full, half, sparse))
    return "\n".join(lines)


def main():
    cases = [
        ([4, 8, 1, 4, 2, 1], 10),
        ([9, 8, 2, 2, 5, 4], 10),
        ([2, 5, 4, 7, 1, 3, 8], 10),
        ([1, 1, 1, 1], 8),
    ]
    for items, capacity in cases:
        print(format_report(items, capacity))
    totals = [0, 0, 0]
    for items, capacity in cases:
        for position, count in enumerate(pack(items, capacity)):
            totals[position] += count
    print("overall full=%d half=%d sparse=%d" % tuple(totals))


if __name__ == "__main__":
    main()

