DIRECTIONS = ("north", "south", "east", "west")
PHASE_LENGTH = 20


def green_directions(second):
    """Return the pair of approaches holding a green light at `second`."""
    if (second // PHASE_LENGTH) % 2 == 0:
        return ("north", "south")
    return ("east", "west")


def parse_vehicles(vehicles):
    """Group arrivals into {arrival_second: [direction, ...]} after validation."""
    schedule = {}
    for item in vehicles:
        arrival, direction = item
        arrival = int(arrival)
        if arrival < 0:
            raise ValueError("arrival times cannot be negative: %d" % arrival)
        name = str(direction).strip().lower()
        if name not in DIRECTIONS:
            raise ValueError("unknown approach direction: %r" % (direction,))
        schedule.setdefault(arrival, []).append(name)
    return schedule


def direct(vehicles, duration):
    """Simulate the intersection and return (cars_passed, cars_still_waiting)."""
    if duration < 0:
        raise ValueError("duration cannot be negative")
    schedule = parse_vehicles(vehicles)
    queues = dict.fromkeys(DIRECTIONS, 0)
    passed = 0
    for second in range(duration):
        for direction in green_directions(second):
            if queues[direction] > 0:
                queues[direction] -= 1
                passed += 1
        for direction in schedule.get(second, ()):
            queues[direction] += 1
    return passed, sum(queues.values())


def phase_plan(duration):
    """List the (start, end, directions) light phases covering the simulation."""
    plan = []
    second = 0
    while second < duration:
        end = min(second + PHASE_LENGTH, duration)
        plan.append((second, end, green_directions(second)))
        second = end
    return plan


def format_report(vehicles, duration):
    passed, waiting = direct(vehicles, duration)
    late = 0
    for arrival, _direction in vehicles:
        if arrival >= duration:
            late += 1
    lines = ["Intersection report: %d vehicles, %d seconds" % (len(vehicles), duration)]
    for start, end, dirs in phase_plan(duration):
        lines.append("  %4d-%-4d green: %s" % (start, end, " & ".join(dirs)))
    lines.append("  passed through: %d" % passed)
    lines.append("  still waiting:  %d" % waiting)
    if late:
        lines.append("  arriving after the simulation ended: %d" % late)
    return "\n".join(lines)


def main():
    traffic = []
    for second in range(0, 60, 3):
        traffic.append((second, "north"))
        traffic.append((second, "east"))
    traffic.extend([(5, "south"), (7, "south"), (41, "west"), (75, "north")])
    print(format_report(traffic, 60))
    print(direct(traffic, 60))


if __name__ == "__main__":
    main()

