def validate(pieces):
    """Check that every entry is a known piece on a free square of the board."""
    allowed = ("rook", "bishop", "knight", "queen")
    occupied = set()
    for entry in pieces:
        if len(entry) != 3:
            raise ValueError("each piece needs a type, a row and a column: %r" % (entry,))
        kind, row, col = entry
        if kind not in allowed:
            raise ValueError("unknown piece type: %r" % (kind,))
        if not (0 <= row < 8 and 0 <= col < 8):
            raise ValueError("square out of the board: (%r, %r)" % (row, col))
        if (row, col) in occupied:
            raise ValueError("two pieces on the same square: (%r, %r)" % (row, col))
        occupied.add((row, col))


def attacks(kind, origin, target):
