def normalize_coupon(coupon):
    """Turn a coupon record into a (kind, value, minimum) tuple."""
    if isinstance(coupon, dict):
        kind = coupon.get("type", coupon.get("kind"))
        value = coupon.get("value", coupon.get("amount"))
        minimum = coupon.get("minimum", coupon.get("min_total", 0))
    else:
        kind, value, minimum = coupon
    kind = str(kind).strip().lower()
    if kind not in ("flat", "percentage"):
        raise ValueError("unknown discount type: {!r}".format(kind))
    value = float(value)
    minimum = float(minimum or 0)
    if value < 0 or minimum < 0:
        raise ValueError("coupon values must not be negative")
    if kind == "percentage" and value > 100:
        raise ValueError("percentage discount above 100 is not allowed")
    return kind, value, minimum


def eligible_coupons(coupons, subtotal):
    """Split usable coupons into flat and percentage groups."""
    flats = []
    percents = []
    for coupon in coupons:
        kind, value, minimum = normalize_coupon(coupon)
        if minimum > subtotal:
            continue
        if kind == "flat":
            flats.append(value)
        else:
            percents.append(value)
    return flats, percents


def apply_discounts(subtotal, flat, percent):
    total = subtotal - flat
    if total < 0:
        total = 0.0
    total -= total * percent / 100.0
    return total


def checkout(cart, coupons):
    subtotal = 0.0
    for price in cart:
        price = float(price)
        if price < 0:
            raise ValueError("item prices must not be negative")
        subtotal += price
    flats, percents = eligible_coupons(coupons, subtotal)
    flats.append(0.0)
    percents.append(0.0)
    best = subtotal
    for flat in flats:
        for percent in percents:
            candidate = apply_discounts(subtotal, flat, percent)
            if candidate < best:
                best = candidate
    return round(best, 2)


def describe_basket(cart, coupons):
    subtotal = round(sum(float(p) for p in cart), 2)
    final = checkout(cart, coupons)
    saved = round(subtotal - final, 2)
    lines = ["{} item(s), subtotal {:.2f}".format(len(cart), subtotal)]
    for coupon in coupons:
        kind, value, minimum = normalize_coupon(coupon)
        if minimum > subtotal:
            lines.append("  rejected {} {:g} (needs {:.2f})".format(kind, value, minimum))
        else:
            lines.append("  usable   {} {:g}".format(kind, value))
    lines.append("pay {:.2f} (saved {:.2f})".format(final, saved))
    return "\n".join(lines)


def main():
    baskets = [
        ([19.99, 5.50, 30.00], [("flat", 10, 40), ("percentage", 15, 50), ("flat", 5, 20)]),
        ([8.00, 2.25], [{"type": "percentage", "value": 25, "minimum": 5}]),
        ([100.0], [("flat", 120, 50)]),
    ]
    for cart, coupons in baskets:
        print(describe_basket(cart, coupons))
        print("-" * 32)


if __name__ == "__main__":
    main()

