BASE_FARE = 2.50
ZONE_FARE = 1.25


def build_zone_map(stations):
    """Map each stop name to its geographic zone."""
    zones = {}
    for entry in stations:
        name, zone = entry[0], entry[1]
        zones[name] = int(zone)
    return zones


def trip_price(zones, start, end):
    """Price a single trip, or 0.0 if either stop is unknown."""
    if start not in zones or end not in zones:
        return 0.0
    boundaries = abs(zones[start] - zones[end])
    return BASE_FARE + boundaries * ZONE_FARE


def fare(stations, journeys):
    """Return the price of every journey in the given list."""
    zones = build_zone_map(stations)
    prices = []
    for journey in journeys:
        start, end = journey[0], journey[1]
        prices.append(trip_price(zones, start, end))
    return prices


def unknown_stops(stations, journeys):
    """Collect the stop names used by journeys but missing from stations."""
    zones = build_zone_map(stations)
    missing = []
    for journey in journeys:
        for name in (journey[0], journey[1]):
            if name not in zones and name not in missing:
                missing.append(name)
    return missing


def format_report(stations, journeys):
    """Build a readable per-journey report plus a summary total."""
    prices = fare(stations, journeys)
    lines = []
    total = 0.0
    for journey, price in zip(journeys, prices):
        label = "{} -> {}".format(journey[0], journey[1])
        if price == 0.0:
            lines.append("{:<28} invalid".format(label))
        else:
            lines.append("{:<28} ${:.2f}".format(label, price))
            total += price
    lines.append("{:<28} ${:.2f}".format("TOTAL", total))
    for name in unknown_stops(stations, journeys):
        lines.append("unknown stop: {}".format(name))
    return "\n".join(lines)


def main():
    stations = [
        ("Central", 1),
        ("Riverside", 1),
        ("Hilltop", 2),
        ("Fernwood", 3),
        ("Longview", 5),
    ]
    journeys = [
        ("Central", "Riverside"),
        ("Central", "Hilltop"),
        ("Riverside", "Longview"),
        ("Fernwood", "Central"),
        ("Central", "Seaside"),
    ]
    print(format_report(stations, journeys))


if __name__ == "__main__":
    main()

