import math


CHILD_AGE_LIMIT = 12
SENIOR_AGE_LIMIT = 65
STANDARD_RATE = 80
CHILD_RATE = 40
SENIOR_RATE = 50
DISCOUNT_DAYS = 3
DISCOUNT_FACTOR = 0.9


def daily_rate(age):
    """Return the price of a single daily pass for a skier of the given age."""
    if age < CHILD_AGE_LIMIT:
        return CHILD_RATE
    if age > SENIOR_AGE_LIMIT:
        return SENIOR_RATE
    return STANDARD_RATE


def category(age):
    """Return a human readable name for the price category of an age."""
    if age < CHILD_AGE_LIMIT:
        return "child"
    if age > SENIOR_AGE_LIMIT:
        return "senior"
    return "adult"


def check_skier(entry):
    """Validate one (age, days) pair and return it as a pair of ints."""
    if len(entry) != 2:
        raise ValueError("each skier must be a pair of (age, days)")
    age, days = entry
    if not isinstance(age, int) or not isinstance(days, int):
        raise ValueError("age and days must be integers")
    if age < 0:
        raise ValueError("age cannot be negative")
    if days < 1:
        raise ValueError("a skier must ski at least one day")
    return age, days


def price_for(age, days):
    """Cost for a single skier, discounted for long stays, rounded down."""
    total = daily_rate(age) * days
    if days >= DISCOUNT_DAYS:
        total *= DISCOUNT_FACTOR
    return math.floor(total)


def evaluate(skiers):
    """Return the list of final lift pass prices, one per skier."""
    prices = []
    for entry in skiers:
        age, days = check_skier(entry)
        prices.append(price_for(age, days))
    return prices


def report(skiers):
    """Build a per-skier summary followed by the total takings."""
    prices = evaluate(skiers)
    lines = []
    for (age, days), price in zip(skiers, prices):
        label = "{:>6} aged {:>3}, {:>2} day(s): {:>5}".format(
            category(age), age, days, price)
        if days >= DISCOUNT_DAYS:
            label += "  (10% off)"
        lines.append(label)
    lines.append("total: {}".format(sum(prices)))
    return "\n".join(lines)


def main():
    groups = [(10, 1), (30, 4), (70, 2)]
    print(evaluate(groups))
    print(report(groups))


if __name__ == "__main__":
    main()

