RATES = {"economy": 30, "sedan": 40, "suv": 50}
YOUNG_DRIVER_AGE = 25
YOUNG_DRIVER_SURCHARGE = 15
LONG_RENTAL_DAYS = 7
LONG_RENTAL_DISCOUNT = 20


def validate_rental(rental):
    """Check a single rental tuple and return its normalised parts."""
    if len(rental) != 3:
        raise ValueError("each rental needs a car type, day count and driver age")
    car_type, days, age = rental
    key = str(car_type).strip().lower()
    if key not in RATES:
        raise ValueError("unknown car type: {}".format(car_type))
    if not isinstance(days, int) or isinstance(days, bool):
        raise ValueError("rental days must be an integer")
    if days < 1:
        raise ValueError("rental days must be at least one")
    if not isinstance(age, int) or isinstance(age, bool):
        raise ValueError("driver age must be an integer")
    if age < 18:
        raise ValueError("drivers must be at least eighteen years old")
    return key, days, age


def price_rental(car_type, days, age):
    """Price one validated rental."""
    daily = RATES[car_type]
    if age < YOUNG_DRIVER_AGE:
        daily += YOUNG_DRIVER_SURCHARGE
    total = daily * days
    if days >= LONG_RENTAL_DAYS:
        total -= LONG_RENTAL_DISCOUNT
    return total


def quote(rentals):
    """Return a list of quoted prices, one per rental in the input list."""
    prices = []
    for rental in rentals:
        car_type, days, age = validate_rental(rental)
        prices.append(price_rental(car_type, days, age))
    return prices


def format_report(rentals, prices):
    """Build a readable line per rental plus a grand total line."""
    lines = []
    for rental, price in zip(rentals, prices):
        car_type, days, age = validate_rental(rental)
        notes = []
        if age < YOUNG_DRIVER_AGE:
            notes.append("young driver surcharge")
        if days >= LONG_RENTAL_DAYS:
            notes.append("long rental discount")
        label = "{:<8} {:>2} day(s) age {:>2}".format(car_type, days, age)
        if notes:
            lines.append("{}: {:>5} ({})".format(label, price, ", ".join(notes)))
        else:
            lines.append("{}: {:>5}".format(label, price))
    lines.append("{:<22} {:>5}".format("TOTAL", sum(prices)))
    return "\n".join(lines)


def main():
    rentals = [("economy", 3, 22), ("suv", 7, 40), ("sedan", 10, 21), ("sedan", 1, 30)]
    prices = quote(rentals)
    print(prices)
    print(format_report(rentals, prices))
    try:
        quote([("truck", 2, 30)])
    except ValueError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

