BASE_POINTS = {"farmer": 2, "noble": 5, "merchant": 1}
BONUS_MERCHANT_POINTS = 3
CARD_TYPES = ("farmer", "noble", "merchant")


def count_cards(hand):
    """Return a mapping from card type to the number of copies in the hand."""
    counts = {card_type: 0 for card_type in CARD_TYPES}
    for card in hand:
        if card not in counts:
            raise ValueError("unknown card type: {!r}".format(card))
        counts[card] += 1
    return counts


def has_full_set(counts):
    """True when every card type appears at least once."""
    for card_type in CARD_TYPES:
        if counts[card_type] == 0:
            return False
    return True


def score_hand(hand):
    """Score a single hand, applying the merchant bonus when it is earned."""
    counts = count_cards(hand)
    merchant_value = BASE_POINTS["merchant"]
    if has_full_set(counts):
        merchant_value = BONUS_MERCHANT_POINTS
    total = counts["merchant"] * merchant_value
    for card_type in ("farmer", "noble"):
        total += counts[card_type] * BASE_POINTS[card_type]
    return total


def score(hands):
    """Return the list of totals, one per hand."""
    totals = []
    for hand in hands:
        totals.append(score_hand(hand))
    return totals


def format_report(hands):
    """Build human readable lines describing each hand and the grand total."""
    lines = []
    totals = score(hands)
    for index, hand in enumerate(hands, start=1):
        counts = count_cards(hand)
        parts = []
        for card_type in CARD_TYPES:
            if counts[card_type] > 0:
                parts.append("{} {}".format(counts[card_type], card_type))
        description = ", ".join(parts)
        if not description:
            description = "empty hand"
        note = ""
        if has_full_set(counts):
            note = " (merchant bonus)"
        lines.append("Player {}: {} -> {} points{}".format(
            index, description, totals[index - 1], note))
    lines.append("Grand total: {} points".format(sum(totals)))
    return lines


def main():
    games = [
        [["farmer", "farmer"], ["merchant", "farmer", "noble", "merchant"]],
        [["noble", "noble", "merchant"], [], ["merchant", "merchant"]],
    ]
    for number, hands in enumerate(games, start=1):
        print("Game {}".format(number))
        for line in format_report(hands):
            print("  " + line)
        print("  scores: {}".format(score(hands)))


if __name__ == "__main__":
    main()

