def recipe_for(name):
    """Return the (beans, milk, chocolate) cost of a drink name."""
    recipes = {
        "espresso": (1, 0, 0),
        "latte": (1, 1, 0),
        "mocha": (1, 1, 1),
    }
    key = name.strip().lower()
    if key not in recipes:
        raise ValueError("unknown drink: {!r}".format(name))
    return recipes[key]


INITIAL_STOCK = (10, 5, 2)

INGREDIENT_NAMES = ("beans", "milk", "chocolate")


def can_brew(stock, cost):
    """True when every ingredient in stock covers the matching cost."""
    for have, need in zip(stock, cost):
        if have < need:
            return False
    return True


def consume(stock, cost):
    """Subtract a recipe cost from the current stock tuple."""
    return tuple(have - need for have, need in zip(stock, cost))


def brew(orders):
    stock = INITIAL_STOCK
    brewed = 0
    for order in orders:
        cost = recipe_for(order)
        if can_brew(stock, cost):
            stock = consume(stock, cost)
            brewed += 1
    return brewed, stock


def describe_queue(orders):
    """Summarise the queue as 'count x drink' entries in first-seen order."""
    tally = {}
    sequence = []
    for order in orders:
        key = order.strip().lower()
        if key not in tally:
            tally[key] = 0
            sequence.append(key)
        tally[key] += 1
    return ", ".join("{} x {}".format(tally[key], key) for key in sequence)


def report(orders):
    """Build a human readable summary of a completed brewing run."""
    brewed, stock = brew(orders)
    lines = ["Queue: " + describe_queue(orders)]
    lines.append("Brewed {} of {} drinks".format(brewed, len(orders)))
    for name, amount in zip(INGREDIENT_NAMES, stock):
        if amount == 0:
            lines.append("  {}: out of stock".format(name))
        else:
            lines.append("  {}: {} units left".format(name, amount))
    return "\n".join(lines)


def main():
    queues = [
        ["mocha", "mocha", "mocha", "espresso"],
        ["latte", "latte", "latte", "latte", "latte", "latte"],
        ["espresso"] * 12,
    ]
    for queue in queues:
        print(report(queue))
        print(brew(queue))
        print()


if __name__ == "__main__":
    main()

