FUEL_RATES = {"thrust": 10, "rotate": 2, "stabilize": 1}
INITIAL_FUEL = 1000


def fuel_cost(action, duration):
    """Return the fuel needed for one maneuver, validating its fields."""
    if action not in FUEL_RATES:
        raise ValueError("unknown action: {!r}".format(action))
    if not isinstance(duration, int) or isinstance(duration, bool):
        raise TypeError("duration must be an integer, got {!r}".format(duration))
    if duration < 0:
        raise ValueError("duration must not be negative: {}".format(duration))
    return FUEL_RATES[action] * duration


def monitor(maneuvers):
    """Run the maneuvers in order and report (successful count, fuel left)."""
    fuel = INITIAL_FUEL
    completed = 0
    for action, duration in maneuvers:
        cost = fuel_cost(action, duration)
        if cost > fuel:
            break
        fuel -= cost
        completed += 1
    return completed, fuel


def flight_log(maneuvers):
    """Build a per-maneuver log of the same flight, including aborted steps."""
    fuel = INITIAL_FUEL
    entries = []
    aborted = False
    for action, duration in maneuvers:
        cost = fuel_cost(action, duration)
        if aborted or cost > fuel:
            aborted = True
            entries.append((action, duration, cost, None, "skipped"))
        else:
            fuel -= cost
            entries.append((action, duration, cost, fuel, "executed"))
    return entries


def format_log(entries):
    """Render a flight log as aligned, human readable text lines."""
    lines = []
    for index, (action, duration, cost, fuel, status) in enumerate(entries, start=1):
        head = "{:>2}. {:<9} {:>4}s  cost {:>5}".format(index, action, duration, cost)
        if fuel is None:
            lines.append("{}  --  {}".format(head, status))
        else:
            lines.append("{}  fuel {:>5}  {}".format(head, fuel, status))
    return lines


def main():
    flights = [
        [("thrust", 50), ("rotate", 100), ("thrust", 100)],
        [("stabilize", 300), ("rotate", 200), ("thrust", 40), ("rotate", 10)],
        [("thrust", 200)],
    ]
    for number, maneuvers in enumerate(flights, start=1):
        completed, fuel = monitor(maneuvers)
        print("Flight {}: {} maneuvers completed, {} fuel remaining".format(
            number, completed, fuel))
        for line in format_log(flight_log(maneuvers)):
            print("    " + line)
        if fuel == 0:
            print("    warning: tanks are empty")


if __name__ == "__main__":
    main()

