import math


def validate_package(package):
    """Check that a package tuple has the shape (distance, weight, priority)."""
    if not isinstance(package, tuple) or len(package) != 3:
        raise ValueError("each package must be a 3-tuple (distance, weight, priority)")
    distance, weight, priority = package
    for name, value in (("distance", distance), ("weight", weight)):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("{0} must be an integer".format(name))
        if value < 0:
            raise ValueError("{0} must not be negative".format(name))
    if not isinstance(priority, bool):
        raise TypeError("priority flag must be a boolean")
    return distance, weight, priority


def distance_days(distance, priority):
    """Days needed to cover the distance, one per full or partial hundred miles."""
    days = math.ceil(distance / 100)
    if priority:
        days = math.ceil(days / 2)
    return days


def surcharge_days(distance, weight):
    """Extra processing and long haul days added on top of the transit time."""
    extra = 0
    if weight > 50:
        extra += 1
    if distance > 1000:
        extra += 2
    return extra


def estimate(packages):
    """Return the estimated delivery time in whole days for each package."""
    results = []
    for package in packages:
        distance, weight, priority = validate_package(package)
        days = distance_days(distance, priority) + surcharge_days(distance, weight)
        results.append(days)
    return results


def format_report(packages, days):
    """Build one human readable line per package plus a summary line."""
    lines = []
    for package, total in zip(packages, days):
        distance, weight, priority = package
        service = "priority" if priority else "standard"
        notes = []
        if weight > 50:
            notes.append("heavy")
        if distance > 1000:
            notes.append("long haul")
        suffix = " ({0})".format(", ".join(notes)) if notes else ""
        lines.append(
            "{0:>5} mi {1:>4} lb {2:<8} -> {3:>2} day(s){4}".format(
                distance, weight, service, total, suffix
            )
        )
    if days:
        lines.append("slowest shipment: {0} day(s)".format(max(days)))
    return "\n".join(lines)


def main():
    shipments = [(250, 10, False), (400, 60, True), (1200, 20, False)]
    days = estimate(shipments)
    print(days)
    print(format_report(shipments, days))


if __name__ == "__main__":
    main()

