ROWS = 5
SEATS_PER_ROW = 10


def validate_groups(raw):
    """Return the group sizes as a clean list of positive integers."""
    cleaned = []
    for item in raw:
        if isinstance(item, bool) or not isinstance(item, int):
            raise TypeError(f"group size must be an integer, got {item!r}")
        if item < 1:
            raise ValueError(f"group size must be positive, got {item}")
        cleaned.append(item)
    return cleaned


def find_row(rows, size):
    """Index of the first row with `size` adjacent free seats, or -1."""
    for index, used in enumerate(rows):
        if SEATS_PER_ROW - used >= size:
            return index
    return -1


def fill_rows(sizes):
    """Seat the groups, returning the row occupancy and every placement."""
    rows = [0] * ROWS
    placements = []
    for size in sizes:
        if size > SEATS_PER_ROW:
            placements.append((size, -1))
            continue
        row = find_row(rows, size)
        if row >= 0:
            rows[row] += size
        placements.append((size, row))
    return rows, placements


def seat(groups):
    rows, placements = fill_rows(validate_groups(groups))
    seated = 0
    for _size, row in placements:
        if row >= 0:
            seated += 1
    empty = ROWS * SEATS_PER_ROW - sum(rows)
    return seated, empty


def format_layout(rows):
    """Render each row as taken ('#') and free ('.') seats."""
    lines = []
    for index, used in enumerate(rows):
        free = SEATS_PER_ROW - used
        lines.append(f"row {index + 1}: {'#' * used}{'.' * free}")
    return lines


def main():
    arrivals = [4, 5, 2, 8, 12, 3]
    seated, empty = seat(arrivals)
    print(f"arrivals: {arrivals}")
    print(f"result: {(seated, empty)}")
    rows, placements = fill_rows(validate_groups(arrivals))
    for size, row in placements:
        if row < 0:
            print(f"group of {size} turned away")
        else:
            print(f"group of {size} seated in row {row + 1}")
    for line in format_layout(rows):
        print(line)


if __name__ == "__main__":
    main()

