def score(minutes, clues):
    """Return the final point total for a team's run."""
    points = 1000 - 10 * minutes - 50 * clues
    if minutes < 30:
        points += 200
    return points


def validate(entry):
    """Check one raw entry and return it as a (name, minutes, clues) tuple."""
    if len(entry) != 3:
        raise ValueError("each team entry needs a name, minutes and clues")
    name, minutes, clues = entry
    if not isinstance(name, str) or not name.strip():
        raise ValueError("team name must be a non-empty string")
    if not isinstance(minutes, int) or not isinstance(clues, int):
        raise TypeError("minutes and clues must be integers")
    if minutes < 0 or clues < 0:
        raise ValueError("minutes and clues cannot be negative")
    return (name.strip(), minutes, clues)


def scoreboard(teams):
    """Build a list of (name, points) pairs sorted from best to worst."""
    results = []
    for entry in teams:
        name, minutes, clues = validate(entry)
        results.append((name, score(minutes, clues)))
    results.sort(key=lambda pair: (-pair[1], pair[0]))
    return results


def rank(teams):
    """Return team names ordered from highest final score to lowest."""
    return [name for name, _points in scoreboard(teams)]


def placings(teams):
    """Return (place, name, points) rows where tied scores share a place."""
    rows = []
    previous_points = None
    place = 0
    for index, (name, points) in enumerate(scoreboard(teams), start=1):
        if points != previous_points:
            place = index
            previous_points = points
        rows.append((place, name, points))
    return rows


def report(teams):
    """Format the placings as a printable table."""
    rows = placings(teams)
    if not rows:
        return "no teams competed"
    width = max(len(name) for _place, name, _points in rows)
    lines = []
    for place, name, points in rows:
        lines.append("{:>2}. {:<{w}}  {:>5} pts".format(place, name, points, w=width))
    return "\n".join(lines)


def main():
    challenge = [
        ("alpha", 45, 2),
        ("beta", 25, 3),
        ("gamma", 29, 0),
        ("delta", 60, 1),
        ("epsilon", 45, 2),
    ]
    print(report(challenge))
    winners = rank(challenge)
    print("winner:", winners[0])
    for name, points in scoreboard(challenge):
        if points < 500:
            print("{} needs more practice ({} pts)".format(name, points))


if __name__ == "__main__":
    main()

