def plant(seeds):
    """Fill one bed in order; return (planted count, leftover count)."""
    names = normalize(seeds)
    used = 0
    planted = 0
    for name in names:
        size = PLANT_SIZES[name]
        if used + size > BED_CAPACITY:
            break
        used += size
        planted += 1
    return planted, len(names) - planted


BED_CAPACITY = 8

PLANT_SIZES = {
    "tomato": 3,
    "carrot": 1,
    "bean": 2,
}


def normalize(seeds):
    """Return a cleaned list of lower-case plant names, rejecting unknown ones."""
    cleaned = []
    for seed in seeds:
        if not isinstance(seed, str):
            raise TypeError("plant names must be strings, got %r" % (seed,))
        name = seed.strip().lower()
        if name not in PLANT_SIZES:
            raise ValueError("unknown plant type: %r" % (seed,))
        cleaned.append(name)
    return cleaned


def space_used(seeds):
    """Total units occupied by the plants that actually made it into the bed."""
    names = normalize(seeds)
    planted = plant(names)[0]
    return sum(PLANT_SIZES[name] for name in names[:planted])


def describe(seeds):
    """Build a one-line summary of how a bed turns out."""
    planted, leftover = plant(seeds)
    used = space_used(seeds)
    parts = ["%d planted" % planted, "%d left over" % leftover]
    if used < BED_CAPACITY:
        parts.append("%d unit(s) of bare dirt" % (BED_CAPACITY - used))
    else:
        parts.append("bed full")
    return ", ".join(parts)


def main():
    beds = [
        ["tomato", "bean", "tomato", "carrot", "bean"],
        ["carrot", "Carrot", " bean ", "bean", "carrot", "tomato"],
        ["tomato", "tomato", "tomato"],
        [],
        ["bean", "parsnip"],
    ]
    for index, bed in enumerate(beds, start=1):
        try:
            summary = describe(bed)
        except (TypeError, ValueError) as error:
            summary = "rejected (%s)" % error
        print("Bed %d: %s -> %s" % (index, bed, summary))


if __name__ == "__main__":
    main()

