import sys

VALID_SPECIES = ("cat", "dog")


def cups_for_cat(weight):
    """Cups needed by one cat: one per full five pounds."""
    return weight // 5


def cups_for_dog(weight):
    """Cups needed by one dog: one per full ten pounds, plus one if over fifty."""
    cups = weight // 10
    if weight > 50:
        cups += 1
    return cups


def validate_pet(pet):
    """Return a (species, weight) pair, raising ValueError on bad data."""
    if len(pet) != 2:
        raise ValueError("each pet must be a (species, weight) pair, got %r" % (pet,))
    species, weight = pet
    if species not in VALID_SPECIES:
        raise ValueError("unknown species %r" % (species,))
    if not isinstance(weight, int) or isinstance(weight, bool):
        raise ValueError("weight of %s must be an integer, got %r" % (species, weight))
    if weight < 0:
        raise ValueError("weight of %s cannot be negative" % (species,))
    return species, weight


def feed(pets):
    """Total cups of (cat food, dog food) required for one day."""
    cat_cups = 0
    dog_cups = 0
    for pet in pets:
        species, weight = validate_pet(pet)
        if species == "cat":
            cat_cups += cups_for_cat(weight)
        else:
            dog_cups += cups_for_dog(weight)
    return cat_cups, dog_cups


def parse_pet(text):
    """Turn a 'species,weight' line into a tuple usable by feed()."""
    parts = text.split(",")
    if len(parts) != 2:
        raise ValueError("expected 'species,weight' but got %r" % (text,))
    species = parts[0].strip().lower()
    try:
        weight = int(parts[1].strip())
    except ValueError:
        raise ValueError("weight %r is not a whole number of pounds" % (parts[1].strip(),))
    return species, weight


def read_pets(stream):
    """Collect pets from a text stream, ignoring blank lines and comments."""
    pets = []
    for line in stream:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        pets.append(parse_pet(line))
    return pets


def format_report(cat_cups, dog_cups):
    lines = ["Cat food: %d cup(s)" % cat_cups, "Dog food: %d cup(s)" % dog_cups]
    lines.append("Total:    %d cup(s)" % (cat_cups + dog_cups))
    return "\n".join(lines)


def main():
    try:
        pets = read_pets(sys.stdin)
    except ValueError as err:
        print("input error: %s" % err, file=sys.stderr)
        return 1
    cat_cups, dog_cups = feed(pets)
    print(format_report(cat_cups, dog_cups))
    return 0


if __name__ == "__main__":
    sys.exit(main())

