def is_vulnerable(age):
    """Children under twelve and seniors over sixty five are vulnerable."""
    return age < 12 or age > 65


def validate_patient(record):
    """Unpack one waiting-room record, raising ValueError on bad input."""
    if len(record) != 4:
        raise ValueError("each patient needs name, age, severity, arrival")
    name, age, severity, arrival = record
    if not isinstance(name, str) or not name.strip():
        raise ValueError("patient name must be a non-empty string")
    if not isinstance(age, int) or age < 0:
        raise ValueError("age must be a non-negative whole number for " + name)
    if not isinstance(severity, int) or not 1 <= severity <= 10:
        raise ValueError("severity must be between 1 and 10 for " + name)
    if not isinstance(arrival, (int, float)) or arrival < 0:
        raise ValueError("arrival time must be non-negative for " + name)
    return name.strip(), age, severity, arrival


def triage_key(record):
    """Sort key: high severity first, then vulnerable ages, then early arrival."""
    name, age, severity, arrival = record
    vulnerability_rank = 0 if is_vulnerable(age) else 1
    return (-severity, vulnerability_rank, arrival, name)


def triage(patients):
    """Return patient names in the order medical staff should see them."""
    cleaned = []
    for record in patients:
        cleaned.append(validate_patient(record))
    cleaned.sort(key=triage_key)
    return [record[0] for record in cleaned]


def group_by_severity(patients):
    """Map each severity score to the names waiting at that score."""
    groups = {}
    for record in patients:
        name, age, severity, arrival = validate_patient(record)
        if severity not in groups:
            groups[severity] = []
        groups[severity].append(name)
    return groups


def format_queue(patients):
    """Build a human readable call list for the waiting room display."""
    order = triage(patients)
    lookup = {}
    for record in patients:
        name, age, severity, arrival = validate_patient(record)
        lookup[name] = (age, severity, arrival)
    lines = []
    for position, name in enumerate(order, start=1):
        age, severity, arrival = lookup[name]
        note = "priority age" if is_vulnerable(age) else "standard age"
        lines.append(
            "{0}. {1} (age {2}, severity {3}, waiting {4} min) - {5}".format(
                position, name, age, severity, arrival, note
            )
        )
    return "\n".join(lines)


def main():
    waiting_room = [
        ("Ada", 34, 7, 12),
        ("Ben", 8, 7, 40),
        ("Cleo", 70, 7, 5),
        ("Dai", 50, 9, 30),
        ("Eve", 19, 4, 2),
        ("Finn", 67, 4, 55),
    ]
    print(format_queue(waiting_room))
    print()
    for severity in sorted(group_by_severity(waiting_room), reverse=True):
        names = group_by_severity(waiting_room)[severity]
        print("severity {0}: {1}".format(severity, ", ".join(sorted(names))))


if __name__ == "__main__":
    main()

