CAPACITY = 50000


def validate(demands):
    """Check the raw input and return a cleaned list of (name, distance, request)."""
    cleaned = []
    for entry in demands:
        if len(entry) != 3:
            raise ValueError("each demand needs a name, a distance and a request")
        name, distance, request = entry
        if not str(name).strip():
            raise ValueError("city name must not be empty")
        if distance < 0:
            raise ValueError("distance to %s cannot be negative" % name)
        if request < 0:
            raise ValueError("power request of %s cannot be negative" % name)
        cleaned.append((str(name).strip(), distance, request))
    return cleaned


def distribute(demands):
    """Allocate up to CAPACITY megawatts, nearest cities first."""
    cities = sorted(validate(demands), key=lambda c: c[1])
    remaining = CAPACITY
    allocation = []
    for name, _distance, request in cities:
        if request <= remaining:
            granted = request
        else:
            granted = remaining
        remaining -= granted
        allocation.append((name, granted))
    return allocation


def shortfalls(demands, allocation):
    """Return the unmet megawatts per city, keyed by name."""
    requested = {}
    for name, _distance, request in validate(demands):
        requested[name] = requested.get(name, 0) + request
    missing = {}
    for name, granted in allocation:
        gap = requested[name] - granted
        if gap > 0:
            missing[name] = gap
    return missing


def report(demands, allocation):
    """Build a human readable summary of the distribution."""
    lines = []
    total = 0
    missing = shortfalls(demands, allocation)
    for name, granted in allocation:
        total += granted
        if name in missing:
            note = " (short %d MW)" % missing[name]
        else:
            note = ""
        lines.append("%-12s %6d MW%s" % (name, granted, note))
    lines.append("%-12s %6d MW of %d MW capacity" % ("TOTAL", total, CAPACITY))
    if total < CAPACITY:
        lines.append("Spare capacity: %d MW" % (CAPACITY - total))
    return "\n".join(lines)


def main():
    demands = [
        ("Farhaven", 410, 12000),
        ("Nearby", 15, 8000),
        ("Midtown", 120, 21000),
        ("Riverside", 60, 15000),
        ("Hilltop", 250, 5000),
    ]
    allocation = distribute(demands)
    print(report(demands, allocation))


if __name__ == "__main__":
    main()

