def validate(measurements):
    """Return the readings as a list of floats, rejecting malformed input."""
    if not isinstance(measurements, (list, tuple)):
        raise TypeError("measurements must be a list of numbers")
    readings = []
    for position, value in enumerate(measurements):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("reading at index %d is not a number: %r" % (position, value))
        readings.append(float(value))
    return readings


def predict(measurements):
    """Find every strictly local maximum (high tide) and minimum (low tide)."""
    readings = validate(measurements)
    tides = []
    for index in range(1, len(readings) - 1):
        before = readings[index - 1]
        current = readings[index]
        after = readings[index + 1]
        if current > before and current > after:
            tides.append((index, "high", current))
        elif current < before and current < after:
            tides.append((index, "low", current))
    return tides


def tide_range(tides):
    """Return the (lowest low, highest high) levels, or None when absent."""
    lows = [level for _, kind, level in tides if kind == "low"]
    highs = [level for _, kind, level in tides if kind == "high"]
    lowest = min(lows) if lows else None
    highest = max(highs) if highs else None
    return lowest, highest


def intervals(tides):
    """Hours elapsed between consecutive tides of any kind."""
    gaps = []
    for earlier, later in zip(tides, tides[1:]):
        gaps.append(later[0] - earlier[0])
    return gaps


def report(measurements):
    """Build a human readable summary of the tides in a series of readings."""
    tides = predict(measurements)
    lines = ["Analysed %d hourly readings." % len(measurements)]
    if not tides:
        lines.append("No local high or low tides were detected.")
        return "\n".join(lines)
    for index, kind, level in tides:
        lines.append("hour %2d: %-4s tide at %.2f m" % (index, kind, level))
    lowest, highest = tide_range(tides)
    if highest is not None:
        lines.append("Highest high tide: %.2f m" % highest)
    if lowest is not None:
        lines.append("Lowest low tide: %.2f m" % lowest)
    gaps = intervals(tides)
    if gaps:
        average = sum(gaps) / len(gaps)
        lines.append("Average %.1f hours between tides." % average)
    return "\n".join(lines)


def main():
    series = {
        "harbour": [3.1, 3.6, 4.2, 4.0, 3.3, 2.5, 1.9, 2.4, 3.0, 3.8, 4.1, 3.7],
        "estuary": [1.0, 1.0, 1.0, 1.0],
        "bay": [5.5, 4.0, 4.4, 6.1, 5.0, 5.0, 4.2],
    }
    for name in sorted(series):
        print("== %s ==" % name)
        print(report(series[name]))
        print()


if __name__ == "__main__":
    main()

