MINUTES_PER_PERCENT = 2
SOAK_THRESHOLD = 20
SOAK_BONUS = 5


def validate_sensor(reading):
    """Return a clean (zone, current, target) triple or raise ValueError."""
    if len(reading) != 3:
        raise ValueError("each sensor reading needs zone, current and target")
    zone, current, target = reading
    if not str(zone).strip():
        raise ValueError("zone identifier must not be empty")
    values = []
    for value in (current, target):
        number = float(value)
        if number < 0 or number > 100:
            raise ValueError("moisture for zone %s out of range: %r" % (zone, value))
        values.append(number)
    return str(zone).strip(), values[0], values[1]


def water(sensors):
    """Minutes of sprinkler time per zone, given moisture sensor readings."""
    schedule = []
    for reading in sensors:
        zone, current, target = validate_sensor(reading)
        if current >= target:
            schedule.append((zone, 0))
            continue
        deficit = target - current
        minutes = deficit * MINUTES_PER_PERCENT
        if deficit > SOAK_THRESHOLD:
            minutes += SOAK_BONUS
        schedule.append((zone, int(round(minutes))))
    return schedule


def total_runtime(schedule):
    """Sum of all watering minutes in a schedule."""
    total = 0
    for _zone, minutes in schedule:
        total += minutes
    return total


def format_report(schedule):
    """Render the schedule as aligned text lines plus a summary line."""
    if not schedule:
        return "no zones to water"
    width = max(len(zone) for zone, _minutes in schedule)
    lines = []
    for zone, minutes in schedule:
        if minutes == 0:
            action = "moisture at target"
        else:
            action = "run %d min" % minutes
        lines.append("%-*s  %s" % (width, zone, action))
    lines.append("%-*s  total %d min" % (width, "ALL", total_runtime(schedule)))
    return "\n".join(lines)


def main():
    readings = [
        ("north-bed", 55, 55),
        ("south-bed", 40, 58),
        ("herb-trays", 12, 70),
        ("citrus-row", 80, 62),
        ("seedlings", 33, 54.5),
    ]
    schedule = water(readings)
    print(format_report(schedule))
    dry = [zone for zone, minutes in schedule if minutes > 0]
    if dry:
        print("zones needing water: " + ", ".join(dry))
    else:
        print("all zones are already moist enough")


if __name__ == "__main__":
    main()

