def validate_routine(routine):
    if len(routine) != 3:
        raise ValueError("each routine needs a name, difficulty and judge scores")
    name, difficulty, judges = routine
    if not isinstance(name, str) or not name.strip():
        raise ValueError("athlete name must be a non-empty string")
    if difficulty <= 0:
        raise ValueError("difficulty multiplier for %s must be positive" % name)
    if len(judges) != 5:
        raise ValueError("%s needs exactly five judge scores" % name)
    for judge_score in judges:
        if judge_score < 0:
            raise ValueError("judge scores for %s cannot be negative" % name)
    return name.strip(), float(difficulty), [float(j) for j in judges]


def trimmed_mean(judges):
    ordered = sorted(judges)
    kept = ordered[1:-1]
    return sum(kept) / len(kept)


def score(routines):
    results = []
    for routine in routines:
        name, difficulty, judges = validate_routine(routine)
        final = trimmed_mean(judges) * difficulty
        results.append((name, round(final, 3)))
    results.sort(key=lambda entry: (-entry[1], entry[0]))
    return results


def format_table(results):
    if not results:
        return "no routines scored"
    width = max(len(name) for name, _ in results)
    lines = []
    for rank, (name, final) in enumerate(results, start=1):
        lines.append("%2d. %-*s %8.3f" % (rank, width, name, final))
    return "\n".join(lines)


def medalists(results):
    winners = []
    for name, final in results[:3]:
        if final > 0:
            winners.append(name)
    return winners


def main():
    routines = [
        ("Hanna Loft", 3.4, [8.5, 9.0, 8.8, 9.4, 8.7]),
        ("Ivo Petrov", 3.8, [7.9, 8.2, 8.0, 9.1, 7.5]),
        ("Mei Tanaka", 3.1, [9.5, 9.6, 9.4, 9.9, 9.2]),
        ("Diego Cruz", 3.8, [8.1, 8.0, 8.4, 8.2, 8.3]),
    ]
    results = score(routines)
    print(format_table(results))
    podium = medalists(results)
    for place, name in zip(("gold", "silver", "bronze"), podium):
        print("%s: %s" % (place, name))

    try:
        score([("Broken Entry", 2.0, [9.0, 9.0, 9.0])])
    except ValueError as err:
        print("rejected:", err)


if __name__ == "__main__":
    main()

