def validate_claim(claim):
    if len(claim) != 4:
        raise ValueError("each claim needs name, cost, deductible and limit")
    name, cost, deductible, limit = claim
    if not isinstance(name, str) or not name.strip():
        raise ValueError("policyholder name must be a non-empty string")
    for label, value in (("cost", cost), ("deductible", deductible), ("limit", limit)):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("%s for %s must be numeric" % (label, name))
        if value < 0:
            raise ValueError("%s for %s must not be negative" % (label, name))
    return name.strip(), float(cost), float(deductible), float(limit)


def payout_for(cost, deductible, limit):
    covered = cost - deductible
    if covered < 0:
        return 0.0
    if covered > limit:
        return limit
    return covered


def process(claims):
    totals = {}
    order = []
    for claim in claims:
        name, cost, deductible, limit = validate_claim(claim)
        if name not in totals:
            totals[name] = 0.0
            order.append(name)
        totals[name] += payout_for(cost, deductible, limit)
    return [(name, totals[name]) for name in order]


def format_report(results):
    if not results:
        return "No claims processed."
    width = max(len(name) for name, _ in results)
    lines = []
    for name, total in results:
        lines.append("%-*s  %10.2f" % (width, name, total))
    grand = sum(total for _, total in results)
    lines.append("%-*s  %10.2f" % (width, "TOTAL", grand))
    return "\n".join(lines)


def main():
    claims = [
        ("Alice Moreno", 1200.00, 500.00, 5000.00),
        ("Bob Tran", 300.00, 750.00, 4000.00),
        ("Alice Moreno", 9800.00, 500.00, 5000.00),
        ("Cora Blake", 2500.50, 250.50, 1500.00),
        ("Bob Tran", 1875.25, 750.00, 4000.00),
    ]
    results = process(claims)
    print(format_report(results))
    for name, total in results:
        if total == 0.0:
            print("%s received no reimbursement." % name)
    print()
    bad_claims = [
        ("Dana Iyer", 100.0, -20.0, 1000.0),
        ("", 100.0, 20.0, 1000.0),
        ("Eli Ford", 100.0, 20.0),
    ]
    for claim in bad_claims:
        try:
            process([claim])
        except (ValueError, TypeError) as exc:
            print("rejected %r: %s" % (claim, exc))


if __name__ == "__main__":
    main()

