import re

SUSPICIOUS_WORDS = ("urgent", "winner", "wire", "prize", "guaranteed", "free")
REPUTABLE_DOMAINS = (".edu", ".gov", ".mil")
SPAM_THRESHOLD = 3
REPUTABLE_CREDIT = 2

WORD_RE = re.compile(r"[a-z']+")


def tokenize(text):
    """Split a piece of text into lowercase word tokens."""
    if text is None:
        return []
    return WORD_RE.findall(str(text).lower())


def count_suspicious(text):
    """Count how many tokens of text are suspicious words."""
    total = 0
    for token in tokenize(text):
        if token in SUSPICIOUS_WORDS:
            total += 1
    return total


def is_reputable(sender):
    """True when the sender's address ends in a reputable top level domain."""
    address = str(sender).strip().lower()
    for domain in REPUTABLE_DOMAINS:
        if address.endswith(domain):
            return True
    return False


def score_email(sender, subject, body):
    """Compute the spam score for a single message."""
    score = count_suspicious(subject) + count_suspicious(body)
    if is_reputable(sender):
        score -= REPUTABLE_CREDIT
    return score


def filter(emails):
    """Classify each (sender, subject, body) tuple as spam or not."""
    results = []
    for email in emails:
        if len(email) != 3:
            raise ValueError("each email needs a sender, subject and body")
        sender, subject, body = email
        score = score_email(sender, subject, body)
        results.append((sender, score >= SPAM_THRESHOLD))
    return results


def format_report(verdicts):
    """Build a human readable summary of the classification results."""
    lines = []
    spam_count = 0
    for sender, spam in verdicts:
        if spam:
            spam_count += 1
            label = "SPAM"
        else:
            label = "ok"
        lines.append("{:<28} {}".format(sender, label))
    lines.append("{} of {} messages flagged".format(spam_count, len(verdicts)))
    return "\n".join(lines)


def main():
    inbox = [
        ("sales@offers.biz", "URGENT winner notice", "Wire the fee to claim your prize."),
        ("dean@college.edu", "Urgent: wire transfer", "Please wire tuition, it is urgent."),
        ("friend@mail.com", "Lunch tomorrow", "Are you free at noon?"),
        ("clerk@city.gov", "Permit renewal", "Your permit renewal is ready."),
    ]
    print(format_report(filter(inbox)))


if __name__ == "__main__":
    main()

