FEE_RATE = 0.02
BASE_CURRENCY = "USD"


def validate(transactions):
    """Check the shape and values of each transaction, returning clean tuples."""
    cleaned = []
    for index, entry in enumerate(transactions):
        if len(entry) != 3:
            raise ValueError("transaction %d must have 3 fields" % index)
        amount, code, rate = entry
        if not isinstance(code, str):
            raise TypeError("currency code of transaction %d must be a string" % index)
        if amount < 0:
            raise ValueError("amount of transaction %d is negative" % index)
        if rate <= 0:
            raise ValueError("rate of transaction %d must be positive" % index)
        cleaned.append((float(amount), code.strip().upper(), float(rate)))
    return cleaned


def convert(transactions):
    """Total base currency value and total foreign transaction fees."""
    total_value = 0.0
    total_fees = 0.0
    for amount, code, rate in validate(transactions):
        value = amount * rate
        if code != BASE_CURRENCY:
            fee = value * FEE_RATE
            total_fees += fee
            total_value += value + fee
        else:
            total_value += value
    return (round(total_value, 2), round(total_fees, 2))


def summarize(transactions):
    """Group the converted values per currency code."""
    per_currency = {}
    for amount, code, rate in validate(transactions):
        value = amount * rate
        if code != BASE_CURRENCY:
            value += value * FEE_RATE
        if code in per_currency:
            per_currency[code] += value
        else:
            per_currency[code] = value
    return {code: round(value, 2) for code, value in per_currency.items()}


def format_report(transactions):
    """Build a human readable report of the conversion results."""
    total, fees = convert(transactions)
    lines = []
    for code in sorted(summarize(transactions)):
        subtotal = summarize(transactions)[code]
        lines.append("  {:<5} {:>12.2f}".format(code, subtotal))
    lines.append("  {:<5} {:>12.2f}".format("FEES", fees))
    lines.append("  {:<5} {:>12.2f}".format("TOTAL", total))
    return "\n".join(lines)


def main():
    purchases = [
        (100.00, "USD", 1.0),
        (250.00, "eur", 1.0850),
        (75.50, "GBP", 1.2640),
        (12000.0, "JPY", 0.0067),
        (40.00, "USD", 1.0),
        (99.99, "EUR", 1.0850),
    ]
    print("Foreign purchase conversion report")
    print(format_report(purchases))
    total, fees = convert(purchases)
    if fees > 0:
        print("Fees represent {:.2f}% of the total.".format(100.0 * fees / total))


if __name__ == "__main__":
    main()

