def parse_readings(lines):
    """Turn text lines of the form 'waste hours' into numeric tuples."""
    readings = []
    for lineno, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split()
        if len(parts) != 2:
            raise ValueError("line %d: expected 'waste hours'" % lineno)
        try:
            waste, hours = float(parts[0]), float(parts[1])
        except ValueError:
            raise ValueError("line %d: non-numeric reading" % lineno)
        readings.append((waste, hours))
    return readings


def validate(readings):
    """Reject readings that cannot describe a real day in the tank."""
    for index, entry in enumerate(readings):
        if len(entry) != 2:
            raise ValueError("reading %d must hold waste and filter hours" % index)
        waste, hours = entry
        if waste < 0:
            raise ValueError("reading %d has negative waste" % index)
        if hours < 0 or hours > 24:
            raise ValueError("reading %d has impossible filter hours" % index)


def run_days(readings):
    """Yield the tank state at the end of each simulated day."""
    validate(readings)
    ammonia = 0.0
    multiplier = 2.0
    for day, (waste, hours) in enumerate(readings, start=1):
        ammonia += waste
        ammonia -= hours * multiplier
        if ammonia < 0.0:
            ammonia = 0.0
        if hours > 8:
            multiplier -= 0.1
        yield day, waste, hours, ammonia, multiplier
        if ammonia > 10.0:
            return


def simulate(readings):
    """Return the ammonia level when the simulation ends, to one decimal."""
    ammonia = 0.0
    for _day, _waste, _hours, level, _multiplier in run_days(readings):
        ammonia = level
    return round(ammonia, 1)


def format_report(readings):
    """Build a human readable log of the run plus its verdict."""
    lines = ["day  waste  hours  ammonia  multiplier"]
    last_day = 0
    for day, waste, hours, ammonia, multiplier in run_days(readings):
        lines.append("%3d  %5.1f  %5.1f  %7.1f  %10.1f" % (day, waste, hours, ammonia, multiplier))
        last_day = day
    final = simulate(readings)
    if final > 10.0:
        lines.append("ALERT: toxicity breach on day %d at %.1f ppm" % (last_day, final))
    else:
        lines.append("Tank stable after %d day(s) at %.1f ppm" % (last_day, final))
    return "\n".join(lines)


def main():
    log = [
        "# waste hours",
        "6 2",
        "9 9",
        "12 1",
        "4 3",
    ]
    readings = parse_readings(log)
    print(format_report(readings))


if __name__ == "__main__":
    main()

