def validate_stops(neighborhoods):
    """Return the stops as a clean list of (name, distance, customers) tuples."""
    cleaned = []
    for index, stop in enumerate(neighborhoods):
        if len(stop) != 3:
            raise ValueError("stop %d must have name, distance and customer count" % index)
        name, distance, customers = stop
        if not isinstance(name, str) or not name.strip():
            raise ValueError("stop %d has an empty neighborhood name" % index)
        distance = float(distance)
        customers = int(customers)
        if distance < 0:
            raise ValueError("stop %r has a negative distance" % name)
        if customers < 0:
            raise ValueError("stop %r has a negative customer count" % name)
        cleaned.append((name.strip(), distance, customers))
    return cleaned


def route(neighborhoods):
    """Drive the stops in order, selling ice creams until fuel or stock runs out."""
    stops = validate_stops(neighborhoods)
    fuel = 50.0
    inventory = 200
    sales = []
    for name, distance, customers in stops:
        fuel -= distance
        if fuel < 0:
            break
        if customers <= inventory:
            sold = customers
        else:
            sold = inventory
        inventory -= sold
        sales.append((name, sold))
    return sales


def summarize(sales, neighborhoods):
    """Build the totals used by the printed report."""
    total_sold = 0
    for _name, sold in sales:
        total_sold += sold
    skipped = []
    served_names = set(name for name, _sold in sales)
    for name, _distance, _customers in validate_stops(neighborhoods):
        if name not in served_names:
            skipped.append(name)
    return total_sold, skipped


def format_report(sales, neighborhoods):
    """Render a human readable summary of one day on the road."""
    total_sold, skipped = summarize(sales, neighborhoods)
    lines = []
    for name, sold in sales:
        if sold == 0:
            lines.append("%-14s sold out, no deliveries" % name)
        else:
            lines.append("%-14s %3d ice creams" % (name, sold))
    lines.append("%-14s %3d total, %d left in the truck" % ("TOTAL", total_sold, 200 - total_sold))
    if skipped:
        lines.append("Out of fuel before: " + ", ".join(skipped))
    return "\n".join(lines)


def main():
    day = [
        ("Maple Grove", 8, 45),
        ("Riverside", 12, 60),
        ("Hillcrest", 9, 80),
        ("Oakfield", 14, 35),
        ("Fartown", 20, 25),
    ]
    sales = route(day)
    print(format_report(sales, day))


