def bounding_box(points):
    """Return (min_x, min_y, max_x, max_y) for a list of 2D points."""
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    return min(xs), min(ys), max(xs), max(ys)


def center_of(points):
    """Return the exact center of the bounding box of the given points."""
    min_x, min_y, max_x, max_y = bounding_box(points)
    return (min_x + max_x) / 2.0, (min_y + max_y) / 2.0


def validate(points, factor):
    """Reject inputs that cannot describe a scalable pattern."""
    if not points:
        raise ValueError("a pattern needs at least one point")
    for index, point in enumerate(points):
        if len(point) != 2:
            raise ValueError("point %d is not two dimensional" % index)
        for value in point:
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError("point %d has a non numeric coordinate" % index)
    if factor <= 0:
        raise ValueError("the scale factor must be positive")


def scale(points, factor):
    """Scale a garment pattern about the center of its bounding box."""
    validate(points, factor)
    cx, cy = center_of(points)
    moved = []
    for x, y in points:
        moved.append((cx + (x - cx) * factor, cy + (y - cy) * factor))
    min_x, min_y, _, _ = bounding_box(moved)
    shift_x = -min_x if min_x < 0 else 0.0
    shift_y = -min_y if min_y < 0 else 0.0
    return [(round(x + shift_x), round(y + shift_y)) for x, y in moved]


def describe(points):
    """Build a one line summary of a pattern's extent."""
    min_x, min_y, max_x, max_y = bounding_box(points)
    return "%d points, %g x %g, origin (%g, %g)" % (
        len(points), max_x - min_x, max_y - min_y, min_x, min_y)


def report(name, points, factor):
    """Print the original and scaled versions of one pattern piece."""
    print("%s @ x%.2f" % (name, factor))
    print("  before: " + describe(points))
    adjusted = scale(points, factor)
    print("  after : " + describe(adjusted))
    for original, result in zip(points, adjusted):
        print("    (%g, %g) -> (%d, %d)" % (original[0], original[1], result[0], result[1]))
    return adjusted


def main():
    sleeve = [(10, 10), (40, 12), (44, 60), (8, 58)]
    collar = [(0, 0), (20, 4), (18, 14), (2, 12)]
    pieces = [("sleeve", sleeve, 1.25), ("collar", collar, 0.8), ("collar", collar, 2.5)]
    for name, points, factor in pieces:
        adjusted = report(name, points, factor)
        min_x, min_y, _, _ = bounding_box(adjusted)
        if min_x == 0 or min_y == 0:
            print("  pattern was shifted back onto the positive quadrant")
        print()


if __name__ == "__main__":
    main()

