MAX_TEMP = 25.0
MIN_TEMP = 15.0
STABLE_DAYS = 3


def parse_readings(lines):
    """Turn 'temperature,gravity' text lines into a list of float tuples."""
    readings = []
    for line in lines:
        text = line.strip()
        if not text:
            continue
        parts = text.split(",")
        if len(parts) != 2:
            raise ValueError("expected 'temperature,gravity', got %r" % line)
        readings.append((float(parts[0]), float(parts[1])))
    return readings


def validate(readings):
    """Reject anything that is not a sequence of two numeric measurements."""
    for position, reading in enumerate(readings, start=1):
        if not isinstance(reading, (tuple, list)) or len(reading) != 2:
            raise ValueError("reading %d is not a (temperature, gravity) pair" % position)
        for value in reading:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("reading %d contains a non-numeric value" % position)
        if reading[1] <= 0:
            raise ValueError("reading %d has a non-positive gravity" % position)


def monitor(readings):
    """Follow a fermentation and report (final gravity, days elapsed, warning)."""
    validate(readings)
    off_flavor = False
    stable_days = 0
    previous = None
    for day, (temperature, gravity) in enumerate(readings, start=1):
        if temperature > MAX_TEMP:
            off_flavor = True
        if temperature < MIN_TEMP:
            stable_days = 0
            previous = None
            continue
        if previous is not None and gravity == previous:
            stable_days += 1
        else:
            stable_days = 1
        previous = gravity
        if stable_days >= STABLE_DAYS:
            return (gravity, day, off_flavor)
    return (previous, len(readings), off_flavor)


def format_report(name, result):
    """Render the monitor() outcome for a single batch as readable text."""
    gravity, days, off_flavor = result
    pieces = ["%s: %d day(s)" % (name, days)]
    if gravity is None:
        pieces.append("no usable gravity (every day stalled)")
    else:
        pieces.append("final gravity %.3f" % gravity)
    if off_flavor:
        pieces.append("WARNING: off flavors likely")
    return " | ".join(pieces)


def main():
    batches = {
        "pale ale": [
            "20.0,1.050", "21.5,1.030", "22.0,1.012",
            "21.0,1.012", "20.5,1.012", "20.0,1.012",
        ],
        "hot saison": ["24.0,1.060", "26.5,1.040", "27.0,1.020", "22.0,1.020"],
        "cold lager": ["16.0,1.048", "14.0,1.040", "13.5,1.040", "16.5,1.040"],
    }
    for name in sorted(batches):
        readings = parse_readings(batches[name])
        print(format_report(name, monitor(readings)))


if __name__ == "__main__":
    main()

