CAPACITY = 8


def validate_groups(groups):
    """Return a clean list of group sizes, rejecting malformed input."""
    cleaned = []
    for index, size in enumerate(groups):
        if isinstance(size, bool) or not isinstance(size, int):
            raise TypeError("group %d is not an integer: %r" % (index, size))
        if size < 1:
            raise ValueError("group %d must contain at least one person" % index)
        cleaned.append(size)
    return cleaned


def board(groups):
    """Load groups onto cabins of eight seats; return (cabins, boarded)."""
    queue = validate_groups(groups)
    cabins = 0
    boarded = 0
    occupancy = 0
    for size in queue:
        if size > CAPACITY:
            continue
        if occupancy + size > CAPACITY:
            cabins += 1
            occupancy = 0
        occupancy += size
        boarded += size
    if occupancy > 0:
        cabins += 1
    return cabins, boarded


def denied_groups(groups):
    """List the groups that are too large to ever fit in a single cabin."""
    oversized = []
    for size in validate_groups(groups):
        if size > CAPACITY:
            oversized.append(size)
    return oversized


def format_report(groups):
    """Build a human readable summary of one boarding operation."""
    cabins, boarded = board(groups)
    refused = denied_groups(groups)
    lines = ["queue: " + ", ".join(str(size) for size in groups)]
    lines.append("cabins dispatched: %d" % cabins)
    lines.append("passengers carried: %d" % boarded)
    if refused:
        lines.append("denied groups: " + ", ".join(str(size) for size in refused))
    if cabins:
        average = boarded / cabins
        lines.append("average load: %.2f of %d seats" % (average, CAPACITY))
    return "\n".join(lines)


def main():
    queues = [
        [1, 2, 3, 4, 5],
        [8, 8, 8],
        [9, 1, 7, 2],
        [3, 3, 3, 3, 3],
        [12, 14],
    ]
    for queue in queues:
        print(format_report(queue))
        print("-" * 32)
    total_cabins = 0
    for queue in queues:
        cabins, _people = board(queue)
        total_cabins += cabins
    print("total cabins for the day: %d" % total_cabins)


if __name__ == "__main__":
    main()

