def validate_keystrokes(keystrokes):
    """Check that every keystroke is a (character, timestamp) pair in time order."""
    previous = 0.0
    for position, stroke in enumerate(keystrokes):
        if len(stroke) != 2:
            raise ValueError("keystroke %d is not a (character, time) pair" % position)
        character, moment = stroke
        if not isinstance(character, str) or len(character) != 1:
            raise ValueError("keystroke %d does not hold a single character" % position)
        if not isinstance(moment, (int, float)) or isinstance(moment, bool):
            raise ValueError("keystroke %d has a non numeric timestamp" % position)
        if moment < previous:
            raise ValueError("keystroke %d travels backwards in time" % position)
        previous = moment


def count_matches(keystrokes, target):
    """Compare the typed characters to the target sentence, position by position."""
    correct = 0
    errors = 0
    for position, stroke in enumerate(keystrokes):
        if position >= len(target):
            errors += 1
        elif stroke[0] == target[position]:
            correct += 1
        else:
            errors += 1
    return correct, errors


def final_timestamp(keystrokes):
    latest = 0.0
    for stroke in keystrokes:
        if stroke[1] > latest:
            latest = stroke[1]
    return latest


def words_per_minute(correct, seconds):
    if seconds <= 0:
        return 0
    return int(correct / 5.0 * 60.0 / seconds)


def evaluate(keystrokes, target):
    validate_keystrokes(keystrokes)
    correct, errors = count_matches(keystrokes, target)
    seconds = final_timestamp(keystrokes)
    return words_per_minute(correct, seconds), errors


def build_keystrokes(typed, total_seconds):
    """Turn a typed sentence into evenly spaced keystrokes ending at total_seconds."""
    strokes = []
    if typed:
        step = float(total_seconds) / len(typed)
        for index, character in enumerate(typed, start=1):
            strokes.append((character, round(index * step, 3)))
    return strokes


def format_report(name, keystrokes, target):
    wpm, errors = evaluate(keystrokes, target)
    lines = ["%s: %d wpm, %d error(s)" % (name, wpm, errors)]
    if errors == 0:
        lines.append("    flawless transcription")
    else:
        for position, stroke in enumerate(keystrokes):
            if position >= len(target):
                lines.append("    %2d: typed %r past the end of the target" % (position, stroke[0]))
            elif stroke[0] != target[position]:
                lines.append("    %2d: typed %r, expected %r" % (position, stroke[0], target[position]))
    return "\n".join(lines)


def main():
    target = "The quick brown fox jumps over the lazy dog."
    attempts = [
        ("Ada", target, 21.0),
        ("Grace", "The quick brwon fox jumps over the lazy dog.", 18.5),
        ("Linus", "The quick brown fox jumps over the lazy dog.!", 30.0),
    ]
    for name, typed, duration in attempts:
        print(format_report(name, build_keystrokes(typed, duration), target))


if __name__ == "__main__":
    main()

