import sys

SYMBOL_TABLE = {'.': 'E', '-': 'T', '..': 'I', '--': 'M'}
DOT_DURATION = 1
DASH_DURATION = 3


def classify(duration):
    """Return '.' or '-' for a flash length, or None when it marks a gap."""
    if duration == DOT_DURATION:
        return '.'
    if duration == DASH_DURATION:
        return '-'
    return None


def group_flashes(flashes):
    """Split the durations into symbol groups delimited by gap flashes."""
    groups = []
    current = []
    for duration in flashes:
        symbol = classify(duration)
        if symbol is None:
            if current:
                groups.append(''.join(current))
                current = []
        else:
            current.append(symbol)
    if current:
        groups.append(''.join(current))
    return groups


def decode_group(group):
