CIRCUMFERENCE_METERS = 2.0


def _validate_teeth(teeth, label):
    if not isinstance(teeth, (list, tuple)):
        raise TypeError("{} gears must be given as a list".format(label))
    if len(teeth) == 0:
        raise ValueError("{} gears must not be empty".format(label))
    cleaned = []
    for count in teeth:
        if isinstance(count, bool) or not isinstance(count, int):
            raise TypeError("{} tooth counts must be integers".format(label))
        if count <= 0:
            raise ValueError("{} tooth counts must be positive".format(label))
        cleaned.append(count)
    return cleaned


def validate_setup(setup):
    if not isinstance(setup, (list, tuple)) or len(setup) != 2:
        raise ValueError("setup must be a pair of gear lists")
    front = _validate_teeth(setup[0], "front")
    rear = _validate_teeth(setup[1], "rear")
    return front, rear


def analyze(setup):
    front, rear = validate_setup(setup)
    biggest_front, smallest_front = max(front), min(front)
    biggest_rear, smallest_rear = max(rear), min(rear)
    lengths = []
    for chainring in front:
        for cog in rear:
            if chainring == biggest_front and cog == biggest_rear:
                continue
            if chainring == smallest_front and cog == smallest_rear:
                continue
            lengths.append(chainring / cog * CIRCUMFERENCE_METERS)
    return sorted(lengths)


def gear_steps(lengths):
    steps = []
    for index in range(1, len(lengths)):
        previous = lengths[index - 1]
        if previous > 0:
            steps.append((lengths[index] - previous) / previous * 100.0)
    return steps


def format_report(name, setup, lengths):
    lines = ["{}: {} x {}".format(name, setup[0], setup[1])]
    if not lengths:
        lines.append("  no usable gears")
        return "\n".join(lines)
    for index, length in enumerate(lengths, start=1):
        lines.append("  gear {:>2}: {:6.2f} m".format(index, length))
    steps = gear_steps(lengths)
    if steps:
        widest = max(steps)
        lines.append("  range: {:.2f} m - {:.2f} m".format(lengths[0], lengths[-1]))
        lines.append("  largest step between gears: {:.1f}%".format(widest))
    return "\n".join(lines)


def main():
    setups = [
        ("road double", ([53, 39], [11, 13, 15, 17, 19, 21, 23, 25])),
        ("mountain triple", ([44, 32, 22], [14, 18, 24, 32])),
        ("single speed", ([46], [16])),
    ]
    for name, setup in setups:
        lengths = analyze(setup)
        print(format_report(name, setup, lengths))
        print()


if __name__ == "__main__":
    main()

