PENALTIES = {"thick": 3, "medium": 2, "thin": 1}
START_DURABILITY = 20
REINFORCED_BONUS = 2


def layer_cost(fabric):
    """Sum the durability penalty of every layer a single stitch pierces."""
    total = 0
    for layer in fabric:
        if not isinstance(layer, str):
            raise TypeError("fabric layers must be strings, got %r" % (layer,))
        name = layer.strip().lower()
        if name not in PENALTIES:
            raise ValueError("unknown fabric layer: %r" % (layer,))
        total += PENALTIES[name]
    return total


def stitch(fabric, reinforced):
    """Return (completed stitches, final strength score).

    A stitch pierces every layer at once, so it costs the sum of the layer
    penalties (doubled when reinforced).  A stitch only counts as completed
    if the needle still has durability left afterwards; once the durability
    reaches zero or less the needle breaks and no further stitches happen.
    Reinforced stitching adds two points to the final strength score.
    """
    cost = layer_cost(fabric)
    if reinforced:
        cost *= 2
    bonus = REINFORCED_BONUS if reinforced else 0
    if cost == 0:
        return 0, bonus

    durability = START_DURABILITY
    stitches = 0
    while durability - cost > 0:
        durability -= cost
        stitches += 1
    return stitches, stitches + bonus


def describe_layers(fabric):
    """Summarise the fabric stack as a short human readable string."""
    counts = {}
    for layer in fabric:
        name = layer.strip().lower()
        counts[name] = counts.get(name, 0) + 1
    parts = []
    for name in ("thick", "medium", "thin"):
        if name in counts:
            parts.append("%d x %s" % (counts[name], name))
    if not parts:
        return "no layers"
    return ", ".join(parts)


def format_report(fabric, reinforced):
    """Run the stitching and describe the outcome in one line."""
    stitches, score = stitch(fabric, reinforced)
    cost = layer_cost(fabric)
    if reinforced:
        cost *= 2
    mode = "reinforced" if reinforced else "plain"
    if stitches == 0:
        outcome = "the needle never completes a stitch"
    else:
        outcome = "%d stitches completed, strength %d" % (stitches, score)
    return "%s (%s, cost %d): %s" % (describe_layers(fabric), mode, cost, outcome)


def main():
    seams = [
        (["thin", "thin"], False),
        (["thick", "medium", "thin"], False),
        (["thick", "medium", "thin"], True),
        (["thick", "thick", "thick", "thick"], True),
        ([], False),
    ]
    for fabric, reinforced in seams:
        print(format_report(fabric, reinforced))


if __name__ == "__main__":
    main()

