def validate(reptiles, volume):
    """Check the pet list and terrarium volume, raising ValueError on bad input."""
    if volume <= 0:
        raise ValueError("terrarium volume must be a positive number of gallons")
    for entry in reptiles:
        if len(entry) != 3:
            raise ValueError("each pet needs a species, a size and a temperament")
        species, size, temperament = entry
        if not species:
            raise ValueError("species name must not be empty")
        if size <= 0:
            raise ValueError("adult size of %s must be positive" % species)
        if not 1 <= temperament <= 10:
            raise ValueError("temperament of %s must be between 1 and 10" % species)


def total_size(reptiles):
    """Sum the adult sizes, in inches, of every reptile in the enclosure."""
    total = 0
    for _species, size, _temperament in reptiles:
        total += size
    return total


def evaluate(reptiles, volume):
    """Return (overstocked, small_pets_in_danger) for the given enclosure."""
    validate(reptiles, volume)
    overstocked = total_size(reptiles) > volume
    aggressive = False
    tiny = False
    for _species, size, temperament in reptiles:
        if temperament > 7:
            aggressive = True
        if size < 3:
            tiny = True
    return overstocked, aggressive and tiny


def aggressors(reptiles):
    """Names of the reptiles whose temperament is above seven."""
    names = []
    for species, _size, temperament in reptiles:
        if temperament > 7:
            names.append(species)
    return names


def describe(reptiles, volume):
    """Build a short multi-line report about one terrarium."""
    overstocked, danger = evaluate(reptiles, volume)
    lines = ["Terrarium of %d gallons holding %d reptile(s):" % (volume, len(reptiles))]
    for species, size, temperament in reptiles:
        lines.append("  %-18s %2d in  temperament %d" % (species, size, temperament))
    used = total_size(reptiles)
    if overstocked:
        lines.append("  OVERSTOCKED: %d inches of reptile for %d gallons" % (used, volume))
    else:
        lines.append("  Stocking is fine: %d of %d gallons used" % (used, volume))
    if danger:
        lines.append("  DANGER: small pets share space with %s" % ", ".join(aggressors(reptiles)))
    return "\n".join(lines)


def main():
    habitats = [
        ([("leopard gecko", 8, 3), ("crested gecko", 7, 2)], 20),
        ([("savannah monitor", 40, 9), ("house gecko", 2, 4)], 75),
        ([("ball python", 48, 5), ("corn snake", 50, 4)], 40),
    ]
    for reptiles, volume in habitats:
        print(describe(reptiles, volume))
        print()
    try:
        evaluate([("axolotl", 9, 12)], 30)
    except ValueError as err:
        print("rejected setup:", err)


if __name__ == "__main__":
    main()

