def validate_slide(slide):
    """Return a normalised (identifier, count, clarity) tuple or raise ValueError."""
    if len(slide) != 3:
        raise ValueError("each slide needs an identifier, a cell count and a clarity score")
    identifier, count, clarity = slide
    if not isinstance(identifier, str) or not identifier.strip():
        raise ValueError("slide identifier must be a non-empty string")
    if isinstance(count, bool) or not isinstance(count, int):
        raise ValueError("cell count for %r must be an integer" % (identifier,))
    if count < 0:
        raise ValueError("cell count for %s cannot be negative" % identifier)
    if isinstance(clarity, bool) or not isinstance(clarity, (int, float)):
        raise ValueError("clarity score for %s must be numeric" % identifier)
    return (identifier.strip(), count, float(clarity))


def select_valid(slides, threshold):
    """Keep only the slides whose clarity score reaches the threshold."""
    kept = []
    for slide in slides:
        identifier, count, clarity = validate_slide(slide)
        if clarity >= threshold:
            kept.append((identifier, count, clarity))
    return kept


def average_count(valid_slides):
    total = 0
    for _, count, _ in valid_slides:
        total += count
    return total / len(valid_slides)


def analyze(slides, threshold):
    """Return the identifiers of valid slides denser than the valid average."""
    if not isinstance(threshold, (int, float)) or isinstance(threshold, bool):
        raise ValueError("threshold must be numeric")
    valid_slides = select_valid(slides, threshold)
    if not valid_slides:
        return []
    mean = average_count(valid_slides)
    dense = []
    for identifier, count, _ in valid_slides:
        if count > mean:
            dense.append(identifier)
    return dense


def format_report(slides, threshold):
    """Build a human readable summary of one analysis run."""
    valid_slides = select_valid(slides, threshold)
    lines = ["Clarity threshold: %.2f" % threshold]
    lines.append("Slides submitted: %d" % len(slides))
    lines.append("Slides retained: %d" % len(valid_slides))
    if valid_slides:
        lines.append("Average cell count: %.1f" % average_count(valid_slides))
    dense = analyze(slides, threshold)
    if dense:
        for identifier in dense:
            lines.append("  high density: %s" % identifier)
    else:
        lines.append("  no high density slides")
    return "\n".join(lines)


def main():
    batch = [
        ("S-001", 1200, 0.91),
        ("S-002", 430, 0.44),
        ("S-003", 1580, 0.77),
        ("S-004", 900, 0.83),
        ("S-005", 1310, 0.60),
    ]
    for threshold in (0.5, 0.8, 0.99):
        print(format_report(batch, threshold))
        print("-" * 32)
    try:
        analyze([("S-006", -5, 0.9)], 0.5)
    except ValueError as error:
        print("rejected batch: %s" % error)


if __name__ == "__main__":
    main()

