VEHICLE_FARES = {"car": 20, "truck": 50, "motorcycle": 10}
PASSENGER_FARE = 5
HEAVY_LOAD_SURCHARGE = 15
HEAVY_LOAD_THRESHOLD = 2


def validate(vehicles, passengers):
    """Check that the two lists describe the same set of vehicles."""
    if len(vehicles) != len(passengers):
        raise ValueError(
            "got {0} vehicles but {1} passenger counts".format(
                len(vehicles), len(passengers)
            )
        )
    for index, kind in enumerate(vehicles):
        if kind not in VEHICLE_FARES:
            raise ValueError("unknown vehicle type {0!r} at index {1}".format(kind, index))
        count = passengers[index]
        if not isinstance(count, int) or isinstance(count, bool):
            raise TypeError("passenger count at index {0} must be an int".format(index))
        if count < 0:
            raise ValueError("negative passenger count at index {0}".format(index))


def vehicle_charge(kind, count):
    """Return the fare for a single vehicle carrying count passengers."""
    charge = VEHICLE_FARES[kind] + PASSENGER_FARE * count
    if kind == "truck" and count > HEAVY_LOAD_THRESHOLD:
        charge += HEAVY_LOAD_SURCHARGE
    return charge


def revenue(vehicles, passengers):
    """Total money collected for the trip."""
    validate(vehicles, passengers)
    total = 0
    for kind, count in zip(vehicles, passengers):
        total += vehicle_charge(kind, count)
    return total


def summarize(vehicles, passengers):
    """Group the trip into per-type totals: counts, passengers and money."""
    validate(vehicles, passengers)
    summary = {}
    for kind, count in zip(vehicles, passengers):
        if kind not in summary:
            summary[kind] = {"vehicles": 0, "passengers": 0, "charge": 0}
        entry = summary[kind]
        entry["vehicles"] += 1
        entry["passengers"] += count
        entry["charge"] += vehicle_charge(kind, count)
    return summary


def format_report(vehicles, passengers):
    """Build a human readable manifest for the trip."""
    summary = summarize(vehicles, passengers)
    lines = []
    for kind in sorted(summary):
        entry = summary[kind]
        lines.append(
            "{0:<11} x{1:<3} passengers: {2:<3} ${3}".format(
                kind, entry["vehicles"], entry["passengers"], entry["charge"]
            )
        )
    lines.append("TOTAL ${0}".format(revenue(vehicles, passengers)))
    return "\n".join(lines)


def main():
    trips = [
        (["car", "truck", "motorcycle"], [2, 3, 1]),
        (["truck", "truck", "car", "car"], [0, 4, 3, 1]),
        (["motorcycle"], [0]),
    ]
    for number, (vehicles, passengers) in enumerate(trips, start=1):
        print("Trip {0}".format(number))
        print(format_report(vehicles, passengers))
        print()


if __name__ == "__main__":
