def validate_turbines(turbines):
    """Return the turbine list, raising ValueError on malformed entries."""
    checked = []
    for entry in turbines:
        if len(entry) != 3:
            raise ValueError("each turbine needs an id, a capacity and an efficiency")
        name, capacity, efficiency = entry
        if not isinstance(name, str) or not name:
            raise ValueError("turbine identifier must be a non-empty string")
        if capacity < 0:
            raise ValueError("turbine %s has a negative capacity" % name)
        if not 0.0 <= efficiency <= 1.0:
            raise ValueError("turbine %s has an efficiency outside 0..1" % name)
        checked.append((name, float(capacity), float(efficiency)))
    return checked


def validate_flow(flow):
    """Return the daily flow values as floats, rejecting negative readings."""
    readings = []
    for day, value in enumerate(flow, start=1):
        if value < 0:
            raise ValueError("day %d has a negative water flow" % day)
        readings.append(float(value))
    return readings


def yields(turbines, flow):
    """Total energy produced plus the ids of turbines that ever fell short."""
    plant = validate_turbines(turbines)
    readings = validate_flow(flow)
    total = 0.0
    underperforming = []
    for water in readings:
        for name, capacity, efficiency in plant:
            energy = capacity * efficiency * water
            total += energy
            if energy < 10.0:
                if name not in underperforming:
                    underperforming.append(name)
    return total, underperforming


def format_report(total, underperforming, days):
    """Build a short human readable summary of a production run."""
    lines = ["Days simulated: %d" % days, "Total energy: %.2f units" % total]
    if days:
        lines.append("Daily average: %.2f units" % (total / days))
    if underperforming:
        lines.append("Underperforming turbines:")
        for name in underperforming:
            lines.append("  - %s" % name)
    else:
        lines.append("All turbines met the ten unit threshold every day.")
    return "\n".join(lines)


def main():
    turbines = [
        ("alpha", 120.0, 0.85),
        ("beta", 40.0, 0.60),
        ("gamma", 5.0, 0.40),
    ]
    flow = [1.0, 0.8, 0.35, 1.4, 0.2]
    total, weak = yields(turbines, flow)
    print(format_report(total, weak, len(flow)))
    for name, capacity, efficiency in turbines:
        share = capacity * efficiency * sum(flow)
        if total:
            print("%-6s contributed %5.1f%%" % (name, 100.0 * share / total))
        else:
            print("%-6s contributed nothing" % name)


if __name__ == "__main__":
    main()

