def validate(crates, limit):
    """Return the crate list as validated integers, raising on bad input."""
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise TypeError("limit must be an integer")
    if limit <= 0:
        raise ValueError("limit must be positive")
    checked = []
    for crate in crates:
        if not isinstance(crate, int) or isinstance(crate, bool):
            raise TypeError("crate weights must be integers")
        if crate < 0:
            raise ValueError("crate weights must not be negative")
        checked.append(crate)
    return checked


def load(crates, limit):
    """Pack crates into flights, returning (flight count, skipped weight)."""
    weights = validate(crates, limit)
    flights = 0
    payload = 0
    skipped = 0
    for weight in weights:
        if weight > limit:
            skipped += weight
            continue
        if flights == 0 or payload + weight > limit:
            flights += 1
            payload = weight
        else:
            payload += weight
    return flights, skipped


def manifest(crates, limit):
    """Build the list of per-flight crate lists produced by the same rules."""
    weights = validate(crates, limit)
    flights = []
    for weight in weights:
        if weight > limit:
            continue
        if not flights or sum(flights[-1]) + weight > limit:
            flights.append([weight])
        else:
            flights[-1].append(weight)
    return flights


def report(crates, limit):
    """Render a human readable summary of a loading plan."""
    count, skipped = load(crates, limit)
    lines = ["Limit per flight: {0}".format(limit)]
    for index, flight in enumerate(manifest(crates, limit), start=1):
        crate_text = " + ".join(str(weight) for weight in flight)
        lines.append("  Flight {0}: {1} = {2}".format(index, crate_text, sum(flight)))
    if count == 0:
        lines.append("  No flights needed")
    if skipped:
        lines.append("  Skipped weight: {0}".format(skipped))
    lines.append("Total flights: {0}".format(count))
    return "\n".join(lines)


def main():
    cases = [
        ([10, 20, 30, 40, 50], 60),
        ([70, 15, 5, 80, 25], 50),
        ([], 100),
        ([200, 300], 100),
    ]
    for crates, limit in cases:
        print(report(crates, limit))
        print()


if __name__ == "__main__":
    main()

