def parse_coin(line):
    """Turn a 'metal,year,face,condition' record into a coin tuple."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 4:
        raise ValueError("a coin record needs exactly four fields: " + line)
    metal, year, face, condition = parts
    return (metal.lower(), int(year), float(face), condition.lower())


def validate(coins, threshold):
    """Reject collections that cannot be priced."""
    if not isinstance(threshold, int):
        raise TypeError("threshold must be an integer year")
    for index, coin in enumerate(coins):
        if len(coin) != 4:
            raise ValueError("coin %d is malformed: %r" % (index, coin))
        metal, year, face, condition = coin
        if not metal:
            raise ValueError("coin %d has no metal" % index)
        if not condition:
            raise ValueError("coin %d has no condition grade" % index)
        if face < 0:
            raise ValueError("coin %d has a negative face value" % index)
        if year < 0:
            raise ValueError("coin %d has an impossible mint year" % index)


def coin_value(coin, threshold):
    """Adjusted worth of a single coin."""
    year, face, condition = coin[1], coin[2], coin[3]
    worth = face
    if year < threshold:
        worth *= 5
    if condition == "mint":
        worth *= 2
    return worth


def value(coins, threshold):
    """Total adjusted worth of the whole collection."""
    validate(coins, threshold)
    total = 0.0
    for coin in coins:
        total += coin_value(coin, threshold)
    return total


def report(coins, threshold):
    """Build a human readable breakdown of the collection."""
    header = "%-10s %6s %8s %10s %10s" % ("METAL", "YEAR", "FACE", "COND", "WORTH")
    lines = [header]
    for coin in coins:
        metal, year, face, condition = coin
        worth = coin_value(coin, threshold)
        lines.append("%-10s %6d %8.2f %10s %10.2f" % (metal, year, face, condition, worth))
    lines.append("%-10s %6s %8s %10s %10.2f" % ("TOTAL", "", "", "", value(coins, threshold)))
    return "\n".join(lines)


def main():
    records = [
        "gold, 1885, 20.0, mint",
        "silver, 1964, 0.25, good",
        "copper, 1943, 0.01, mint",
        "nickel, 2001, 0.05, worn",
    ]
    threshold = 1950
    coins = [parse_coin(record) for record in records]
    print(report(coins, threshold))
    mints = [coin for coin in coins if coin[3] == "mint"]
    if mints:
        print("mint-state coins contribute %.2f" % value(mints, threshold))


if __name__ == "__main__":
    main()

