def validate_waypoints(waypoints):
    """Check that every waypoint is a usable (x, y, status) triple."""
    if not isinstance(waypoints, list):
        raise TypeError("waypoints must be a list of tuples")
    for index, point in enumerate(waypoints):
        if not isinstance(point, tuple) or len(point) != 3:
            raise ValueError("waypoint %d must be a 3-tuple" % index)
        x, y, status = point
        if not isinstance(x, int) or not isinstance(y, int):
            raise ValueError("waypoint %d has non-integer coordinates" % index)
        if status not in ("clear", "obstructed"):
            raise ValueError("waypoint %d has unknown status %r" % (index, status))
    return True


def segment_distance(origin, destination):
    """Manhattan distance between two waypoints plus any obstruction penalty."""
    x1, y1 = origin[0], origin[1]
    x2, y2, status = destination
    distance = abs(x2 - x1) + abs(y2 - y1)
    if status == "obstructed":
        distance += 20
    return distance


def route(waypoints):
    """Total travel distance for the crawler across all waypoints."""
    validate_waypoints(waypoints)
    total = 0
    for index in range(1, len(waypoints)):
        total += segment_distance(waypoints[index - 1], waypoints[index])
    return total


def segment_report(waypoints):
    """Build a list of (leg_label, distance, running_total) rows."""
    validate_waypoints(waypoints)
    rows = []
    running = 0
    for index in range(1, len(waypoints)):
        origin = waypoints[index - 1]
        destination = waypoints[index]
        distance = segment_distance(origin, destination)
        running += distance
        label = "(%d,%d)->(%d,%d)" % (origin[0], origin[1],
                                      destination[0], destination[1])
        rows.append((label, distance, running))
    return rows


def format_report(waypoints):
    """Render the leg-by-leg report as printable lines."""
    rows = segment_report(waypoints)
    if not rows:
        return ["no travel required"]
    lines = []
    for label, distance, running in rows:
        lines.append("%-22s %4d %6d" % (label, distance, running))
    lines.append("total: %d" % rows[-1][2])
    return lines


def main():
    courses = {
        "survey loop": [(0, 0, "clear"), (3, 4, "clear"), (3, 4, "obstructed"),
                        (-2, 1, "clear")],
        "depot run": [(5, 5, "clear"), (5, -5, "obstructed")],
        "parked": [(1, 1, "clear")],
    }
    for name in sorted(courses):
        waypoints = courses[name]
        print("%s (%d waypoints, distance %d)"
              % (name, len(waypoints), route(waypoints)))
        for line in format_report(waypoints):
            print("    " + line)


if __name__ == "__main__":
    main()

