def validate(deposits, withdrawals):
    """Check that the two monthly series are usable and equal in length."""
    if len(deposits) != len(withdrawals):
        raise ValueError("deposits and withdrawals must cover the same months")
    for month, (incoming, outgoing) in enumerate(zip(deposits, withdrawals), start=1):
        if incoming < 0:
            raise ValueError("negative deposit in month %d" % month)
        if outgoing < 0:
