def levels(deposits, withdrawals):
    """Return (total sold tonnage, total deficit tonnage) for the silo year."""
    validate(deposits, withdrawals)
    tonnage = INITIAL_TONNAGE
    sold = 0.0
    deficit = 0.0
    for incoming, outgoing in zip(deposits, withdrawals):
        tonnage += incoming - outgoing
        if tonnage > MAX_CAPACITY:
            sold += tonnage - MAX_CAPACITY
            tonnage = MAX_CAPACITY
        elif tonnage < 0.0:
            deficit += -tonnage
            tonnage = 0.0
    return sold, deficit


def monthly_trace(deposits, withdrawals):
    """Build a list of (month, deposit, withdrawal, closing tonnage) rows."""
    validate(deposits, withdrawals)
    tonnage = INITIAL_TONNAGE
    rows = []
    for month, (incoming, outgoing) in enumerate(zip(deposits, withdrawals), start=1):
        tonnage += incoming - outgoing
        if tonnage > MAX_CAPACITY:
            tonnage = MAX_CAPACITY
        elif tonnage < 0.0:
            tonnage = 0.0
        rows.append((month, incoming, outgoing, tonnage))
    return rows


def format_report(deposits, withdrawals):
    """Render the month-by-month trace plus the sold/deficit summary."""
    lines = ["month     in      out    stock"]
    for month, incoming, outgoing, tonnage in monthly_trace(deposits, withdrawals):
        lines.append("%5d %7.1f %7.1f %8.1f" % (month, incoming, outgoing, tonnage))
    sold, deficit = levels(deposits, withdrawals)
    lines.append("sold off: %.1f t" % sold)
    lines.append("deficit:  %.1f t" % deficit)
    if deficit > 0.0:
        lines.append("warning: silo ran empty during the season")
    return "\n".join(lines)


