COST_PER_ITEM = {"bowl": 2, "plate": 3, "vase": 5}


def batch_cost(shape, quantity):
    """Return the supply needed to glaze `quantity` items of `shape`."""
    if shape not in COST_PER_ITEM:
        raise ValueError("unknown pot shape: {!r}".format(shape))
    if quantity < 0:
        raise ValueError("quantity must not be negative: {}".format(quantity))
    return COST_PER_ITEM[shape] * quantity


def validate_supply(supply):
    """Reject a supply figure that cannot describe a real amount of glaze."""
    if not isinstance(supply, int) or isinstance(supply, bool):
        raise TypeError("supply must be an integer")
    if supply < 0:
        raise ValueError("supply must not be negative")
    return supply


def glaze(pots, supply):
    """Glaze the batches that fit, returning finished shapes and leftovers."""
    remaining = validate_supply(supply)
    completed = []
    for shape, quantity in pots:
        cost = batch_cost(shape, quantity)
        if cost <= remaining:
            remaining -= cost
            completed.append(shape)
    return completed, remaining


def skipped_batches(pots, completed):
    """List the batches that were passed over, in processing order."""
    pending = list(completed)
    skipped = []
    for shape, quantity in pots:
        if pending and pending[0] == shape:
            pending.pop(0)
        else:
            skipped.append((shape, quantity))
    return skipped


def format_report(pots, supply):
    """Build a human readable summary of one glazing run."""
    completed, remaining = glaze(pots, supply)
    lines = ["Supply: {} units".format(supply)]
    for shape, quantity in pots:
        cost = batch_cost(shape, quantity)
        lines.append("  {} x{} needs {} units".format(shape, quantity, cost))
    if completed:
        lines.append("Glazed: " + ", ".join(completed))
    else:
        lines.append("Glazed: nothing")
    for shape, quantity in skipped_batches(pots, completed):
        lines.append("Skipped: {} x{}".format(shape, quantity))
    lines.append("Remaining: {} units".format(remaining))
    return "\n".join(lines)


def main():
    runs = [
        ([("bowl", 3), ("plate", 2), ("vase", 1)], 20),
        ([("vase", 4), ("bowl", 1)], 6),
        ([("plate", 1), ("plate", 1), ("plate", 1)], 7),
    ]
    totals = {}
    leftover = 0
    for pots, supply in runs:
        print(format_report(pots, supply))
        print("-" * 32)
        completed, remaining = glaze(pots, supply)
        leftover += remaining
        for shape in completed:
            totals[shape] = totals.get(shape, 0) + 1
    for shape in sorted(totals):
        print("{}: {} batches glazed".format(shape, totals[shape]))
    print("Unused glaze across all runs: {} units".format(leftover))


if __name__ == "__main__":
    main()

