def validate(passengers):
    """Check that every entry is a well formed passenger tuple."""
    cleaned = []
    for index, entry in enumerate(passengers):
        if not isinstance(entry, tuple) or len(entry) != 3:
            raise ValueError("passenger %d must be a 3-tuple" % index)
        name, tier, needs = entry
        if not isinstance(name, str) or not name.strip():
            raise ValueError("passenger %d has an empty name" % index)
        if not isinstance(tier, int) or isinstance(tier, bool):
            raise ValueError("passenger %s has a non-integer tier" % name)
        if not isinstance(needs, bool):
            raise ValueError("passenger %s has a non-boolean needs flag" % name)
        cleaned.append((name.strip(), tier, needs))
    return cleaned


def split_groups(passengers):
    """Return the assistance, VIP and standard groups, each sorted by name."""
    assistance = []
    vip = []
    standard = []
    for name, tier, needs in passengers:
        if needs:
            assistance.append(name)
        elif tier > 5:
            vip.append(name)
        else:
            standard.append(name)
    return sorted(assistance), sorted(vip), sorted(standard)


def board(passengers):
    """Determine the order in which guests enter the liner."""
    assistance, vip, standard = split_groups(validate(passengers))
    return assistance + vip + standard


def manifest(passengers):
    """Build a printable boarding manifest with group labels."""
    assistance, vip, standard = split_groups(validate(passengers))
    labelled = [
        ("Assistance", assistance),
        ("VIP", vip),
        ("Standard", standard),
    ]
    lines = []
    position = 1
    for label, group in labelled:
        if not group:
            lines.append("%s: none" % label)
            continue
        for name in group:
            lines.append("%2d. %-12s %s" % (position, name, label))
            position += 1
    return "\n".join(lines)


def main():
