def normalize(stitch):
    """Reduce a raw operation string to a canonical lowercase token."""
    if not isinstance(stitch, str):
        raise TypeError("operations must be strings, got %r" % (stitch,))
    token = stitch.strip().lower()
    aliases = {"k": "knit", "p": "purl", "d": "drop"}
    if token in aliases:
        return aliases[token]
    return token


def analyze(stitches):
    """Count drops and flag structural/boundary problems in an operation list."""
    knits = 0
    purls = 0
    drops = 0
    run = 0
    structural_flaw = False
    boundary_violation = False
    for index, raw in enumerate(stitches):
        op = normalize(raw)
        if op == "knit":
            knits += 1
            run = 0
        elif op == "purl":
            purls += 1
            run = 0
            if index == 0:
                boundary_violation = True
        elif op == "drop":
            drops += 1
            run += 1
            if run >= 3:
                structural_flaw = True
        else:
            raise ValueError("unknown operation at position %d: %s" % (index, raw))
    return (drops, structural_flaw, boundary_violation)


def summarize(stitches):
    """Build a per-operation tally alongside the analysis result."""
    tally = {"knit": 0, "purl": 0, "drop": 0}
    for raw in stitches:
        tally[normalize(raw)] += 1
    return tally, analyze(stitches)


def format_report(name, stitches):
    """Render a one-block human readable report for a named sequence."""
    tally, (drops, flaw, boundary) = summarize(stitches)
    lines = ["%s (%d operations)" % (name, len(stitches))]
    for op in ("knit", "purl", "drop"):
        lines.append("  %-5s : %d" % (op, tally[op]))
    lines.append("  drop count reported: %d" % drops)
    if flaw:
        lines.append("  structural flaw: three consecutive drops")
    if boundary:
        lines.append("  boundary violation: sequence opens with purl")
    if not flaw and not boundary:
        lines.append("  sequence is clean")
    return "\n".join(lines)


def main():
    samples = [
        ("plain rib", ["knit", "purl", "knit", "purl"]),
        ("dropped edge", ["p", "k", "d", "d", "d", "k"]),
        ("scattered drops", ["knit", "drop", "drop", "knit", "drop", "drop"]),
        ("all dropped", ["d", "d", "d", "d"]),
    ]
    for name, stitches in samples:
        print(format_report(name, stitches))
        print()
    bad = ["knit", "twist"]
    try:
        analyze(bad)
    except ValueError as exc:
        print("rejected sequence:", exc)


if __name__ == "__main__":
    main()

