def vine_yield(variety, age):
	"""Return the units produced by a single vine of the given variety and age."""
	rules = {
		"merlot": (4, 20.0, 0.0),
		"chardonnay": (6, 30.0, 10.0),
	}
	key = variety.strip().lower()
	if key not in rules:
		raise ValueError("unknown grape variety: {0}".format(variety))
	threshold, mature_yield, young_yield = rules[key]
	if age > threshold:
		return mature_yield
	return young_yield


def validate_vines(vines):
	"""Check every vine record and return a list of cleaned (variety, age) pairs."""
	cleaned = []
	for index, vine in enumerate(vines):
		if len(vine) != 2:
			raise ValueError("vine {0} must hold a variety and an age".format(index))
		variety, age = vine
		if not isinstance(age, int):
			raise TypeError("vine {0} has a non-integer age".format(index))
		if age < 0:
			raise ValueError("vine {0} has a negative age".format(index))
		cleaned.append((variety.strip().lower(), age))
	return cleaned


def weather_multiplier(weather):
	"""Translate a weather condition into a multiplicative yield factor."""
	modifiers = {
		"frost": -0.30,
		"sunny": 0.15,
	}
	return 1.0 + modifiers.get(weather.strip().lower(), 0.0)


def harvest(vines, weather):
	"""Forecast the total yield in units for the given vines and weather."""
	total = 0.0
	for variety, age in validate_vines(vines):
		total += vine_yield(variety, age)
	return float(total * weather_multiplier(weather))


def summarize_by_variety(vines):
	"""Group the base (weather-free) yield of the vineyard by grape variety."""
	totals = {}
	for variety, age in validate_vines(vines):
		totals[variety] = totals.get(variety, 0.0) + vine_yield(variety, age)
	return totals


def format_report(vines, conditions):
	"""Build a plain-text forecast comparing the yield under several conditions."""
	lines = ["Vineyard forecast for {0} vines".format(len(vines))]
	for variety, units in sorted(summarize_by_variety(vines).items()):
		lines.append("  {0:<12} {1:8.1f} units".format(variety, units))
	for weather in conditions:
		lines.append("  {0:<12} {1:8.1f} units total".format(weather, harvest(vines, weather)))
	return "\n".join(lines)


def main():
	vineyard = [
		("merlot", 3),
		("merlot", 7),
		("Chardonnay", 6),
		("chardonnay", 12),
	]
	print(format_report(vineyard, ["frost", "sunny", "overcast"]))


if __name__ == "__main__":
	main()

