EMPTY = '.'
TURN = 'T'
FILTER = 'F'
BLOCK = '#'
START_PRESSURE = 100
PRESSURE_COST = {EMPTY: 1, TURN: 5, FILTER: 10}


def parse_rows(text):
    grid = []
    for line in text.strip().splitlines():
        stripped = line.strip()
        if stripped:
            grid.append(list(stripped))
    return grid


def validate_grid(grid):
    if not grid or not grid[0]:
        raise ValueError("the aqueduct needs at least one row and one column")
    width = len(grid[0])
    for index, row in enumerate(grid):
        if len(row) != width:
            raise ValueError("row %d holds %d tiles, expected %d" % (index, len(row), width))
        for tile in row:
            if tile != BLOCK and tile not in PRESSURE_COST:
                raise ValueError("unknown aqueduct tile: %r" % tile)
    if grid[0][0] == BLOCK:
        raise ValueError("the aqueduct entrance is blocked")
    return len(grid), width


def count_adjacent_blockages(grid, row, col):
    height, width = len(grid), len(grid[0])
    total = 0
    for delta_row, delta_col in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        near_row, near_col = row + delta_row, col + delta_col
        if 0 <= near_row < height and 0 <= near_col < width:
            if grid[near_row][near_col] == BLOCK:
                total += 1
        else:
            total += 1
    return total


def choose_detour(grid, row, col):
    height, width = len(grid), len(grid[0])
    options = []
    for heading, next_row, next_col in (("down", row + 1, col), ("right", row, col + 1)):
        if 0 <= next_row < height and 0 <= next_col < width:
            if grid[next_row][next_col] != BLOCK:
                crowding = count_adjacent_blockages(grid, next_row, next_col)
                options.append((crowding, heading, next_row, next_col))
    if not options:
        return None
    options.sort(key=lambda option: option[0])
    return options[0][1:]


def flow(grid):
    height, width = validate_grid(grid)
    row, col, pressure, heading = 0, 0, START_PRESSURE, "right"
    while pressure > 0:
        if heading == "right":
            next_row, next_col = row, col + 1
        else:
            next_row, next_col = row + 1, col
        inside = 0 <= next_row < height and 0 <= next_col < width
        if not inside or grid[next_row][next_col] == BLOCK:
            detour = choose_detour(grid, row, col)
            if detour is None:
                break
            heading, next_row, next_col = detour
        row, col = next_row, next_col
        pressure -= PRESSURE_COST[grid[row][col]]
        if grid[row][col] == TURN:
            heading = "down" if heading == "right" else "right"
    return (row, col, max(pressure, 0))


def format_report(label, grid, result):
    row, col, pressure = result
    lines = ["%s: %d x %d aqueduct" % (label, len(grid), len(grid[0]))]
    lines.append("  water stopped at row %d, column %d with pressure %d" % (row, col, pressure))
    if pressure == 0:
        lines.append("  the channel drained the flow before it arrived")
    elif (row, col) == (len(grid) - 1, len(grid[0]) - 1):
        lines.append("  water was delivered to the far corner")
    else:
        lines.append("  blockages trapped the water mid-channel")
    return "\n".join(lines)


def main():
    straight = parse_rows("""
        .........T
        ..........
        ..........
        ..........
        ..........
        ..........
        ..........
        ..........
        ..........
        ..........
    """)
    blocked = parse_rows("""
        .....#....
        .....#....
        .....#....
        .....#....
        .....#....
        ..........
        ..........
        ..........
        ..........
        ....T..F..
    """)
    for label, grid in (("straight run", straight), ("blocked run", blocked)):
        print(format_report(label, grid, flow(grid)))


if __name__ == "__main__":
    main()

