import math
from collections import defaultdict

THRESHOLD = 15.0


def distance(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def find(parent, index):
    root = index
    while parent[root] != root:
        root = parent[root]
    while parent[index] != root:
        parent[index], index = root, parent[index]
    return root


def union(parent, size, first, second):
    left = find(parent, first)
    right = find(parent, second)
    if left == right:
        return False
    if size[left] < size[right]:
        left, right = right, left
    parent[right] = left
    size[left] += size[right]
    return True


def validate(stars):
    points = []
    for star in stars:
        if len(star) != 2:
            raise ValueError("each star needs exactly two coordinates: %r" % (star,))
        x, y = star
        points.append((float(x), float(y)))
    return points


def groups(stars):
    points = validate(stars)
    count = len(points)
    parent = list(range(count))
    size = [1] * count
    for i in range(count):
        for j in range(i + 1, count):
            if distance(points[i], points[j]) <= THRESHOLD:
                union(parent, size, i, j)
    clusters = defaultdict(list)
    for index in range(count):
        clusters[find(parent, index)].append(points[index])
    return [members for members in clusters.values() if len(members) >= 4]


def constellations(stars):
    return len(groups(stars))


def report(stars):
    found = sorted(groups(stars), key=len, reverse=True)
    lines = ["%d stars scanned" % len(stars)]
    for number, members in enumerate(found, 1):
        cx = sum(point[0] for point in members) / len(members)
        cy = sum(point[1] for point in members) / len(members)
        template = "constellation %d: %d stars centred at (%.1f, %.1f)"
        lines.append(template % (number, len(members), cx, cy))
    if not found:
        lines.append("no constellations found")
    return "\n".join(lines)


def main():
    cluster = [(0, 0), (5, 5), (10, 2), (3, 9), (7, 12)]
    scattered = [(200, 4), (400, 80), (600, 150), (800, 25), (1000, 300)]
    sky = cluster + scattered
    print(report(sky))
    print("total: %d" % constellations(sky))


if __name__ == "__main__":
    main()

