THRESHOLD = 50.0
MIN_DISHES = 3


def validate(signals):
    """Check that the input really is a non-empty table of numeric readings."""
    if not isinstance(signals, list):
        raise TypeError("signals must be a list of dish recordings")
    if not signals:
        raise ValueError("at least one dish is required")
    for index, row in enumerate(signals):
        if not isinstance(row, list):
            raise TypeError("dish {} did not provide a list".format(index))
        for step, value in enumerate(row):
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(
                    "dish {} step {} is not a frequency".format(index, step)
                )


def collect_events(signals):
    """Return (time, dishes, peak) for every valid astronomical event."""
    validate(signals)
    span = 0
    for row in signals:
        if len(row) > span:
            span = len(row)
    events = []
    for time in range(span):
        spiking = []
        recording = 0
        for index, row in enumerate(signals):
            if time < len(row):
                recording += 1
                if row[time] > THRESHOLD:
                    spiking.append((index, row[time]))
        if len(spiking) < MIN_DISHES:
            continue
        if len(spiking) == recording:
            continue
        peak = spiking[0][1]
        for index, value in spiking:
            if value > peak:
                peak = value
        events.append((time, [index for index, value in spiking], peak))
    return events


def scan(signals):
    """Count valid events and report the loudest frequency among them."""
    events = collect_events(signals)
    peak = 0
    for time, dishes, value in events:
        if value > peak:
            peak = value
    return len(events), peak


def report(signals):
    count, peak = scan(signals)
    lines = ["dishes: {}".format(len(signals))]
    for time, dishes, value in collect_events(signals):
        joined = ", ".join(str(dish) for dish in dishes)
        lines.append("  t={} dishes=[{}] peak={}".format(time, joined, value))
    if count == 0:
        lines.append("no astronomical events detected")
    else:
        lines.append("events={} max_frequency={}".format(count, peak))
    return "\n".join(lines)


def main():
    sky = [
        [60, 55, 60, 10, 10, 20, 10, 12, 11, 10],
        [70, 55, 60, 10, 10, 55, 10, 13, 12, 10],
        [80, 55, 10, 10, 10, 65, 10, 14, 13, 10],
        [10, 55, 10, 10, 10, 75, 10, 15, 14, 10],
    ]
    print(report(sky))
    print(scan(sky))


if __name__ == "__main__":
