SEASONS = ("winter", "spring", "summer", "autumn")
STARTING_MASS = 10000
WINTER_GAIN = 50
SUMMER_LOSS_PER_DEGREE = 10
RESIDUAL_LOSS = 20
HOT_SUMMER = 20


def parse_entry(entry):
    """Validate one (season, temperature) pair and return it normalised."""
    if not isinstance(entry, (tuple, list)) or len(entry) != 2:
        raise ValueError("each climate entry needs a season and a temperature")
    name, temperature = entry
    if not isinstance(name, str):
        raise TypeError("season names must be strings")
    season = name.strip().lower()
    if season not in SEASONS:
        raise ValueError("unknown season: %r" % (name,))
    if not isinstance(temperature, (int, float)):
        raise TypeError("temperatures must be numeric")
    return season, float(temperature)


def glacier(climate):
    """Return the final mass of a glacier exposed to the given climate."""
    mass = STARTING_MASS
    previous = None
    for entry in climate:
        season, temperature = parse_entry(entry)
        if mass <= 0:
            return 0
        if season == "winter":
            if temperature < 0:
                mass += WINTER_GAIN
        elif season == "summer":
            if temperature > 0:
                mass -= SUMMER_LOSS_PER_DEGREE * temperature
        elif previous is not None:
            last_season, last_temperature = previous
            if last_season == "summer" and last_temperature > HOT_SUMMER:
                mass -= RESIDUAL_LOSS
        if mass < 0:
            mass = 0
        previous = (season, temperature)
    return mass


def alternating_climate(years, winter_temperature, summer_temperature):
    """Build a climate of cold winters followed by summers, one pair per year."""
    climate = []
    for _ in range(years):
        climate.append(("winter", winter_temperature))
        climate.append(("summer", summer_temperature))
    return climate


def season_counts(climate):
    counts = {}
    for entry in climate:
        season, _temperature = parse_entry(entry)
        if season in counts:
            counts[season] += 1
        else:
            counts[season] = 1
    return counts


def format_report(label, climate):
    lines = ["%s: %d seasons" % (label, len(climate))]
    counts = season_counts(climate)
    for season in SEASONS:
        if season in counts:
            lines.append("  %-7s x%d" % (season, counts[season]))
    lines.append("  final mass: %g" % glacier(climate))
    return "\n".join(lines)


def main():
    mild = alternating_climate(10, -5.0, 3.0)
    harsh = []
    for year in range(10):
        harsh.extend([("winter", 2.0), ("spring", 8.0),
                      ("summer", 25.0 + year), ("autumn", 6.0)])
    for label, climate in (("Mild cycle", mild), ("Warming cycle", harsh)):
        print(format_report(label, climate))


if __name__ == "__main__":
    main()

