def parse_slope(entry):
    """Validate one mountain face record and return it as floats."""
    if not isinstance(entry, (tuple, list)):
        raise TypeError("each slope must be a tuple of three values")
    if len(entry) != 3:
        raise ValueError("each slope needs an angle, snowfall and temperature shift")
    values = []
    for value in entry:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("slope measurements must be numbers")
        values.append(float(value))
    angle, snowfall, shift = values
    if angle < 0.0 or angle > 90.0:
        raise ValueError("steepness angle must lie between 0 and 90 degrees")
    if snowfall < 0.0:
        raise ValueError("snowfall cannot be negative")
    return angle, snowfall, shift


def snowfall_threshold(shift):
    """Warm weather settles the snowpack, so more snow is tolerated."""
    if shift > 5.0:
        return 30.0
    return 20.0


def is_dangerous(angle, snowfall, shift):
    """A face is dangerous when it is steep enough and loaded with fresh snow."""
    if 30.0 <= angle <= 45.0:
        return snowfall > snowfall_threshold(shift)
    return False


def avalanche(slopes):
    """Return [dangerous count, safe count] for the given mountain faces."""
    dangerous = 0
    safe = 0
    for entry in slopes:
        angle, snowfall, shift = parse_slope(entry)
        if is_dangerous(angle, snowfall, shift):
            dangerous += 1
        else:
            safe += 1
    return [dangerous, safe]


def describe(slopes):
    """Build a per-face report describing why each verdict was reached."""
    lines = []
    for index, entry in enumerate(slopes, start=1):
        angle, snowfall, shift = parse_slope(entry)
        limit = snowfall_threshold(shift)
        if is_dangerous(angle, snowfall, shift):
            verdict = "DANGEROUS"
        else:
            verdict = "safe"
        lines.append(
            "Face {0}: {1:.1f} deg, {2:.1f} units of snow, shift {3:+.1f} "
            "(limit {4:.0f}) -> {5}".format(index, angle, snowfall, shift, limit, verdict)
        )
    return lines


def main():
    faces = [
        (35.0, 25.0, 0.0),
        (40.0, 35.0, 8.0),
        (20.0, 50.0, -2.0),
        (44.0, 22.0, 6.5),
    ]
    for line in describe(faces):
        print(line)
    dangerous, safe = avalanche(faces)
    print("Dangerous slopes: {0}".format(dangerous))
    print("Safe slopes: {0}".format(safe))
    if dangerous > safe:
        print("Advisory: avoid the backcountry today.")
    else:
        print("Advisory: travel with normal caution.")


if __name__ == "__main__":
    main()

