SPEEDS = {"clear": 60.0, "rainy": 40.0, "windy": 50.0}
MAX_CONTINUOUS_HOURS = 10.0
REST_HOURS = 12.0


def speed_for(weather):
    """Return the pigeon's cruising speed in km/h for a weather condition."""
    key = str(weather).strip().lower()
    if key not in SPEEDS:
        raise ValueError("unknown weather condition: {!r}".format(weather))
    return SPEEDS[key]


def validate(checkpoints):
    """Check that every checkpoint is a (distance, weather) pair we can fly."""
    for number, leg in enumerate(checkpoints, start=1):
        if len(leg) != 2:
            raise ValueError("checkpoint {} must be a (distance, weather) pair".format(number))
        distance, weather = leg
        if not isinstance(distance, (int, float)) or isinstance(distance, bool):
            raise TypeError("checkpoint {} has a non-numeric distance".format(number))
        if distance < 0:
            raise ValueError("checkpoint {} has a negative distance".format(number))
        speed_for(weather)


def race_log(checkpoints):
    """Build the ordered list of flying and resting events for the whole race."""
    validate(checkpoints)
    events = []
    continuous = 0.0
    elapsed = 0.0
    for number, (distance, weather) in enumerate(checkpoints, start=1):
        hours = distance / speed_for(weather)
        continuous += hours
        elapsed += hours
        events.append(("fly", number, hours, elapsed))
        if continuous > MAX_CONTINUOUS_HOURS:
            elapsed += REST_HOURS
            continuous = 0.0
            events.append(("rest", number, REST_HOURS, elapsed))
    return events


def pigeons(checkpoints):
    """Total hours, rests included, for the pigeon to pass all checkpoints."""
    events = race_log(checkpoints)
    if not events:
        return 0
    return round(events[-1][3])


def format_report(checkpoints):
    """Render the race as human-readable lines, one per flight leg or rest."""
    lines = []
    for kind, number, hours, elapsed in race_log(checkpoints):
        distance, weather = checkpoints[number - 1]
        if kind == "fly":
            lines.append("leg {}: {:.0f} km in {} weather, {:.2f} h (elapsed {:.2f} h)".format(
                number, distance, str(weather).strip().lower(), hours, elapsed))
        else:
            lines.append("rest after leg {}: {:.0f} h (elapsed {:.2f} h)".format(
                number, hours, elapsed))
    return lines


def main():
    races = [
        ("long clear haul", [(500, "clear"), (500, "clear"), (500, "clear")]),
        ("mixed weather", [(300, "rainy"), (250, "windy"), (180, "clear"), (420, "rainy")]),
    ]
    for name, checkpoints in races:
        print(name)
        for line in format_report(checkpoints):
            print("  " + line)
        print("  total: {} h".format(pigeons(checkpoints)))


if __name__ == "__main__":
    main()

