WIDTH = 100
LENGTH = 200


def _decay(velocity):
    """Reduce the magnitude of one velocity component by one unit of friction."""
    if velocity > 0:
        return velocity - 1
    if velocity < 0:
        return velocity + 1
    return 0


def _reflect(position, limit):
    """Fold a position back inside [0, limit], reporting bounces and direction flips."""
    bounces = 0
    flipped = False
    while position < 0 or position > limit:
        if position < 0:
            position = -position
        else:
            position = 2 * limit - position
        flipped = not flipped
        bounces += 1
    return position, bounces, flipped


def _validate(shots):
    """Turn the raw input into a list of integer velocity pairs."""
    if not isinstance(shots, (list, tuple)):
        raise TypeError("shots must be a list of (vx, vy) tuples")
    cleaned = []
    for index, shot in enumerate(shots):
        if len(shot) != 2:
            raise ValueError("shot %d must hold exactly two velocities" % index)
        vx, vy = shot
        for component in (vx, vy):
            if not isinstance(component, int):
                raise TypeError("shot %d has a non-integer velocity" % index)
        cleaned.append((vx, vy))
    return cleaned


def simulate_shot(vx, vy):
    """Count the cushion bounces of one cue ball struck from the table centre."""
    x, y = WIDTH / 2.0, LENGTH / 2.0
    bounces = 0
    while vx != 0 or vy != 0:
        x, hits, flipped = _reflect(x + vx, WIDTH)
        bounces += hits
        if flipped:
            vx = -vx
        y, hits, flipped = _reflect(y + vy, LENGTH)
        bounces += hits
        if flipped:
            vy = -vy
        vx = _decay(vx)
        vy = _decay(vy)
    return bounces


def billiards(shots):
    """Return the total number of cushion bounces produced by every shot."""
    total = 0
    for vx, vy in _validate(shots):
        total += simulate_shot(vx, vy)
    return total


def format_report(shots):
    """Build a per-shot summary followed by the combined bounce total."""
    lines = []
    for index, (vx, vy) in enumerate(_validate(shots), start=1):
        hits = simulate_shot(vx, vy)
        lines.append("shot %d: vx=%+d vy=%+d -> %d bounce(s)" % (index, vx, vy, hits))
    lines.append("total bounces: %d" % billiards(shots))
    return lines


def main():
    break_shots = [(30, 40), (12, 60), (-25, 25)]
    for line in format_report(break_shots):
        print(line)


if __name__ == "__main__":
    main()

