def validate_profile(profile):
    """Return the profile as a list of (depth, time) pairs of non-negative numbers."""
    if not isinstance(profile, (list, tuple)):
        raise TypeError("profile must be a list of (depth, time) tuples")
    cleaned = []
    for index, segment in enumerate(profile):
        if len(segment) != 2:
            raise ValueError("segment %d must have exactly two values" % index)
        depth, time = segment
        if depth < 0 or time < 0:
            raise ValueError("segment %d has negative depth or time" % index)
        cleaned.append((depth, time))
    return cleaned


def segment_load(depth, time):
    """Nitrogen contribution of a single segment."""
    return depth * time


def stops_for_load(load):
    """Minutes of safety stop needed to bring load down to 500 or less."""
    minutes = 0
    while load > 500:
        load -= 200
        minutes += 3
    return minutes, load


def ascent_points(profile):
    """Indices after which the diver ascends (shallower next, or surfaces)."""
    points = []
    last = len(profile) - 1
    for index, (depth, _time) in enumerate(profile):
        if index == last:
            points.append(index)
        elif profile[index + 1][0] < depth:
            points.append(index)
    return points


def scuba(profile):
    """Total minutes spent at the five metre safety stop during the dive."""
    segments = validate_profile(profile)
    ascents = set(ascent_points(segments))
    load = 0
    total_minutes = 0
    for index, (depth, time) in enumerate(segments):
        load += segment_load(depth, time)
        if index in ascents:
            minutes, load = stops_for_load(load)
            total_minutes += minutes
    return total_minutes


def format_report(name, profile):
    """One line describing a dive plan and its required safety stops."""
    minutes = scuba(profile)
    plan = " -> ".join("%dm/%dmin" % (depth, time) for depth, time in profile)
    if minutes:
        verdict = "%d min of stops at 5m" % minutes
    else:
        verdict = "no stop required"
    return "%-12s %s : %s" % (name, plan, verdict)


def main():
    dives = [
        ("shallow", [(10, 20), (5, 10)]),
        ("recreational", [(18, 30), (12, 15)]),
        ("deep", [(30, 25), (20, 20), (10, 10)]),
        ("multilevel", [(40, 15), (25, 20), (15, 25), (5, 5)]),
    ]
    for name, profile in dives:
        print(format_report(name, profile))


if __name__ == "__main__":
    main()

