def validate_shells(shells):
    """Return a list of cleaned (launch, fuse, color) triples."""
    cleaned = []
    for index, shell in enumerate(shells):
        if len(shell) != 3:
            raise ValueError("shell %d must have launch, fuse and color" % index)
        launch, fuse, color = shell
        if not isinstance(launch, (int, float)) or not isinstance(fuse, (int, float)):
            raise TypeError("shell %d has a non-numeric time" % index)
        if fuse < 0:
            raise ValueError("shell %d has a negative fuse" % index)
        cleaned.append((launch, fuse, str(color).strip().lower()))
    return cleaned


def explosion_schedule(shells):
    """Compute explosion times and sort them chronologically."""
    schedule = []
    for launch, fuse, color in validate_shells(shells):
        schedule.append((launch + fuse, color))
    schedule.sort(key=lambda event: event[0])
    return schedule


def count_dark_skies(schedule, limit=10):
    """One penalty for every gap longer than the given limit."""
    penalties = 0
    for previous, current in zip(schedule, schedule[1:]):
        if current[0] - previous[0] > limit:
            penalties += 1
    return penalties


def count_red_runs(schedule, run=3):
    """One bonus for every window of consecutive red explosions."""
    bonuses = 0
    streak = 0
    for _, color in schedule:
        if color == "red":
            streak += 1
            if streak >= run:
                bonuses += 1
        else:
            streak = 0
    return bonuses


def fireworks(shells):
    schedule = explosion_schedule(shells)
    return count_dark_skies(schedule), count_red_runs(schedule)


def describe_show(shells):
    """Build a human readable report of the show."""
    schedule = explosion_schedule(shells)
    lines = []
    for moment, color in schedule:
        lines.append("t=%6.2fs  %s" % (moment, color))
