from math import floor

FRACTIONS = (1.5, 2.0 / 3.0, 4.0 / 3.0, 2.0, 3.0)
STRONG = (2.0, 3.0)


def validate_planets(planets):
    """Reject malformed planet records before any ratio arithmetic is done."""
    for entry in planets:
        if len(entry) != 3:
            raise ValueError("each planet needs a name, a period and a mass")
        name, period, mass = entry
        if not str(name).strip():
            raise ValueError("planet names must not be empty")
        if period <= 0:
            raise ValueError("orbital period of %s must be positive" % name)
        if mass < 0:
            raise ValueError("mass of %s must not be negative" % name)


def period_ratio(first_period, second_period):
    """Ratio of the two periods, always larger divided by smaller."""
    if first_period >= second_period:
        return first_period / second_period
    return second_period / first_period


def resonance_match(ratio, threshold):
    """Return the exact fraction the ratio locks onto, or None."""
    for fraction in FRACTIONS:
        if abs(ratio - fraction) <= threshold:
            return fraction
        if abs(1.0 / ratio - 1.0 / fraction) <= threshold:
            return fraction
    return None


def resonance_pairs(planets, threshold):
    """All resonant pairs as (name_a, name_b, ratio, fraction, combined_mass)."""
    pairs = []
    for i in range(len(planets)):
        for j in range(i + 1, len(planets)):
            name_a, period_a, mass_a = planets[i]
            name_b, period_b, mass_b = planets[j]
            ratio = period_ratio(period_a, period_b)
            fraction = resonance_match(ratio, threshold)
            if fraction is not None:
                pairs.append((name_a, name_b, ratio, fraction, mass_a + mass_b))
    return pairs


def resonate(planets, threshold):
    if threshold <= 0:
        raise ValueError("threshold must be positive")
    validate_planets(planets)
    counts = {}
    score = 0.0
    for pair in resonance_pairs(planets, threshold):
        score += pair[4]
        if pair[3] in STRONG:
            score += 3.0 * pair[4]
        for name in pair[:2]:
            counts[name] = counts.get(name, 0) + 1
    for name in counts:
        if counts[name] >= 3:
            return -1
    return floor(score)


def describe(fraction):
    if fraction in STRONG:
        return "%d:1 (highly resonant)" % int(fraction)
    return "%.3f" % fraction


def report(label, planets, threshold):
    lines = ["%s (threshold %.3f)" % (label, threshold)]
    for name_a, name_b, ratio, fraction, mass in resonance_pairs(planets, threshold):
        template = "  %s / %s: ratio %.3f near %s, mass %.2f"
        lines.append(template % (name_b, name_a, ratio, describe(fraction), mass))
    score = resonate(planets, threshold)
    if score < 0:
        lines.append("  system is chaotic")
    else:
        lines.append("  stability score: %d" % score)
    return "\n".join(lines)


