def _validate(walls, attackers):
    if not walls:
        raise ValueError("a castle needs at least one wall section")
    for integrity in walls:
        if integrity <= 0:
            raise ValueError("every wall section must start with positive integrity")
    for damage in attackers:
        if damage < 0:
            raise ValueError("daily damage cannot be negative")


def _weakest(current, indices):
    chosen = indices[0]
    for index in indices[1:]:
        if current[index] < current[chosen]:
            chosen = index
    return chosen


def _hit(current, index, amount):
    if amount > current[index]:
        amount = current[index]
    current[index] -= amount


def _intact_neighbours(current, index):
    neighbours = []
    for offset in (-1, 1):
        side = index + offset
        if 0 <= side < len(current) and current[side] > 0:
            neighbours.append(side)
    return neighbours


def _spread_from_breaches(current, breached, share):
    for index in breached:
        targets = _intact_neighbours(current, index)
        if targets:
            doubled = share * 2
            each = doubled // len(targets)
            remainder = doubled % len(targets)
            for target in targets:
                _hit(current, target, each)
            if remainder:
                _hit(current, _weakest(current, targets), remainder)


def _siege_day(current, damage):
    intact = [index for index, value in enumerate(current) if value > 0]
    if intact:
        absorbed = damage // len(intact)
        each = absorbed // len(intact)
        remainder = absorbed % len(intact)
        for index in intact:
            _hit(current, index, each)
        if remainder:
            _hit(current, _weakest(current, intact), remainder)
        breached = [index for index in range(len(current)) if index not in intact]
        _spread_from_breaches(current, breached, each)


def _simulate(walls, attackers):
    current = list(walls)
    for day, damage in enumerate(attackers, start=1):
        _siege_day(current, damage)
        breaches = sum(1 for value in current if value == 0)
        if 2 * breaches > len(walls):
            return True, day
    return False, sum(value for value in current if value > 0)


def defend(walls, attackers):
    _validate(walls, attackers)
    return _simulate(walls, attackers)[1]


def describe(name, walls, attackers):
    _validate(walls, attackers)
    fell, outcome = _simulate(walls, attackers)
    if fell:
        return "%s: the castle fell after %d day(s)" % (name, outcome)
    return "%s: held the siege with %d integrity left" % (name, outcome)


def main():
    sieges = [
        ("Twin towers", [100, 100], [50, 50]),
        ("Frontier keep", [40, 10, 60, 30, 50], [30, 45, 60, 80, 100, 120]),
        ("Lone bastion", [75], [20, 20, 20]),
    ]
    for name, walls, attackers in sieges:
        print(describe(name, walls, attackers))


if __name__ == "__main__":
    main()

