def classify_note(volatility):
    """Map a volatility rating of 1..10 onto its note class."""
    if volatility >= 8:
        return "top"
    if volatility >= 4:
        return "heart"
    return "base"


def validate(ingredients, volume):
    """Reject malformed recipes before any arithmetic is attempted."""
    if volume <= 0:
        raise ValueError("target volume must be positive")
    for family, volatility, added in ingredients:
        if not family:
            raise ValueError("scent family must be named")
        if not 1 <= volatility <= 10:
            raise ValueError("volatility %r outside 1..10" % (volatility,))
        if added < 0:
            raise ValueError("added volume cannot be negative")


def summarize(ingredients):
    """Total the millilitres per note class and collect the families used."""
    notes = {"top": 0.0, "heart": 0.0, "base": 0.0}
    families = set()
    for family, volatility, added in ingredients:
        notes[classify_note(volatility)] += added
        families.add(family.strip().lower())
    return notes, families


def blend(ingredients, volume):
    """Return the longevity score of a mixed perfume, capped at 100."""
    validate(ingredients, volume)
    notes, families = summarize(ingredients)
    if "citrus" in families and "dairy" in families:
        return 0
    score = 100.0
    if notes["top"] > 0.5 * volume:
        score *= 0.8
    if notes["base"] < 0.1 * volume:
        score /= 2
    if "floral" in families and "woody" in families:
        score += 15
    return min(100, round(score))


def format_report(name, ingredients, volume):
    """Render one recipe and its resulting score as a single text line."""
    notes, families = summarize(ingredients)
    parts = []
    for label in ("top", "heart", "base"):
        share = notes[label] / volume * 100
        parts.append("%s %.0f%%" % (label, share))
    shares = ", ".join(parts)
    score = blend(ingredients, volume)
    return "%-14s %3dml  %s  -> %d" % (name, volume, shares, score)


def main():
    recipes = [
        (
            "Spring Bloom",
            [("floral", 5, 40), ("woody", 2, 30), ("citrus", 9, 30)],
            100,
        ),
        (
            "Sharp Cologne",
            [("citrus", 10, 60), ("herbal", 6, 30), ("musk", 3, 10)],
            100,
        ),
        (
            "Milk & Lemon",
            [("dairy", 4, 50), ("citrus", 9, 50)],
            100,
        ),
        (
            "Deep Resin",
            [("woody", 2, 50), ("amber", 3, 30), ("floral", 6, 20)],
            100,
        ),
    ]
    for name, ingredients, volume in recipes:
        try:
            print(format_report(name, ingredients, volume))
        except ValueError as exc:
            print("%-14s rejected: %s" % (name, exc))


if __name__ == "__main__":
    main()

