			raise ValueError("card %d needs a name and an element" % index)
		if not isinstance(power, (int, float)):
			raise ValueError("card %d has a non-numeric power" % index)


def element_types(deck):
	"""Collect the distinct elemental types present in the deck."""
	types = set()
	for _name, element, _power in deck:
		types.add(element.lower())
	return types


def synergize(deck, rules):
	validate_deck(deck)
	combos = normalize_rules(rules)
	tracker = 0.0
	for i in range(len(deck)):
		name_a, element_a, power_a = deck[i]
		for j in range(i + 1, len(deck)):
			name_b, element_b, power_b = deck[j]
			if name_a.lower() == name_b.lower():
				tracker -= 10
			elif frozenset((element_a.lower(), element_b.lower())) in combos:
				tracker += (power_a + power_b) * 1.5
			elif element_a.lower() == element_b.lower():
				tracker += 5
	if len(element_types(deck)) > 5:
		tracker *= 0.75
	return int(tracker)


def format_report(title, deck, rules):
	"""Describe a deck and its synergy rating as printable text."""
	lines = ["%s (%d cards)" % (title, len(deck))]
	for name, element, power in deck:
		lines.append("    %-10s %-8s power %s" % (name, element, power))
	types = sorted(element_types(deck))
	lines.append("    elements: " + ", ".join(types))
	if len(types) > 5:
		lines.append("    penalty: 25%% reduction for %d element types" % len(types))
	lines.append("    rating: %d" % synergize(deck, rules))
	return "\n".join(lines)


def main():
	rules = [("fire", "water"), ("earth", "air"), ("light", "shadow")]
	decks = [
		("Starter", [("goblin", "fire", 2), ("sprite", "water", 3)]),
		("Twins", [("golem", "earth", 6), ("golem", "earth", 6)]),
		("Rainbow", [
			("ember", "fire", 4), ("tide", "water", 5), ("boulder", "earth", 7),
			("gale", "air", 3), ("beacon", "light", 6), ("umbra", "shadow", 8),
		]),
	]
	for title, deck in decks:
		print(format_report(title, deck, rules))
		print()


if __name__ == "__main__":
	main()

