def schwarzschild_radius(mass):
    """Return the Schwarzschild radius used by the mission computer."""
    return mass * 2.95


def validate_inputs(masses, distances):
    """Check the survey data before any radius is computed."""
    if len(masses) != len(distances):
        raise ValueError("each black hole needs exactly one group of ships")
    for index, mass in enumerate(masses):
        if not isinstance(mass, (int, float)) or isinstance(mass, bool):
            raise TypeError("mass at position %d is not numeric" % index)
        if mass <= 0:
            raise ValueError("mass at position %d must be positive" % index)
    for group in distances:
        for entry in group:
            if len(entry) != 2:
                raise ValueError("ship records must hold a name and a distance")
            name, distance = entry
            if not isinstance(name, str) or not name:
                raise ValueError("ship names must be non-empty strings")
            if not isinstance(distance, (int, float)) or isinstance(distance, bool):
                raise TypeError("distance for %r is not numeric" % name)


def classify_ships(radius, ships):
    """Split one black hole's ships into the lost ones and the critical ones."""
    lost = 0
    critical = []
    for name, distance in ships:
        if distance <= radius:
            lost += 1
        elif distance <= 1.5 * radius:
            critical.append(name)
    return lost, critical


def calculate(masses, distances):
    validate_inputs(masses, distances)
    warnings = []
    for mass, ships in zip(masses, distances):
        radius = schwarzschild_radius(mass)
        lost, critical = classify_ships(radius, ships)
        if mass > 1000 and lost > 2:
            return "Region quarantined: gravitational collapse imminent"
        warnings.extend(critical)
    return sorted(warnings)


def format_report(result):
    """Turn the outcome of calculate into lines for the mission log."""
    if isinstance(result, str):
        return [result]
    if not result:
        return ["All observers clear of the critical band."]
    lines = ["Emergency fuel burned by %d ship(s):" % len(result)]
    for position, name in enumerate(result, start=1):
        lines.append("  %d. %s" % (position, name))
    return lines


def main():
    twin_masses = [10.0, 4.5]
    twin_ships = [
        [["Lyra", 20.0], ["Orion", 40.0], ["Vega", 29.5]],
        [["Pavo", 13.0], ["Draco", 100.0]],
    ]
    giant_masses = [1500.0]
    giant_ships = [
        [
            ["Hydra", 100.0],
            ["Cetus", 200.0],
            ["Norma", 4000.0],
            ["Aquila", 5000.0],
        ],
    ]
    surveys = [(twin_masses, twin_ships), (giant_masses, giant_ships)]
    for number, (masses, distances) in enumerate(surveys, start=1):
        print("Survey %d" % number)
        for line in format_report(calculate(masses, distances)):
            print(line)


if __name__ == "__main__":
    main()

