def validate_streets(streets, snow):
    if snow < 0:
        raise ValueError("snow depth cannot be negative")
    checked = []
    for entry in streets:
        if len(entry) != 3:
            raise ValueError("each street needs a name, length and priority")
        name, length, priority = entry
        if length < 0:
            raise ValueError("street %s has a negative length" % name)
        if priority not in (1, 2, 3):
            raise ValueError("street %s has an unknown priority" % name)
        checked.append((name, float(length), int(priority)))
    return checked


def group_by_priority(streets):
    groups = {1: [], 2: [], 3: []}
    for name, length, priority in streets:
        groups[priority].append((name, length))
    return groups


def base_time(length, snow):
    return length * snow / 5.0


def priority_one_times(group, snow):
    times = {}
    for name, length in group:
        minutes = base_time(length, snow)
        if snow > 10:
            minutes += 10
        times[name] = minutes
    return times


def priority_two_times(group, snow, fatigue):
    times = {}
    for name, length in group:
        minutes = base_time(length, snow)
        if fatigue:
            minutes *= 1.5
        times[name] = minutes
    return times


def priority_three_times(group, snow):
    if snow < 2:
        return {}
    return {name: base_time(length, snow) for name, length in group}


def clearing_schedule(streets, snow):
    groups = group_by_priority(validate_streets(streets, snow))
    first = priority_one_times(groups[1], snow)
    fatigue = sum(first.values()) > 120
    second = priority_two_times(groups[2], snow, fatigue)
    third = priority_three_times(groups[3], snow)
    return first, second, third


def plow(streets, snow):
    total = 0.0
    for times in clearing_schedule(streets, snow):
        total += sum(times.values())
    return round(total)


def report(streets, snow):
    lines = ["Storm depth: %g inches" % snow]
    for level, times in enumerate(clearing_schedule(streets, snow), start=1):
        if not times:
            lines.append("  priority %d: nothing to clear" % level)
            continue
        for name in sorted(times):
            lines.append("  priority %d: %-12s %6.1f min" % (level, name, times[name]))
    lines.append("Total: %d minutes" % plow(streets, snow))
    return "\n".join(lines)


def main():
    neighborhood = [
        ("Main St", 12.0, 1),
        ("Hospital Rd", 8.5, 1),
        ("Elm Ave", 6.0, 2),
        ("Oak Ln", 4.25, 2),
        ("Cul de Sac", 1.5, 3),
    ]
    for depth in (1.5, 6.0, 14.0):
        print(report(neighborhood, depth))
        print()


if __name__ == "__main__":
    main()

