from fractions import Fraction
from itertools import permutations
import sys


def _as_fraction(target):
    """Convert a target multiplier to an exact rational number."""
    if isinstance(target, float):
        return Fraction(str(target))
    return Fraction(target)


def _validate(gears, target):
    """Reject gear sets and targets that cannot describe a real gear train."""
    if len(gears) < 3:
        raise ValueError("at least three cogwheels are needed")
    for teeth in gears:
        if teeth <= 0:
            raise ValueError(f"a cogwheel cannot have {teeth} teeth")
    if target <= 0:
        raise ValueError("the target multiplier must be positive")


def friction_score(driver, idler, driven):
    """Total teeth in the train, plus a penalty for an odd driven gear."""
    score = driver + idler + driven
    if driven % 2:
        score += 5
    return score


def ratio(gears, target):
    """Return the lowest friction (driver, idler, driven) train hitting target."""
    _validate(gears, target)
    wanted = _as_fraction(target)
    best_train = ()
    best_score = None
    for driver, idler, driven in permutations(gears, 3):
        if 2 * idler < driver:
            continue
        if Fraction(driven, driver) != wanted:
            continue
        score = friction_score(driver, idler, driven)
        if best_score is None or score < best_score:
            best_train = (driver, idler, driven)
            best_score = score
    return best_train


def parse_gears(text):
    """Read a comma separated list of teeth counts."""
    counts = []
    for field in text.split(","):
        field = field.strip()
        if field:
            counts.append(int(field))
    return counts


def describe(train, target):
    """Render the chosen train as a one line report."""
    if not train:
        return f"no gear train achieves x{target}"
    driver, idler, driven = train
    score = friction_score(driver, idler, driven)
    path = f"driver {driver}t -> idler {idler}t -> driven {driven}t"
    return f"{path} = x{target}, friction {score}"


def main(argv):
    if len(argv) != 3:
        print(f"usage: {argv[0]} TEETH,TEETH,... TARGET", file=sys.stderr)
        return 2
    try:
        gears = parse_gears(argv[1])
        target = Fraction(argv[2])
    except (ValueError, ZeroDivisionError) as exc:
        print(f"bad input: {exc}", file=sys.stderr)
        return 2
    try:
        train = ratio(gears, target)
    except ValueError as exc:
        print(f"invalid gear set: {exc}", file=sys.stderr)
        return 2
    print(describe(train, target))
    return 0 if train else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

