def normalize(name):
    return " ".join(name.lower().split())


def validate(cores, wood):
    if not isinstance(cores, list):
        raise TypeError("cores must be a list of material names")
    if not isinstance(wood, str):
        raise TypeError("wood must be a single material name")
    for core in cores:
        if not isinstance(core, str):
            raise TypeError("every core must be a string")
        if not core.strip():
            raise ValueError("core names must not be blank")
    if not wood.strip():
        raise ValueError("wood name must not be blank")


def core_power(core, wood):
    power = 100
    name = normalize(core)
    body = normalize(wood)
    if body == "mahogany":
        if "dragon" in name:
            power += 50
        if "unicorn" in name:
            power -= 20
    elif body == "willow":
        if "feather" in name:
            power *= 2
    if len(core) > 10:
        power -= 10
    return power


def combined_power(cores, wood):
    total = 0.0
    seen = set()
    for core in cores:
        power = core_power(core, wood)
        key = normalize(core)
        if key in seen:
            total += power / 2
        else:
            total += power
            seen.add(key)
    return total


def craft(cores, wood):
    validate(cores, wood)
    total = combined_power(cores, wood)
    if total > 500:
        return 0
    return total


def describe(cores, wood):
    validate(cores, wood)
    lines = ["%s wand with %d core(s):" % (wood, len(cores))]
    seen = set()
    for core in cores:
        power = core_power(core, wood)
        key = normalize(core)
        if key in seen:
            lines.append("  %s: %g (halved duplicate)" % (core, power / 2))
        else:
            lines.append("  %s: %g" % (core, power))
            seen.add(key)
    total = combined_power(cores, wood)
    if total > 500:
        lines.append("  raw power %g exceeds 500 -> the wand shatters (0)" % total)
    else:
        lines.append("  final power: %g" % total)
    return "\n".join(lines)


def main():
    wands = [
        (["dragon heartstring"], "mahogany"),
        (["unicorn hair", "unicorn hair"], "mahogany"),
        (["phoenix feather", "thunderbird feather"], "willow"),
        (["dragon scale", "phoenix feather", "kelpie mane", "griffin claw"], "mahogany"),
        ([], "holly"),
    ]
    for cores, wood in wands:
        print(describe(cores, wood))
        print("craft(...) =", craft(cores, wood))
        print()


if __name__ == "__main__":
    main()

