def validate(minerals, temperature):
    """Reject bath descriptions that cannot be scored."""
    if not isinstance(temperature, (int, float)):
        raise TypeError("temperature must be numeric")
    checked = []
    for entry in minerals:
        if len(entry) != 3:
            raise ValueError("each mineral needs name, concentration, threshold")
        name, concentration, threshold = entry
        if not str(name).strip():
            raise ValueError("mineral name must not be blank")
        if concentration < 0 or threshold < 0:
            raise ValueError("concentrations and thresholds must be non-negative")
        checked.append((str(name).strip().lower(), float(concentration), float(threshold)))
    return checked


def precipitate(minerals):
    """Drop every concentration back to its threshold, charging cloudiness."""
    settled = []
