def build_thread_index(threads):
    """Map lowercased color names to (color, thickness, elasticity) tuples."""
    index = {}
    for entry in threads:
        if len(entry) != 3:
            raise ValueError("each thread needs a color, thickness and elasticity")
        color, thickness, elasticity = entry
        if thickness <= 0:
            raise ValueError("thread thickness must be positive: %s" % color)
        key = color.strip().lower()
        if key not in index:
            index[key] = (color, thickness, elasticity)
    return index


def resolve_thread(index, threads, color):
    """Return (thread, substituted) for the requested color."""
    key = color.strip().lower()
    if key in index:
        return index[key], False
    if not threads:
        raise ValueError("no threads available to substitute for %r" % color)
    return index[threads[0][0].strip().lower()], True


def row_length(thread, substituted):
    """Length in centimetres needed for a single row woven with thread."""
    color, _thickness, elasticity = thread
    length = 100.0
    if elasticity > 10:
        length -= 5.0
    if color.strip().lower() in ("gold", "silver"):
        length += 20.0
    if substituted:
        length += 30.0
    return length


def weave(threads, pattern):
    """Total yarn in metres required to weave the pattern from the threads."""
    if not pattern:
        return 0.0
    index = build_thread_index(threads)
    total_cm = 0.0
    for color in pattern:
        thread, substituted = resolve_thread(index, threads, color)
        total_cm += row_length(thread, substituted)
    return total_cm / 100.0


def weaving_report(threads, pattern):
    """Build a per-colour summary of rows and metres consumed."""
    index = build_thread_index(threads)
    usage = {}
    for color in pattern:
        thread, substituted = resolve_thread(index, threads, color)
        name = thread[0]
        rows, metres = usage.get(name, (0, 0.0))
        usage[name] = (rows + 1, metres + row_length(thread, substituted) / 100.0)
    lines = []
    for name in sorted(usage):
        rows, metres = usage[name]
        lines.append("%-8s %2d rows %6.2f m" % (name, rows, metres))
    return "\n".join(lines)


def main():
    threads = [
        ("Linen", 0.8, 4),
        ("Gold", 0.5, 12),
        ("Wool", 1.2, 18),
    ]
    pattern = ["Linen", "Gold", "Wool", "Crimson", "Gold", "linen"]
    print(weaving_report(threads, pattern))
    print("total: %.2f m" % weave(threads, pattern))


if __name__ == "__main__":
    main()

