def validate_branches(branches):
    """Return the branch list as clean tuples, raising on malformed input."""
    cleaned = []
    for entry in branches:
        if len(entry) != 3:
            raise ValueError("each branch needs an id, a length and a leaf count")
        bid, length, leaves = entry
        if length < 0:
            raise ValueError("branch %s has a negative length" % (bid,))
        if leaves < 0:
            raise ValueError("branch %s has a negative leaf count" % (bid,))
        cleaned.append((bid, length, leaves))
    return cleaned


def prune(branches, season):
    """Shape the tree for the given season and report the resulting branches."""
    season = season.strip().lower()
    if season not in ("winter", "spring", "summer"):
        raise ValueError("unknown season: %s" % season)
    shaped = []
    removed_total = 0
    for bid, length, leaves in validate_branches(branches):
        new_length = length
        new_leaves = leaves
        if season == "winter":
            if length > 15:
                new_length = length - length / 3
                new_leaves = 0
        elif season == "spring":
            if leaves < 5:
                new_length = 0
                new_leaves = 0
        else:
            if leaves > 20:
                new_leaves = leaves // 2
        removed_total += length - new_length
        shaped.append((bid, new_length, new_leaves))
    if removed_total > 50:
        shaped = [(bid, length, 0) for bid, length, _ in shaped]
    return shaped


def format_report(original, shaped):
    """Build printable lines comparing the tree before and after pruning."""
    before = {bid: (length, leaves) for bid, length, leaves in original}
    lines = []
    for bid, length, leaves in shaped:
        old_length, old_leaves = before[bid]
        change = old_length - length
        note = "unchanged"
        if change > 0:
            note = "cut %.1f cm" % change
        if leaves < old_leaves:
            note += ", lost %d leaves" % (old_leaves - leaves)
        lines.append("#%s: %.1f cm, %d leaves (%s)" % (bid, length, leaves, note))
    return lines


def main():
    tree = [(1, 24, 30), (2, 18, 4), (3, 12, 26), (4, 30, 2), (5, 9, 40)]
    for season in ("winter", "spring", "summer"):
        shaped = prune(tree, season)
        print(season.capitalize() + " pruning:")
        for line in format_report(tree, shaped):
            print("    " + line)
        total_leaves = sum(leaves for _, _, leaves in shaped)
        if total_leaves == 0:
            print("    the tree is bare")
        print()


if __name__ == "__main__":
    main()

