import math


def requires_net(name):
    return "juggl" in name.lower()


def validate(acts, breaks):
    if breaks < 0:
        raise ValueError("intermission length cannot be negative")
    entries = []
    for entry in acts:
        if len(entry) != 3:
            raise ValueError("each act needs a name, a duration and a setup time")
        name, duration, setup = entry
        if not str(name).strip():
            raise ValueError("every performer needs a name")
        if duration < 0 or setup < 0:
            raise ValueError("times cannot be negative for %s" % name)
        entries.append((str(name).strip(), float(duration), float(setup)))
    return entries


def setup_for(name, setup, zero_streak):
    prep = setup
    if requires_net(name):
        prep += 5
    if zero_streak >= 3:
        prep = max(0.0, prep - 3)
    return prep


def run_order(acts, breaks):
    entries = validate(acts, breaks)
    running = 0.0
    zero_streak = 0
    last = len(entries) - 1
    for index, (name, duration, setup) in enumerate(entries):
        played = duration
        if running > 120:
            played = duration * 0.9
        prep = setup_for(name, setup, zero_streak)
        pause = 0.0
        if played > 20:
            pause += breaks / 2
        if index < last:
            pause += breaks
        running += prep + played + pause
        if setup == 0:
            zero_streak += 1
        else:
            zero_streak = 0
        yield {"name": name, "prep": prep, "played": played,
               "pause": pause, "running": running}


def schedule(acts, breaks):
    running = 0.0
    for slot in run_order(acts, breaks):
        running = slot["running"]
    return math.ceil(running)


def report(acts, breaks):
    lines = ["%-14s %6s %6s %6s %8s" % ("PERFORMER", "SETUP", "ACT", "PAUSE", "RUNNING")]
    for slot in run_order(acts, breaks):
        lines.append("%-14s %6.1f %6.1f %6.1f %8.1f" % (
            slot["name"], slot["prep"], slot["played"], slot["pause"], slot["running"]))
    lines.append("Total running time: %d minutes" % schedule(acts, breaks))
    return "\n".join(lines)


def main():
    bill = [
        ("Marvo the Magnificent", 12, 0),
        ("Singing Sisters", 8, 0),
        ("Tap Dancing Terrier", 6, 0),
        ("Bella the Juggler", 22, 4),
        ("Accordion Al", 18, 5),
        ("Grand Finale Chorus", 25, 10),
    ]
    print(report(bill, 10))


if __name__ == "__main__":
    main()

