	return (x, y)


def bounce_back(pos, blocked, area):
	max_x, max_y = area
	x = pos[0] - (blocked[0] - pos[0])
	y = pos[1] - (blocked[1] - pos[1])
	x = min(max(x, 0), max_x)
	y = min(max(y, 0), max_y)
	return (x, y)


def dig(pos, remaining):
	gained = 0
	for scent in [s for s in remaining if (s[0], s[1]) == pos]:
		gained += scent[2]
		remaining.remove(scent)
	return gained


def forage(scents, area):
	remaining = validate_scents(scents, area)
	pos = (0, 0)
	total = dig(pos, remaining)
	for _step in range(MAX_STEPS):
		if not remaining:
			break
		target = pick_target(scents_in_range(pos, remaining))
		if target is None:
			moved = (pos[0] + 1, pos[1] + 1)
		else:
			moved = step_toward(pos, (target[0], target[1]))
		if not in_bounds(moved, area):
			moved = bounce_back(pos, moved, area)
		pos = moved
		total += dig(pos, remaining)
	return total


def format_report(name, total, area):
	return "%-12s grid %dx%d -> yield %3d" % (name, area[0], area[1], total)


def main():
	woodlands = [
		("Oakhollow", [(2, 2, 5), (3, 3, 9), (6, 6, 4)], (10, 10)),
		("Beechmere", [(1, 1, 7), (2, 2, 7), (4, 4, 12)], (8, 8)),
		("Elmside", [(5, 5, 3), (9, 9, 20), (30, 4, 50)], (9, 9)),
	]
	for name, scents, area in woodlands:
		print(format_report(name, forage(scents, area), area))


if __name__ == "__main__":
	main()

