def validate(bands, projectiles):
    """Check that the equipment tables are usable before calibrating."""
    if not bands:
        raise ValueError("at least one band is required")
    if not projectiles:
        raise ValueError("at least one projectile is required")
    for material, elasticity, draw_weight in bands:
        if elasticity <= 0:
            raise ValueError("band %s has a non-positive elasticity" % material)
        if draw_weight <= 0:
            raise ValueError("band %s has a non-positive draw weight" % material)
    for ammo, weight, drag in projectiles:
        if weight <= 0:
            raise ValueError("projectile %s has a non-positive weight" % ammo)
        if drag <= 0:
            raise ValueError("projectile %s has a non-positive drag" % ammo)


def effective_drag(ammo, drag):
    """Lead shot shrugs off ten percent of its drag penalty."""
    if ammo.lower() == "lead":
        return drag * 0.9
    return drag


def shot_distance(elasticity, draw_weight, ammo, weight, drag):
    """Distance for one pairing, or zero if the projectile snaps the band."""
    if weight > draw_weight / 2:
        return 0.0
    velocity = draw_weight * elasticity / weight
    return velocity ** 2 / effective_drag(ammo, drag)


def calibrate(bands, projectiles):
    """Return (band material, ammo type) of the best performing pairing."""
    validate(bands, projectiles)
    best_material = None
    best_ammo = None
    best_distance = -1.0
    for material, elasticity, draw_weight in bands:
        for ammo, weight, drag in projectiles:
            reach = shot_distance(elasticity, draw_weight, ammo, weight, drag)
            if reach > best_distance:
                best_distance = reach
                best_material = material
                best_ammo = ammo
            if reach > 1000:
                elasticity -= 0.1
                if elasticity <= 0:
                    break
    return best_material, best_ammo


def report(bands, projectiles):
    """Human readable log of every pairing, mirroring calibrate's ordering."""
    lines = []
    for material, elasticity, draw_weight in bands:
        for ammo, weight, drag in projectiles:
            reach = shot_distance(elasticity, draw_weight, ammo, weight, drag)
            note = "snapped" if reach == 0.0 else "%.1f m" % reach
            lines.append("%-8s + %-6s -> %s" % (material, ammo, note))
            if reach > 1000:
                elasticity -= 0.1
                lines.append("    microtears: %s now %.2f" % (material, elasticity))
                if elasticity <= 0:
                    lines.append("    %s is spent" % material)
                    break
    return "\n".join(lines)


def main():
    bands = [
        ("latex", 2.5, 40.0),
        ("rubber", 1.8, 60.0),
        ("silicone", 3.0, 25.0),
    ]
    projectiles = [
        ("lead", 8.0, 1.4),
        ("steel", 12.0, 1.1),
        ("clay", 30.0, 2.0),
    ]
    print(report(bands, projectiles))
    band, ammo = calibrate(bands, projectiles)
    print("optimal pairing: %s band with %s shot" % (band, ammo))


if __name__ == "__main__":
    main()

