def validate_angles(angles):
    """Return the readings as a list of floats, rejecting non-numeric input."""
    if not isinstance(angles, (list, tuple)):
        raise TypeError("angles must be given as a list or tuple")
    cleaned = []
    for angle in angles:
        if isinstance(angle, bool) or not isinstance(angle, (int, float)):
            raise TypeError("measured angle {0!r} is not a number".format(angle))
        cleaned.append(float(angle))
    return cleaned


def calibration(readings):
    """Find the median of the first three positive angles and where they end."""
    positives = []
    end = 0
    for index, angle in enumerate(readings):
        if angle > 0:
            positives.append(angle)
            if len(positives) == 3:
                end = index + 1
                break
    if len(positives) < 3:
        raise ValueError("three positive angles are needed to calibrate the astrolabe")
    return sorted(positives)[1], end


def navigate(angles):
    """Adjust the readings that follow calibration, dropping and capping as needed."""
    readings = validate_angles(angles)
    median, start = calibration(readings)
    adjusted = []
    for angle in readings[start:]:
        value = angle - median
        if value < 0:
            continue
        if value > 90.0:
            value = 90.0
        adjusted.append(value)
    return adjusted


def format_angle(value):
    """Render a degree value without a pointless trailing zero."""
    if value == int(value):
        return str(int(value))
    return "{0:.2f}".format(value)


def format_report(label, readings):
    """Build a human readable summary of one night's measurements."""
    median, start = calibration(validate_angles(readings))
    results = navigate(readings)
    lines = ["{0}:".format(label)]
    lines.append("  calibration median: {0} deg".format(format_angle(median)))
    lines.append("  readings after calibration: {0}".format(len(readings) - start))
    if results:
        for value in results:
            lines.append("    {0} deg".format(format_angle(value)))
    else:
        lines.append("    no usable readings")
    return "\n".join(lines)


def main():
    logbook = [
        ("Example sight", [10, 20, 30, 40]),
        ("Night watch", [0, -3, 12, 18, 15, 9, 14.5, 130, 20]),
        ("Dawn sight", [25, 25, 25, 25, 24, 90]),
        ("Storm sight", [-5, 0, 3, 7]),
    ]
    for label, readings in logbook:
        try:
            print(format_report(label, readings))
        except ValueError as error:
            print("{0}: calibration failed ({1})".format(label, error))


if __name__ == "__main__":
    main()

