STANDARD = 1
CUE = 9
MIN_GAP = 10
MAX_GAP = 20


def validate_frames(frames):
    """Reject anything that is not a flat list of standard frames and cue marks."""
    if not isinstance(frames, list):
        raise TypeError("frames must be a list of integers")
    for position, frame in enumerate(frames):
        if isinstance(frame, bool) or not isinstance(frame, int):
            raise TypeError("frame %d is not an integer: %r" % (position, frame))
        if frame not in (STANDARD, CUE):
            raise ValueError("frame %d has unknown type %d" % (position, frame))
    return frames


def cue_positions(frames):
    """Indices of every cue mark, in projection order."""
    positions = []
    for index, frame in enumerate(frames):
        if frame == CUE:
            positions.append(index)
    return positions


def project(frames):
    """Number of frames projected before the changeover completes."""
    validate_frames(frames)
    cues = cue_positions(frames)
    for first, second in zip(cues, cues[1:]):
        standard_between = second - first - 1
        if MIN_GAP <= standard_between <= MAX_GAP:
            return second + 1
    return len(frames)


def parse_reel(text):
    """Expand a compact reel description such as '1 9 1x12 9' into frame types."""
    frames = []
    for token in text.split():
        if "x" in token:
            value, count = token.split("x")
            frames.extend([int(value)] * int(count))
        else:
            frames.append(int(token))
    return frames


def describe_run(frames):
    """One-line summary of what the projectionist would observe."""
    projected = project(frames)
    ignored = len(frames) - projected
    if ignored > 0:
        return "changeover complete after %d frames, %d frames ignored" % (projected, ignored)
    return "no valid changeover, all %d frames projected" % projected


def main():
    reels = [
        ("textbook cue", "1 9 1x12 9"),
        ("cues too close", "1x5 9 1x4 9 1x30"),
        ("cues too far apart", "9 1x25 9 1x10"),
        ("second pair valid", "9 1x3 9 1x15 9 1x40"),
        ("no cue marks", "1x24"),
    ]
    for name, description in reels:
        frames = parse_reel(description)
        print("%-20s -> %3d  (%s)" % (name, project(frames), describe_run(frames)))


if __name__ == "__main__":
    main()

