def is_symmetric_row(row):
    """Return True when the row reads the same left to right and right to left."""
    left = 0
    right = len(row) - 1
    while left < right:
        if row[left] != row[right]:
            return False
        left += 1
        right -= 1
    return True


def count_symmetric_rows(blocks):
    """Count how many rows of the quilt are perfectly symmetric."""
    total = 0
    for row in blocks:
        if is_symmetric_row(row):
            total += 1
    return total


def validate_blocks(blocks):
    """Ensure the quilt is a non-empty list of equally long integer rows."""
    if not isinstance(blocks, list) or len(blocks) == 0:
        return False
    width = None
    for row in blocks:
        if not isinstance(row, list) or len(row) == 0:
            return False
        if width is None:
            width = len(row)
        elif len(row) != width:
            return False
        for block in row:
            if not isinstance(block, int) or isinstance(block, bool):
                return False
    return True


def patchwork(blocks):
    """Return 1 when the quilt design is structurally valid, else 0."""
    if not validate_blocks(blocks):
        return 0
    if blocks[0] != blocks[-1]:
        return 0
    if 2 * count_symmetric_rows(blocks) <= len(blocks):
        return 0
    return 1


def format_report(name, blocks):
    """Build a one-line summary describing a named quilt design."""
    verdict = patchwork(blocks)
    if validate_blocks(blocks):
        symmetric = count_symmetric_rows(blocks)
        detail = "{0}/{1} symmetric rows".format(symmetric, len(blocks))
    else:
        detail = "malformed layout"
    return "{0}: {1} -> {2}".format(name, detail, verdict)


def main():
    designs = [
        ("triple stripe", [[1, 2, 1], [1, 2, 1], [1, 2, 1]]),
        ("mismatched ends", [[3, 3], [4, 4], [3, 4]]),
        ("too few mirrors", [[5, 6, 5], [7, 8, 9], [1, 2, 3], [5, 6, 5]]),
        ("ragged rows", [[1, 1], [2, 2, 2]]),
        ("single block", [[9]]),
    ]
    for name, blocks in designs:
        print(format_report(name, blocks))


if __name__ == "__main__":
    main()

