def validate_beats(beats):
    if not isinstance(beats, (list, tuple)):
        raise TypeError("beats must be a list or tuple of intervals")
    if len(beats) == 0:
        raise ValueError("beats must contain at least the target interval")
    checked = []
    for index, value in enumerate(beats):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("beat %d is not a number: %r" % (index, value))
        if value <= 0:
            raise ValueError("beat %d must be positive, got %r" % (index, value))
        checked.append(value)
    return checked


def simulate(beats):
    values = validate_beats(beats)
    target = values[0]
    limit = target + 20
    streak = 0
    winds = []
    effective = []
    reset_pending = False
    for index, raw in enumerate(values):
        if reset_pending:
            interval = target
            reset_pending = False
        else:
            interval = raw
        effective.append(interval)
        if interval > limit:
            streak += 1
            if streak == 3:
                winds.append(index)
                streak = 0
                reset_pending = True
        else:
            streak = 0
    return target, effective, winds


def tempo(beats):
    return len(simulate(beats)[2])


def format_report(beats):
    target, effective, winds = simulate(beats)
    limit = target + 20
    reset_beats = set()
    for index in winds:
        if index + 1 < len(effective):
            reset_beats.add(index + 1)
    lines = ["target tempo: %g ms (drift above %g ms)" % (target, limit)]
    for index, interval in enumerate(effective):
        if index in reset_beats:
            state = "reset by winding"
        elif interval > limit:
            state = "drifting"
        else:
            state = "steady"
        lines.append("  beat %2d: %7.1f ms  %s" % (index, interval, state))
        if index in winds:
            lines.append("  -> key wound after beat %d" % index)
    lines.append("total winds: %d" % len(winds))
    return "\n".join(lines)


def main():
    sessions = {
        "unwinding waltz": [500, 530, 530, 530, 530],
        "long march": [400, 425, 430, 431, 428, 429, 435, 440, 441, 442],
        "steady andante": [600, 605, 610, 615, 612],
    }
    for name, beats in sessions.items():
        print(name)
        print(format_report(beats))
        print("tempo(%s) = %d" % (name, tempo(beats)))
        print()


if __name__ == "__main__":
    main()

