TUBE_COUNT = 4
TOGGLE_PULSE = 5


def validate_pulses(pulses):
    """Return a clean list of pulses, rejecting anything the sign cannot drive."""
    if isinstance(pulses, (str, bytes)):
        raise TypeError("pulses must be a sequence of integers, not text")
    cleaned = []
    for position, pulse in enumerate(pulses):
        if isinstance(pulse, bool) or not isinstance(pulse, int):
            raise TypeError("pulse %d is not an integer: %r" % (position, pulse))
        if pulse > TOGGLE_PULSE or pulse < -TUBE_COUNT:
            raise ValueError("pulse %d is out of range: %d" % (position, pulse))
        cleaned.append(pulse)
    return cleaned


def apply_pulse(state, pulse):
    """Return the tube states that result from feeding one pulse to the sign."""
    if pulse == 0:
        return [0] * TUBE_COUNT
    if pulse == TOGGLE_PULSE:
        return [1 - tube for tube in state]
    updated = list(state)
    if pulse > 0:
        updated[pulse - 1] = 1
    else:
        updated[-pulse - 1] = 0
    return updated


def illuminate(pulses):
    """Drive the four neon tubes with the given pulses and report the final state."""
    state = [0] * TUBE_COUNT
    for pulse in validate_pulses(pulses):
        state = apply_pulse(state, pulse)
    return state


def parse_pulse_line(text):
    """Turn a comma or space separated line of pulses into a list of integers."""
    pulses = []
    for token in text.replace(",", " ").split():
        try:
            pulses.append(int(token))
        except ValueError:
            raise ValueError("cannot read %r as a pulse" % token)
    return pulses


def format_state(state):
    """Render a tube state list as a readable line such as '1:off 2:ON ...'."""
    parts = []
    for number, tube in enumerate(state, start=1):
        if tube:
            parts.append("%d:ON" % number)
        else:
            parts.append("%d:off" % number)
    return " ".join(parts)


def report(lines):
    """Process several pulse programs and yield one formatted report line each."""
    for line in lines:
        try:
            state = illuminate(parse_pulse_line(line))
        except (TypeError, ValueError) as problem:
            yield "%-20s -> error: %s" % (line, problem)
        else:
            yield "%-20s -> %s  %s" % (line, state, format_state(state))


def main():
