import sys

TARGET_SCORE = 500
DIM_THRESHOLD = 10


def parse_readings(text):
    """Turn a text line of comma or space separated numbers into integers."""
    readings = []
    for token in text.replace(",", " ").split():
        try:
            readings.append(int(token))
        except ValueError:
            raise ValueError("not a light level: {!r}".format(token))
    return readings


def expose(conditions):
    """Minutes the shutter stays open, or -1 if the film never fully exposes."""
    total = 0
    for minute, level in enumerate(conditions, start=1):
        if not isinstance(level, int):
            raise TypeError("light levels must be integers, got {!r}".format(level))
        if level >= DIM_THRESHOLD:
            total += level
        if total >= TARGET_SCORE:
            return minute
    return -1


def accumulation_trace(conditions):
    """Per-minute (minute, level, running total) triples for the whole session."""
    trace = []
    total = 0
    for minute, level in enumerate(conditions, start=1):
        if level >= DIM_THRESHOLD:
            total += level
        trace.append((minute, level, total))
        if total >= TARGET_SCORE:
            break
    return trace


def exposure_report(conditions):
    lines = []
    for minute, level, total in accumulation_trace(conditions):
        if level < DIM_THRESHOLD:
            note = "too dim"
        else:
            note = "exposing"
        lines.append("minute {:>3}: level {:>4}  total {:>4}  {}".format(minute, level, total, note))
    minutes = expose(conditions)
    if minutes < 0:
        lines.append("film never reached {}; shutter stayed open".format(TARGET_SCORE))
    else:
        lines.append("shutter closed after {} minute(s)".format(minutes))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        sources = [" ".join(argv[1:])]
    else:
        sources = [line for line in sys.stdin if line.strip()]
    for source in sources:
        try:
            readings = parse_readings(source)
        except ValueError as error:
            print("skipping input: {}".format(error))
            continue
        if not readings:
            print("skipping input: no light levels given")
            continue
        print(exposure_report(readings))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

