THRESHOLD = 5


def validate(speeds):
    """Convert raw measurements to floats, rejecting anything unusable."""
    if not isinstance(speeds, (list, tuple)):
        raise TypeError("speeds must be a list or tuple of numbers")
    cleaned = []
    for index, value in enumerate(speeds):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("measurement %d is not a number: %r" % (index, value))
        if value < 0:
            raise ValueError("measurement %d is negative: %r" % (index, value))
        cleaned.append(float(value))
    return cleaned


def gust_spans(speeds):
    """Return (start, end, peak) triples describing each gust event."""
    readings = validate(speeds)
    spans = []
    start = None
    for index, speed in enumerate(readings):
        if speed > THRESHOLD:
            if start is None:
                start = index
        elif start is not None:
            spans.append((start, index - 1, max(readings[start:index])))
            start = None
    if start is not None:
        spans.append((start, len(readings) - 1, max(readings[start:])))
    return spans


def wind(speeds):
    """Return the peak speed of every continuous run of speeds above five."""
    return [peak for _, _, peak in gust_spans(speeds)]


def report(speeds):
    """Build a human readable summary of the gust events in a recording."""
    spans = gust_spans(speeds)
    if not spans:
        return "no gusts registered"
    lines = ["%d gust event(s) registered" % len(spans)]
    for number, (start, end, peak) in enumerate(spans, start=1):
        samples = end - start + 1
        lines.append(
            "  gust %d: samples %d-%d (%d reading(s)), peak %.1f mph"
            % (number, start, end, samples, peak)
        )
    strongest = max(peak for _, _, peak in spans)
    lines.append("strongest gust: %.1f mph" % strongest)
    return "\n".join(lines)


def main():
    recordings = [
        [2, 10, 12, 2, 8],
        [1, 3, 5, 5, 4],
        [6, 7, 5, 9, 20, 3, 5.5, 6.25],
    ]
    for recording in recordings:
        print("readings:", recording)
        print("peaks:", wind(recording))
        print(report(recording))
        print()


if __name__ == "__main__":
