def throw(angles):
    for angle in angles:
        if angle < 0:
            return 3
    total = sum(angles)
    if total == 360:
        return 1
    if total > 400:
        return 2
    return 0


def parse_angles(text):
    values = []
    for token in text.replace(",", " ").split():
        try:
            values.append(int(token))
        except ValueError:
            raise ValueError("not an integer angle: {!r}".format(token))
    return values


def describe(code):
    labels = {
        1: "perfect return",
        2: "crashed into the ground",
        3: "wind interruption",
        0: "incomplete throw",
    }
    return labels[code]


def flight_log(angles):
    heading = 0
    lines = []
    for second, angle in enumerate(angles, start=1):
        heading += angle
        lines.append("t={}s turn {:+d} -> heading {}".format(second, angle, heading))
        if heading > 400:
            lines.append("t={}s boomerang is falling".format(second))
            break
    return lines


def summarize(text):
    angles = parse_angles(text)
    code = throw(angles)
    report = ["throw: {}".format(text.strip())]
    report.extend(flight_log(angles))
    report.append("result {}: {}".format(code, describe(code)))
    if code == 0:
        report.append("missing {} degrees for a full loop".format(360 - sum(angles)))
    return report


def main():
    throws = [
        "90 90 90 90",
        "120, 120, 100",
        "180 180 90",
        "45 -30 90",
        "10 20 30",
    ]
    for text in throws:
        for line in summarize(text):
            print("  " + line)
        print()
    tally = {}
    for text in throws:
        code = throw(parse_angles(text))
        tally[code] = tally.get(code, 0) + 1
    for code in sorted(tally):
        print("{} x {}".format(tally[code], describe(code)))


main()

