	code = throw(angles)
	report = ["throw: {}".format(text.strip())]
	report.extend(flight_log(angles))
	report.append("result {}: {}".format(code, describe(code)))
	if code == 0:
		report.append("missing {} degrees for a full loop".format(360 - sum(angles)))
	return report


