		"120, 120, 100",
		"180 180 90",
		"45 -30 90",
		"10 20 30",
	]
	for text in throws:
		for line in summarize(text):
			print("  " + line)
		print()
	tally = {}
	for text in throws:
		code = throw(parse_angles(text))
		tally[code] = tally.get(code, 0) + 1
	for code in sorted(tally):
		print("{} x {}".format(tally[code], describe(code)))


