def validate_notes(notes):
    """Return the plucked frequencies as a list of positive integers."""
    if not isinstance(notes, (list, tuple)):
        raise TypeError("notes must be a list of integers")
    cleaned = []
    for note in notes:
        if isinstance(note, bool) or not isinstance(note, int):
            raise TypeError("frequency {!r} is not an integer".format(note))
        if note <= 0:
            raise ValueError("frequency {} must be positive".format(note))
        cleaned.append(note)
    return cleaned


def resonances(frequency):
    """Frequencies one octave above and (when whole) one octave below."""
    partials = [frequency * 2]
    if frequency % 2 == 0:
        partials.append(frequency // 2)
    return partials


def pluck(notes):
    """All frequencies vibrating after the given strings are plucked."""
    plucked = validate_notes(notes)
    vibrating = set(plucked)
    for frequency in plucked:
        for partial in resonances(frequency):
            vibrating.add(partial)
    return sorted(vibrating)


def sources(notes):
    """Map each vibrating frequency to how it started vibrating."""
    plucked = validate_notes(notes)
    direct = set(plucked)
    origin = {}
    for frequency in pluck(plucked):
        if frequency in direct:
            origin[frequency] = "plucked"
        else:
            origin[frequency] = "resonance"
    return origin


def report(notes):
    """Build a human readable summary of one pluck of the harp."""
    origin = sources(notes)
    lines = ["plucked: " + ", ".join(str(n) for n in sorted(set(notes)))]
    for frequency in sorted(origin):
        label = origin[frequency]
        lines.append("  {:>6} Hz  {}".format(frequency, label))
    total = len(origin)
    lines.append("  {} string{} vibrating".format(total, "" if total == 1 else "s"))
    return "\n".join(lines)


def main():
    examples = [[400], [400, 800], [110, 220, 330], [7]]
    for notes in examples:
        print(report(notes))
        print()
    try:
        pluck([440, -1])
    except ValueError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

