import sys

MAX_INK = 100


def validate(strokes):
    """Return the stroke pressures as a list, rejecting malformed input."""
    if not isinstance(strokes, (list, tuple)):
        raise TypeError("strokes must be a list of integers")
    for pressure in strokes:
        if not isinstance(pressure, int) or isinstance(pressure, bool):
            raise TypeError("pressure values must be integers")
    return list(strokes)


def consume(ink, pressure):
    """Apply one stroke, returning the remaining ink and whether it ran dry."""
    if pressure < 0:
        return MAX_INK, False
    needed = 2 * pressure
    if needed <= ink:
        return ink - needed, False
    return 0, ink > 0


def letter(strokes):
    """Count the strokes that could not be completed with the ink available."""
    ink = MAX_INK
    dry_strokes = 0
    for pressure in validate(strokes):
        ink, was_dry = consume(ink, pressure)
        if was_dry:
            dry_strokes += 1
    return dry_strokes


def trace(strokes):
    """Record (index, pressure, ink left, dry flag) for every stroke."""
    rows = []
    ink = MAX_INK
    for index, pressure in enumerate(validate(strokes), start=1):
        ink, was_dry = consume(ink, pressure)
        rows.append((index, pressure, ink, was_dry))
    return rows


def parse_strokes(tokens):
    """Convert command line arguments into a list of pressure values."""
    values = []
    for token in tokens:
        digits = token[1:] if token.startswith("-") else token
        if not digits.isdigit():
            raise ValueError("not an integer pressure: %r" % (token,))
        values.append(int(token))
    return values


def format_report(strokes):
    lines = ["%6s %8s %4s  %s" % ("stroke", "pressure", "ink", "status")]
    for index, pressure, ink, was_dry in trace(strokes):
        if pressure < 0:
            status = "dipped"
        elif was_dry:
            status = "dry"
        else:
            status = "ok"
        lines.append("%6d %8d %4d  %s" % (index, pressure, ink, status))
    lines.append("dry strokes: %d" % letter(strokes))
    return "\n".join(lines)


def main(argv):
    if len(argv) > 1:
        strokes = parse_strokes(argv[1:])
    else:
        strokes = [60, 60, -1, 40, 30, 10, 25]
