VOWELS = "aeiou"


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in text, case-insensitive."""
    if not isinstance(text, str):
        raise TypeError("count_vowels() expects a string")
    total = 0
    for character in text.lower():
        if character in VOWELS:
            total += 1
    return total


def vowel_frequency(text):
    """Return a dict mapping each vowel to how often it occurs in text."""
    counts = {vowel: 0 for vowel in VOWELS}
    for character in text.lower():
        if character in counts:
            counts[character] += 1
    return counts


def most_common_vowel(text):
    """Return the most frequent vowel in text, or None when there is none."""
    counts = vowel_frequency(text)
    best = None
    for vowel in VOWELS:
        if best is None or counts[vowel] > counts[best]:
            best = vowel
    if counts[best] == 0:
        return None
    return best


def vowel_ratio(text):
    """Return the share of letters in text that are vowels."""
    letters = 0
    for character in text:
        if character.isalpha():
            letters += 1
    if letters == 0:
        return 0.0
    return count_vowels(text) / letters


def describe(text):
    """Build a human-readable summary line for one piece of text."""
    total = count_vowels(text)
    top = most_common_vowel(text)
    parts = ["{0!r}: {1} vowel(s)".format(text, total)]
    if top is None:
        parts.append("no vowels present")
    else:
        breakdown = vowel_frequency(text)
        listing = ", ".join(
            "{0}={1}".format(vowel, breakdown[vowel])
            for vowel in VOWELS
            if breakdown[vowel] > 0
        )
        parts.append("most common '{0}'".format(top))
        parts.append(listing)
        parts.append("ratio {0:.2f}".format(vowel_ratio(text)))
    return " | ".join(parts)


def main():
    samples = ["Hello World", "Python", "AEIOU sequence", "rhythm", ""]
    grand_total = 0
    for sample in samples:
        print(describe(sample))
        grand_total += count_vowels(sample)
    print("Total vowels across {0} samples: {1}".format(len(samples), grand_total))


if __name__ == "__main__":
    main()

