import sys


def normalize(text):
    """Return only the lowercase alphanumeric characters of text."""
    cleaned = []
    for char in text:
        if char.isalnum():
            cleaned.append(char.lower())
    return "".join(cleaned)


def is_palindrome(text):
    """Return True if text reads the same forwards and backwards."""
    if not isinstance(text, str):
        raise TypeError("is_palindrome expects a string")
    cleaned = normalize(text)
    left = 0
    right = len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1
    return True


def longest_palindromic_phrase(text):
    """Return the longest whitespace-delimited phrase of text that is a palindrome."""
    words = text.split()
    best = ""
    for start in range(len(words)):
        for end in range(start + 1, len(words) + 1):
            phrase = " ".join(words[start:end])
            if is_palindrome(phrase) and len(normalize(phrase)) > len(normalize(best)):
                best = phrase
    return best


def describe(text):
    """Build a one-line report about the palindrome status of text."""
    cleaned = normalize(text)
    if not cleaned:
        return "%r -> no alphanumeric content" % text
    verdict = "palindrome" if is_palindrome(text) else "not a palindrome"
    report = "%r -> %s (normalized: %r)" % (text, verdict, cleaned)
    if verdict == "not a palindrome":
        phrase = longest_palindromic_phrase(text)
        if phrase:
