import sys


def count_lines_in_file(filepath):
    """Return the number of lines in the file at filepath."""
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        return sum(1 for line in handle)


def count_nonblank_lines(filepath):
    """Return the number of lines containing at least one non-space character."""
    count = 0
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        for line in handle:
            if line.strip():
                count += 1
    return count


def longest_line(filepath):
    """Return the longest line (without its newline) found in the file."""
    best = ''
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        for line in handle:
            stripped = line.rstrip('\n')
            if len(stripped) > len(best):
                best = stripped
    return best


def summarize(filepath):
    """Build a dictionary describing the line structure of one file."""
    total = count_lines_in_file(filepath)
    filled = count_nonblank_lines(filepath)
    return {
        'path': filepath,
        'lines': total,
        'nonblank': filled,
        'blank': total - filled,
        'longest': longest_line(filepath),
    }


def format_report(summaries):
    """Turn a list of summaries into aligned report lines."""
    if not summaries:
        return 'no files could be read'
    width = max(len(item['path']) for item in summaries)
    rows = []
    for item in summaries:
        preview = item['longest']
        if len(preview) > 30:
            preview = preview[:27] + '...'
        rows.append('{0:<{1}}  {2:>5} lines  {3:>5} blank  | {4}'.format(
            item['path'], width, item['lines'], item['blank'], preview))
    return '\n'.join(rows)


def main(argv):
    paths = argv[1:]
    if not paths:
        print('usage: linecount FILE [FILE ...]')
        return 1
    summaries = []
    for path in paths:
        try:
            summaries.append(summarize(path))
        except OSError as exc:
            print('could not read {0}: {1}'.format(path, exc))
    print(format_report(summaries))
    if len(summaries) > 1:
        grand_total = sum(item['lines'] for item in summaries)
        print('total: {0} lines in {1} files'.format(grand_total, len(summaries)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

