def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index for a weight in kg and a height in metres."""
    if weight_kg <= 0:
        raise ValueError("weight must be a positive number of kilograms")
    if height_m <= 0:
        raise ValueError("height must be a positive number of metres")
    return round(weight_kg / (height_m ** 2), 2)


def classify_bmi(bmi):
    """Map a BMI value onto the standard WHO weight categories."""
    if bmi < 18.5:
        return "underweight"
    if bmi < 25.0:
        return "normal weight"
    if bmi < 30.0:
        return "overweight"
    return "obese"


def healthy_weight_range(height_m):
    """Return the (min, max) weight in kg giving a normal BMI at this height."""
    if height_m <= 0:
        raise ValueError("height must be a positive number of metres")
    lower = 18.5 * height_m ** 2
    upper = 24.9 * height_m ** 2
    return round(lower, 1), round(upper, 1)


def describe(name, weight_kg, height_m):
    """Build a one-line report for a single person."""
    bmi = calculate_bmi(weight_kg, height_m)
    category = classify_bmi(bmi)
    low, high = healthy_weight_range(height_m)
    line = "{:<8} {:>6.1f} kg {:>5.2f} m  BMI {:>5.2f}  {}".format(
        name, weight_kg, height_m, bmi, category
    )
    if category != "normal weight":
        if weight_kg < low:
            line += " (gain {:.1f} kg to reach {:.1f} kg)".format(low - weight_kg, low)
        else:
            line += " (lose {:.1f} kg to reach {:.1f} kg)".format(weight_kg - high, high)
    return line


def report(people):
    """Produce report lines for an iterable of (name, weight, height) records."""
    lines = []
    for name, weight_kg, height_m in people:
        try:
            lines.append(describe(name, weight_kg, height_m))
        except ValueError as exc:
            lines.append("{:<8} skipped: {}".format(name, exc))
    return lines


def average_bmi(people):
    """Average BMI over the records that hold usable measurements."""
    values = []
    for _name, weight_kg, height_m in people:
        if weight_kg > 0 and height_m > 0:
            values.append(calculate_bmi(weight_kg, height_m))
    if not values:
        return None
    return round(sum(values) / len(values), 2)


def main():
    people = [
        ("Ana", 70, 1.75),
        ("Ben", 100, 2.0),
        ("Cleo", 48, 1.68),
        ("Dan", 95, 1.70),
        ("Eve", 60, 0),
    ]
    for line in report(people):
        print(line)
    mean = average_bmi(people)
    if mean is None:
        print("no valid measurements")
    else:
        print("Average BMI: {:.2f} ({})".format(mean, classify_bmi(mean)))


if __name__ == "__main__":
    main()

