def binary_to_decimal(binary_string):
    decimal_value = 0
    power = 0
    for digit in reversed(binary_string):
        if digit == '1':
            decimal_value += 2 ** power
        elif digit != '0':
            raise ValueError("Invalid binary digit found.")
        power += 1
    return decimal_value

# Example usage:
if __name__ == '__main__':
    print(f"'1011' in decimal is: {binary_to_decimal('1011')}")
    print(f"'1' in decimal is: {binary_to_decimal('1')}")
    print(f"'0' in decimal is: {binary_to_decimal('0')}")
    print(f"'1000' in decimal is: {binary_to_decimal('1000')}")
    print(f"'11111' in decimal is: {binary_to_decimal('11111')}")
    try:
        binary_to_decimal('102')
    except ValueError as e:
        print(f"Error for '102': {e}")

