import sys


def parse_numbers(tokens):
    """Convert a sequence of strings into a list of ints/floats."""
    numbers = []
    for token in tokens:
        text = token.strip().rstrip(",")
        if not text:
            continue
        try:
            numbers.append(int(text))
        except ValueError:
            try:
                numbers.append(float(text))
            except ValueError:
                raise ValueError("not a number: {!r}".format(token))
    return numbers


def find_smallest(numbers):
    """Return the minimum value of a non-empty list of ints/floats."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of int/float")
    if len(numbers) == 0:
        raise ValueError("cannot find the smallest value of an empty list")
    smallest_number = None
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("list elements must be int or float, got {!r}".format(value))
        if smallest_number is None or value < smallest_number:
            smallest_number = value
    return smallest_number


def format_number(value):
    """Render a number without a trailing '.0' for whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(numbers):
    """Build a one-line report about the smallest value and where it occurs."""
    smallest_number = find_smallest(numbers)
    positions = []
    for index, value in enumerate(numbers):
        if value == smallest_number:
            positions.append(index)
    places = ", ".join(str(position) for position in positions)
    template = "smallest = {} (at index {} of {} values)"
    return template.format(format_number(smallest_number), places, len(numbers))


def main(argv):
    if len(argv) > 1:
        tokens = argv[1:]
    else:
        tokens = sys.stdin.read().split()
    try:
        numbers = parse_numbers(tokens)
        print(describe(numbers))
    except (TypeError, ValueError) as error:
        print("error: {}".format(error), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

