def update_dict(dict1, dict2):
    """Return a new dict with dict1's entries overridden/extended by dict2."""
    if not isinstance(dict1, dict):
        raise TypeError("dict1 must be a dict, got %s" % type(dict1).__name__)
    if not isinstance(dict2, dict):
        raise TypeError("dict2 must be a dict, got %s" % type(dict2).__name__)
    merged_dict = {}
    for key, value in dict1.items():
        merged_dict[key] = value
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def deep_update_dict(dict1, dict2):
    """Like update_dict, but nested dicts are merged instead of replaced."""
    merged_dict = update_dict(dict1, dict2)
    for key in dict1:
        if key in dict2:
            left, right = dict1[key], dict2[key]
            if isinstance(left, dict) and isinstance(right, dict):
                merged_dict[key] = deep_update_dict(left, right)
    return merged_dict


def classify_keys(dict1, dict2):
    """Split the keys of a merge into kept, overridden and added groups."""
    kept, overridden, added = [], [], []
    for key in dict1:
        if key in dict2:
            overridden.append(key)
        else:
            kept.append(key)
    for key in dict2:
        if key not in dict1:
            added.append(key)
    return {"kept": kept, "overridden": overridden, "added": added}


def format_merge_report(dict1, dict2):
    """Build a human readable description of merging dict2 into dict1."""
    merged_dict = deep_update_dict(dict1, dict2)
    groups = classify_keys(dict1, dict2)
    lines = ["merged: %r" % (merged_dict,)]
    for name in ("kept", "overridden", "added"):
        keys = sorted(groups[name], key=repr)
        if keys:
            details = []
            for key in keys:
                if name == "overridden":
                    details.append("%r: %r -> %r" % (key, dict1[key], merged_dict[key]))
                else:
                    details.append("%r: %r" % (key, merged_dict[key]))
            lines.append("  %-10s %s" % (name + ":", ", ".join(details)))
        else:
            lines.append("  %-10s (none)" % (name + ":"))
    return "\n".join(lines)


def main():
    settings = {"db": {"host": "localhost", "port": 5432}, "debug": False}
    overrides = {"db": {"port": 6543, "user": "admin"}, "debug": True}
    cases = [
        ({"a": 1, "b": 2}, {"b": 3, "c": 4}),
        ({"x": 10}, {"y": 20}),
        (settings, overrides),
    ]
    for dict1, dict2 in cases:
        print("update_dict(%r, %r)" % (dict1, dict2))
        print(format_merge_report(dict1, dict2))
        print()


if __name__ == "__main__":
    main()

