def validate_inputs(values, weights):
    """Check that values and weights form a usable pair of numeric sequences."""
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    for weight in weights:
        if weight < 0:
            raise ValueError("weights must be non-negative")
    total = sum(weights)
    if total == 0:
        raise ValueError("the sum of the weights must not be zero")
    return total


def weighted_average(values, weights):
    """Return the weighted average of values using the matching weights."""
    total_weight = validate_inputs(values, weights)
    accumulated = 0.0
    for value, weight in zip(values, weights):
        accumulated += value * weight
    return accumulated / total_weight


def normalized_weights(weights):
    """Return the weights rescaled so that they sum to one."""
    total = float(sum(weights))
    return [weight / total for weight in weights]


def format_breakdown(values, weights):
    """Build text lines showing each value, its share and its contribution."""
    shares = normalized_weights(weights)
    lines = []
    for value, share in zip(values, shares):
        lines.append("  {:>8.3f} x {:>6.2%} = {:>8.3f}".format(value, share, value * share))
    return lines


def report(label, values, weights):
    """Print a labelled breakdown followed by the weighted average."""
    print(label)
    for line in format_breakdown(values, weights):
        print(line)
    print("  weighted average: {:.3f}".format(weighted_average(values, weights)))


def course_grade(scores):
    """Combine assessment scores given as (name, score, credit) triples."""
    values = []
    weights = []
    for name, score, credit in scores:
        if credit <= 0:
            raise ValueError("credit for {} must be positive".format(name))
        values.append(score)
        weights.append(credit)
    return weighted_average(values, weights)


def main():
    report("Simple integer weights", [10, 20, 30], [1, 2, 1])
    report("Fractional weights", [5, 10], [0.5, 0.5])
    scores = [
        ("homework", 88.0, 2),
        ("midterm", 74.5, 3),
        ("final", 91.0, 5),
    ]
    print("Course grade: {:.2f}".format(course_grade(scores)))
    for bad_values, bad_weights in [([1, 2], [1]), ([], []), ([1, 2], [0, 0])]:
        try:
            weighted_average(bad_values, bad_weights)
        except ValueError as error:
            print("rejected {}/{}: {}".format(bad_values, bad_weights, error))


if __name__ == "__main__":
    main()

