def flatten_dict(nested_dict, separator):
    flattened_dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                new_key = f"{key}{separator}{sub_key}"
                flattened_dict[new_key] = sub_value
        else:
            flattened_dict[key] = value
    return flattened_dict

if __name__ == '__main__':
    example_dict1 = {'a': 1, 'b': {'c': 2, 'd': 3}}
    separator1 = '_'
    result1 = flatten_dict(example_dict1, separator1)
    print(f"Flattened dict 1: {result1}")
    expected_result1 = {'a': 1, 'b_c': 2, 'b_d': 3}
    assert result1 == expected_result1, f"Test 1 failed. Expected: {expected_result1}, Got: {result1}"

    example_dict2 = {'x': {'y': 10}}
    separator2 = '.'
    result2 = flatten_dict(example_dict2, separator2)
    print(f"Flattened dict 2: {result2}")
    expected_result2 = {'x.y': 10}
