def parse_url(url):
    """Split a URL into (scheme, host, path); missing parts come back empty."""
    if not isinstance(url, str):
        raise TypeError('url must be a string, got %s' % type(url).__name__)
    remainder = url.strip()
    scheme = ''
    if '://' in remainder:
        scheme, remainder = remainder.split('://', 1)
        scheme = scheme.lower()
    path = ''
    for index, character in enumerate(remainder):
        if character in '/?#':
            path = remainder[index:]
            remainder = remainder[:index]
            break
    return scheme, remainder.lower(), path


def validate_url(url):
    """Return a cleaned URL, defaulting the scheme to http when absent."""
    scheme, host, path = parse_url(url)
    if not host:
        raise ValueError('missing host in URL: %r' % url)
    if scheme == '':
        scheme = 'http'
    if scheme not in ('http', 'https'):
        raise ValueError('unsupported scheme %r in URL: %r' % (scheme, url))
    return '%s://%s%s' % (scheme, host, path)


def check_website_status(url):
    """Pretend to perform an HTTP request and report the resulting status."""
    return '200 OK'


def check_many(urls):
    """Check several URLs, returning a list of (url, status_or_error) pairs."""
    results = []
    for url in urls:
        try:
            cleaned = validate_url(url)
        except (TypeError, ValueError) as problem:
            results.append((str(url), 'ERROR: %s' % problem))
            continue
        results.append((cleaned, check_website_status(cleaned)))
    return results


def format_report(results):
    """Render check results as an aligned, human readable table."""
    if not results:
        return 'no URLs checked'
    width = max(len(url) for url, status in results)
    lines = []
    healthy = 0
    for url, status in results:
        lines.append('%-*s  %s' % (width, url, status))
        if status == '200 OK':
            healthy += 1
    lines.append('%d/%d reachable' % (healthy, len(results)))
    return '\n'.join(lines)


def main():
    urls = [
        'http://example.com',
        'https://google.com',
        'example.org/status?verbose=1',
        'ftp://files.example.net',
        '://broken',
    ]
    print(format_report(check_many(urls)))


if __name__ == '__main__':
    main()

