def fibonacci_sequence(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]

    fib_list = [0, 1]
    while True:
        next_fib = fib_list[-1] + fib_list[-2]
        if next_fib >= n:
            break
        fib_list.append(next_fib)
        if len(fib_list) > 1000:  # Safety break for very large n
            break
    return fib_list

