def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    if not isinstance(query_string, str):
        raise TypeError('query_string must be a str')
    params = {}
    for chunk in query_string.split('&'):
        if not chunk:
            continue
        if '=' in chunk:
            key, value = chunk.split('=', 1)
        else:
            key, value = chunk, ''
        key = key.strip()
        if key:
            params[key] = value.strip()
    return params


def extract_query(url):
    """Return the query part of a full URL (empty string when absent)."""
    without_fragment = url.split('#', 1)[0]
    if '?' in without_fragment:
        return without_fragment.split('?', 1)[1]
    return ''


def parse_url(url):
    """Parse the query section of a complete URL into a dictionary."""
    return parse_url_params(extract_query(url))


