    """Build aligned 'key = value' report lines for a parsed query."""
    if not params:
        return ['(no parameters)']
    width = max(len(key) for key in params)
    lines = []
    for key, value in params.items():
        if value:
            lines.append('{0:<{1}} = {2}'.format(key, width, value))
        else:
            lines.append('{0:<{1}} = <empty>'.format(key, width))
    return lines


