			total += len(line.split())
	return total


def count_lines_in_file(filepath):
	lines = 0
	with open(filepath, "r", encoding="utf-8") as handle:
		for _line in handle:
			lines += 1
	return lines


def word_frequencies(filepath):
	counts = {}
	with open(filepath, "r", encoding="utf-8") as handle:
		for line in handle:
			for raw in line.split():
				word = raw.strip(".,;:!?\"'()[]").lower()
				if word:
					counts[word] = counts.get(word, 0) + 1
	return counts


def format_report(filepath):
	words = count_words_in_file(filepath)
	lines = count_lines_in_file(filepath)
	freqs = word_frequencies(filepath)
	rows = ["File: {}".format(filepath),
			"Lines: {}".format(lines),
			"Words: {}".format(words),
			"Distinct words: {}".format(len(freqs))]
	ordered = sorted(freqs.items(), key=lambda item: (-item[1], item[0]))
	for word, count in ordered[:5]:
		rows.append("  {:<15} {}".format(word, count))
	return "\n".join(rows)


def main(argv):
	paths = argv[1:]
	if not paths:
		paths = ["test.txt"]
	missing = []
	for path in paths:
		if not os.path.isfile(path):
			missing.append(path)
	for path in missing:
		print("skipping {}: not a readable file".format(path))
		paths.remove(path)
	if not paths:
		return 1
	grand_total = 0
	for path in paths:
		print(format_report(path))
		grand_total += count_words_in_file(path)
	if len(paths) > 1:
		print("Total words across {} files: {}".format(len(paths), grand_total))
	return 0


if __name__ == "__main__":
	sys.exit(main(sys.argv))

