def xor_cipher(text, key_char):
    """XOR every character of `text` with `key_char` and return the result."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not isinstance(key_char, str) or len(key_char) != 1:
        raise ValueError("key_char must be exactly one character")
    key = ord(key_char)
    out = []
    for ch in text:
        out.append(chr(ord(ch) ^ key))
    return "".join(out)


def to_hex(text):
    """Render a string as space separated two-digit hex codes."""
    parts = []
    for ch in text:
        code = ord(ch)
        if code > 0xFF:
            parts.append("%04x" % code)
        else:
            parts.append("%02x" % code)
    return " ".join(parts)


def printable(text):
    """Replace control and non-ASCII characters with dots for display."""
    shown = []
    for ch in text:
        if 32 <= ord(ch) < 127:
            shown.append(ch)
        else:
            shown.append(".")
    return "".join(shown)


def crack(cipher, known_plain_char, position=0):
    """Recover the key character given one known plaintext character."""
    if position < 0 or position >= len(cipher):
        raise IndexError("position outside cipher text")
    return chr(ord(cipher[position]) ^ ord(known_plain_char))


def report(text, key_char):
    """Encrypt `text`, verify the round trip and return a report string."""
    cipher = xor_cipher(text, key_char)
    plain = xor_cipher(cipher, key_char)
    lines = [
        "plain : %s" % text,
        "key   : %r (0x%02x)" % (key_char, ord(key_char)),
        "cipher: %s" % printable(cipher),
        "hex   : %s" % to_hex(cipher),
    ]
    if plain == text:
        lines.append("check : round trip ok")
    else:
        lines.append("check : FAILED, got %r" % plain)
    return "\n".join(lines)


def main():
    samples = [("Hello", "A"), ("Test", "B"), ("Attack at dawn!", "k")]
    for text, key_char in samples:
        print(report(text, key_char))
        print("-" * 40)
    secret = xor_cipher("Meet me at noon", "Z")
    guessed = crack(secret, "M")
    print("recovered key: %r" % guessed)
    if guessed == "Z":
        print("decrypted: %s" % xor_cipher(secret, guessed))
    else:
        print("key recovery failed")


if __name__ == "__main__":
    main()

