def group_by_type(items):
    """Group items by their type name, preserving first-seen order of types."""
    groups = {}
    for item in items:
        name = type(item).__name__
        if name not in groups:
            groups[name] = []
        groups[name].append(item)
    return groups


def type_counts(groups):
    """Return a list of (type name, count) pairs sorted by descending count."""
    pairs = []
    for name, members in groups.items():
        pairs.append((name, len(members)))
    pairs.sort(key=lambda pair: (-pair[1], pair[0]))
    return pairs


def dominant_type(groups):
    """Return the type name with the most members, or None for empty input."""
    counts = type_counts(groups)
    if not counts:
        return None
    return counts[0][0]


def format_group(name, members, limit=4):
    """Render one group as 'name (n): a, b, ...' truncating long member lists."""
    shown = []
    for member in members[:limit]:
        shown.append(repr(member))
    if len(members) > limit:
        shown.append("...")
    return "{} ({}): {}".format(name, len(members), ", ".join(shown))


def report(items):
    """Build a multi-line human readable summary of the grouping of items."""
    groups = group_by_type(items)
    lines = ["{} item(s) in {} type(s)".format(len(items), len(groups))]
    for name, _count in type_counts(groups):
        lines.append("  " + format_group(name, groups[name]))
    top = dominant_type(groups)
    if top is not None:
        lines.append("  most common type: {}".format(top))
    return "\n".join(lines)


def flatten_grouped(groups, order=None):
    """Concatenate group members, following `order` first then remaining types."""
    names = []
    if order is not None:
        for name in order:
            if name in groups:
                names.append(name)
    for name in groups:
        if name not in names:
            names.append(name)
    result = []
    for name in names:
        result.extend(groups[name])
    return result


def main():
    sample = [1, 'a', 2.5, 'b', 3, None, True, (1, 2), 'c', 4.0, 7, [9]]
    print(group_by_type([1, 'a', 2.5, 'b', 3]))
    print(report(sample))
    grouped = group_by_type(sample)
    print(flatten_grouped(grouped, order=['str', 'int']))
    print(report([]))


if __name__ == '__main__':
    main()

