def binary_search(sorted_list, target):
    """Return the index of target in sorted_list, or -1 if it is absent."""
    low = 0
    high = len(sorted_list) - 1
    while low <= high:
        middle = (low + high) // 2
        candidate = sorted_list[middle]
        if candidate == target:
            return middle
        if candidate < target:
            low = middle + 1
        else:
            high = middle - 1
    return -1


def is_sorted(values):
    """Report whether values are in non-decreasing order."""
    for index in range(1, len(values)):
        if values[index] < values[index - 1]:
            return False
    return True


def insertion_point(sorted_list, target):
    """Return the index where target would keep sorted_list ordered."""
    low = 0
    high = len(sorted_list)
    while low < high:
        middle = (low + high) // 2
        if sorted_list[middle] < target:
            low = middle + 1
        else:
            high = middle
    return low


def search_report(sorted_list, targets):
    """Build one human readable line per target, searching each one."""
    if not is_sorted(sorted_list):
        raise ValueError("binary search requires a sorted list")
    lines = []
    for target in targets:
        index = binary_search(sorted_list, target)
        if index == -1:
            spot = insertion_point(sorted_list, target)
            lines.append("{0} not found (insert at index {1})".format(target, spot))
        else:
            lines.append("{0} found at index {1}".format(target, index))
    return lines


def count_occurrences(sorted_list, target):
    """Count how many times target appears, using the ordering."""
    first = insertion_point(sorted_list, target)
    last = insertion_point(sorted_list, target + 1) if isinstance(target, int) else None
    if last is None:
        total = 0
        for value in sorted_list[first:]:
            if value != target:
                break
            total += 1
        return total
    return last - first


def main():
    data = [1, 2, 3, 5, 5, 7, 9, 9, 9, 12]
    queries = [5, 4, 1, 12, 13, 9]
    for line in search_report(data, queries):
        print(line)
    for target in sorted(set(queries)):
        times = count_occurrences(data, target)
        if times > 1:
            print("{0} appears {1} times".format(target, times))


if __name__ == "__main__":
    main()

