def is_valid_isbn10(isbn):
    if not isinstance(isbn, str):
        return False
    if len(isbn) != 10:
        return False

    checksum = 0
    for i in range(9):
        if '0' <= isbn[i] <= '9':
            checksum += int(isbn[i]) * (i + 1)
        else:
            return False

    last_char = isbn[9]
    if '0' <= last_char <= '9':
        checksum += int(last_char) * 10
    elif last_char == 'X' or last_char == 'x':
        checksum += 10 * 10
    else:
        return False

    if checksum % 11 == 0:
        return True
    else:
        return False

