def extract_domain(url):
    parts = url.split('//')
    if len(parts) > 1:
        domain_path = parts[1]
    else:
        domain_path = parts[0]

    domain_parts = domain_path.split('/')
    main_domain_with_tld = domain_parts[0]

    if main_domain_with_tld.startswith('www.'):
        main_domain_with_tld = main_domain_with_tld[4:]

    try:
        if '.' in main_domain_with_tld:
            domain_components = main_domain_with_tld.split('.')
            if len(domain_components) > 1:
                return domain_components[-2]
            else:
                return main_domain_with_tld
        else:
            return main_domain_with_tld
    except Exception as e:
        print(f"An error occurred: {e}")
        return ""

