import sys


def get_quadrant(x, y):
    """Return the quadrant (1-4) of the point (x, y), or 0 if it lies on an axis."""
    for name, value in (("x", x), ("y", y)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("coordinate %s must be an int or a float" % name)
    if x == 0 or y == 0:
        return 0
    if x > 0:
        if y > 0:
            return 1
        return 4
    if y > 0:
        return 2
    return 3


def parse_point(text):
    """Parse a point written as 'x y' or 'x,y' into a pair of floats."""
    cleaned = text.replace(",", " ").strip()
    parts = cleaned.split()
    if len(parts) != 2:
        raise ValueError("expected two coordinates, got %d" % len(parts))
    coordinates = []
    for part in parts:
        try:
            coordinates.append(float(part))
        except ValueError:
            raise ValueError("%r is not a number" % part)
    return coordinates[0], coordinates[1]


def describe(x, y, quadrant):
    """Build a one-line human readable description of a classified point."""
    location = "quadrant %d" % quadrant
    if quadrant == 0:
        if x == 0 and y == 0:
            location = "the origin"
        elif y == 0:
            location = "the x-axis"
        else:
            location = "the y-axis"
    return "(%g, %g) lies in %s" % (x, y, location)


def classify_all(lines):
    """Classify every non-empty line, returning descriptions and error messages."""
    report = []
    for number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            x, y = parse_point(line)
        except ValueError as error:
            report.append("line %d: %s" % (number, error))
            continue
        report.append(describe(x, y, get_quadrant(x, y)))
    return report


def main(argv):
    if len(argv) > 1:
        lines = argv[1:]
    else:
        lines = sys.stdin.read().splitlines()
    report = classify_all(lines)
    if not report:
        print("no points given")
        return 1
    for entry in report:
        print(entry)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

