def check_interval_overlap(interval1, interval2):
	start1, end1 = interval1
	start2, end2 = interval2

	if start1 <= end2 and start2 <= end1:
		if start1 < end1 or start2 < end2:  # Ensure at least one interval has a non-zero length for overlap
			if not (end1 == start2 or end2 == start1):  # Exclude touch-but-no-overlap cases
				return True
			else:
				if start1 == end1 and start2 == end2: # Both are point intervals
					if start1 == start2:
						return True
					else:
						return False
				elif start1 == end1: # First is point interval
					if start1 >= start2 and start1 <= end2:
						return True
					else:
						return False
				elif start2 == end2: # Second is point interval
					if start2 >= start1 and start2 <= end1:
						return True
					else:
						return False
				else: # Neither is a point interval, and they only touch
					return False
		else: # One or both intervals have zero length and don't overlap or are identical
			if start1 == end1 and start2 == end2 and start1 == start2:
				return True # Two identical point intervals overlap
			else:
				return False
	else:
		return False

