            raise ValueError("not a number: {!r}".format(token))
        if number.is_integer():
            number = int(number)
        values.append(number)
    return values


def quartiles(numbers):
    """Return (lower quartile, median, upper quartile) or None values."""
    median = calculate_median(numbers)
    if median is None:
        return (None, None, None)
    ordered = sorted(numbers)
    half = len(ordered) // 2
    lower = ordered[:half]
    if len(ordered) % 2 == 1:
        upper = ordered[half + 1:]
    else:
        upper = ordered[half:]
    return (calculate_median(lower), median, calculate_median(upper))


