def is_valid_us_zip_code(code):
    """Return True if `code` is a string of exactly 5 digits."""
    if not isinstance(code, str):
        return False
    if len(code) != 5:
        return False
    for character in code:
        if character not in '0123456789':
            return False
    return True


def normalize_zip_code(raw):
    """Strip surrounding whitespace and drop a ZIP+4 suffix if present."""
    trimmed = raw.strip()
    if '-' in trimmed:
        trimmed = trimmed.split('-', 1)[0].strip()
    return trimmed


def parse_zip_codes(text):
    """Split free-form text into candidate zip codes, one per comma or line."""
    candidates = []
    for line in text.splitlines():
        for field in line.split(','):
            cleaned = normalize_zip_code(field)
            if cleaned:
                candidates.append(cleaned)
    return candidates


def classify(candidates):
    """Return two lists: the valid zip codes and the rejected candidates."""
    valid = []
    invalid = []
    for candidate in candidates:
        if is_valid_us_zip_code(candidate):
            valid.append(candidate)
        else:
            invalid.append(candidate)
    return valid, invalid


def describe_failure(candidate):
    """Explain why a candidate is not a valid zip code."""
    digits_only = all(character in '0123456789' for character in candidate)
    if not digits_only:
        return 'contains non-digit characters'
    if len(candidate) < 5:
        return 'too short ({0} digits)'.format(len(candidate))
    return 'too long ({0} digits)'.format(len(candidate))


def build_report(text):
    """Produce printable report lines for every candidate found in `text`."""
    valid, invalid = classify(parse_zip_codes(text))
    lines = ['Accepted: {0}'.format(len(valid)), 'Rejected: {0}'.format(len(invalid))]
    for code in valid:
        lines.append('  OK      {0}'.format(code))
    for code in invalid:
        lines.append('  BAD     {0} -- {1}'.format(code, describe_failure(code)))
    return lines


def main():
    raw_input_text = (
        '90210, 1234\n'
        '10001-1234,  02139 \n'
        'ABCDE, 123456\n'
    )
    for line in build_report(raw_input_text):
        print(line)


if __name__ == '__main__':
    main()

