def geometric_series_sum(a, r, n):
    """Return the sum of the first n terms of a geometric series."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if r == 1:
        return a * n
    return a * (1 - r ** n) / (1 - r)


def series_terms(a, r, n):
    """Yield the individual terms of the series, one at a time."""
    term = a
    for _ in range(n):
        yield term
        term *= r


def format_term(value):
    """Render a numeric term compactly, dropping trailing .0 on whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_series(a, r, n, max_shown=5):
    """Build a readable expression such as '1 + 2 + 4 = 7'."""
    pieces = []
    for index, term in enumerate(series_terms(a, r, n)):
        if index == max_shown:
            pieces.append("...")
            break
        pieces.append(format_term(term))
    total = geometric_series_sum(a, r, n)
    if not pieces:
        return "(empty series) = 0"
    return " + ".join(pieces) + " = " + format_term(total)


def convergence_note(r, n):
    """Describe how the partial sums behave for the given ratio."""
    magnitude = abs(r)
    if magnitude < 1:
        limit = 1 / (1 - r)
        return "terms shrink; sum approaches a*{0}".format(format_term(limit))
    if magnitude == 1:
        if r == 1:
            return "constant terms; sum grows linearly with n"
        return "alternating terms; partial sums oscillate"
    return "terms grow; sum after {0} terms is dominated by the last one".format(n)


def main():
    cases = [(1, 2, 3), (5, 1, 4), (3, 0.5, 8), (2, -3, 5), (7, 4, 0)]
    for a, r, n in cases:
        total = geometric_series_sum(a, r, n)
        print("a={0}, r={1}, n={2}".format(format_term(a), format_term(r), n))
        print("    " + format_series(a, r, n))
        print("    sum   : " + format_term(total))
        if n > 0:
            print("    note  : " + convergence_note(r, n))
    try:
        geometric_series_sum(1, 2, -4)
    except ValueError as error:
        print("rejected negative n: {0}".format(error))


if __name__ == "__main__":
    main()

