def is_point_in_circle(px, py, cx, cy, radius):
    """Return True if (px, py) lies inside or on the circle, False otherwise."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    dx = px - cx
    dy = py - cy
    return dx * dx + dy * dy <= radius * radius


def classify_point(px, py, cx, cy, radius):
    """Return 'inside', 'boundary' or 'outside' for the point/circle pair."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    dx = px - cx
    dy = py - cy
    squared = dx * dx + dy * dy
    limit = radius * radius
    if squared < limit:
        return "inside"
    if squared == limit:
        return "boundary"
    return "outside"


def parse_query(text):
    """Parse '1 1 0 0 2' into a tuple of five floats."""
    parts = text.replace(",", " ").split()
    if len(parts) != 5:
        raise ValueError("expected 5 numbers, got %d" % len(parts))
    values = []
    for part in parts:
        try:
            values.append(float(part))
        except ValueError:
            raise ValueError("not a number: %r" % part)
    return tuple(values)


def format_result(query):
    """Build a one-line report for a parsed query tuple."""
    px, py, cx, cy, radius = query
    inside = is_point_in_circle(px, py, cx, cy, radius)
    where = classify_point(px, py, cx, cy, radius)
    return "point (%g, %g) vs circle (%g, %g) r=%g -> %s (%s)" % (
        px, py, cx, cy, radius, inside, where)


def run_queries(lines):
    """Turn raw query lines into report lines, reporting bad input inline."""
    reports = []
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        try:
            reports.append(format_result(parse_query(stripped)))
        except ValueError as error:
            reports.append("invalid query %r: %s" % (stripped, error))
    return reports


def main():
    queries = [
        "1 1 0 0 2",
        "3 3 0 0 2",
        "2, 0, 0, 0, 2",
        "-1.5 -1.5 -2 -2 1",
        "0 0 0 0 -3",
        "4 5 1",
    ]
    for report in run_queries(queries):
        print(report)


if __name__ == "__main__":
    main()

