def validate_tasks(tasks):
    """Check that every task is well formed and that dependencies exist."""
    names = set()
    for task in tasks:
        if 'name' not in task or 'dependencies' not in task:
            raise ValueError("each task needs 'name' and 'dependencies'")
        if task['name'] in names:
            raise ValueError("duplicate task name: %s" % task['name'])
        names.add(task['name'])
    for task in tasks:
        for dependency in task['dependencies']:
            if dependency not in names:
                message = "unknown dependency %r of task %r"
                raise ValueError(message % (dependency, task['name']))
    return names


def find_task(task_name, tasks):
    """Return the task dict called task_name, or None when absent."""
    for task in tasks:
        if task['name'] == task_name:
            return task
    return None


def unmet_dependencies(task_name, tasks, completed_tasks):
    """List the dependencies of task_name that are not completed yet."""
    task = find_task(task_name, tasks)
    if task is None:
        raise KeyError("no such task: %s" % task_name)
    done = set(completed_tasks)
    missing = []
    for dependency in task['dependencies']:
        if dependency not in done:
            missing.append(dependency)
    return missing


def has_unmet_dependencies(task_name, tasks, completed_tasks):
    """True when at least one dependency of task_name is still pending."""
    return bool(unmet_dependencies(task_name, tasks, completed_tasks))


def runnable_tasks(tasks, completed_tasks):
    """Names of tasks that are not done but whose dependencies all are."""
    ready = []
    for task in tasks:
        if task['name'] in completed_tasks:
            continue
        if not has_unmet_dependencies(task['name'], tasks, completed_tasks):
            ready.append(task['name'])
    return ready


def format_report(tasks, completed_tasks):
    """Build a human readable status line for every known task."""
    validate_tasks(tasks)
