def is_positive_integer(value):
    try:
        if isinstance(value, bool):
            return False
        if isinstance(value, int):
            if value > 0:
                return True
            else:
                return False
        elif isinstance(value, float):
            if value > 0 and value == int(value):
                return True
            else:
                return False
        elif isinstance(value, str):
            if value.isdigit():
                if int(value) > 0:
                    return True
                else:
                    return False
            else:
                return False
        else:
            return False
    except Exception:
        return False

