import math


def _validate_vector(vec, name):
    if not isinstance(vec, (tuple, list)):
        raise TypeError(name + " must be a tuple of two numbers")
    if len(vec) != 2:
        raise ValueError(name + " must have exactly two components")
    for component in vec:
        if isinstance(component, bool) or not isinstance(component, (int, float)):
            raise TypeError(name + " components must be numbers")


def calculate_dot_product(vec1, vec2):
    _validate_vector(vec1, "vec1")
    _validate_vector(vec2, "vec2")
    total = 0
    for a, b in zip(vec1, vec2):
        total += a * b
    return total


def magnitude(vec):
    return math.sqrt(calculate_dot_product(vec, vec))


def angle_between(vec1, vec2):
    denominator = magnitude(vec1) * magnitude(vec2)
    if denominator == 0:
        return None
    cosine = calculate_dot_product(vec1, vec2) / denominator
    if cosine > 1.0:
        cosine = 1.0
    elif cosine < -1.0:
        cosine = -1.0
    return math.degrees(math.acos(cosine))


def describe_relation(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    if product == 0:
        return "perpendicular (or involves a zero vector)"
    if product > 0:
        return "pointing in broadly the same direction"
    return "pointing in broadly opposite directions"


def format_vector(vec):
    parts = []
    for component in vec:
        if isinstance(component, int):
            parts.append(str(component))
        else:
            parts.append("%g" % component)
    return "(" + ", ".join(parts) + ")"


def format_report(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    header = "%s . %s = %g" % (format_vector(vec1), format_vector(vec2), product)
    lines = [header]
    angle = angle_between(vec1, vec2)
    if angle is None:
        lines.append("  angle: undefined")
    else:
        lines.append("  angle: %.2f degrees" % angle)
    lines.append("  relation: " + describe_relation(vec1, vec2))
    return "\n".join(lines)


def main():
    pairs = [
        ((1, 2), (3, 4)),
        ((0, 5), (10, 0)),
        ((-2, 3), (4, -1.5)),
        ((0, 0), (7, 8)),
    ]
    for vec1, vec2 in pairs:
        print(format_report(vec1, vec2))


if __name__ == "__main__":
    main()

