def enqueue(queue, item):
    if isinstance(queue, list):
        queue.append(item)

def dequeue(queue):
    if isinstance(queue, list):
        if len(queue) > 0:
            return queue.pop(0)
        else:
            return None
    else:
        return None

if __name__ == '__main__':
    my_queue = []
    print(f"Initial queue: {my_queue}")

    enqueue(my_queue, 10)
    enqueue(my_queue, 20)
    print(f"After enqueuing 10 and 20: {my_queue}")

    first_item = dequeue(my_queue)
    if first_item is not None:
        print(f"Dequeued item: {first_item}")
        print(f"Queue after dequeue: {my_queue}")
    else:
        print("Queue was empty, no item dequeued.")

    while len(my_queue) > 0:
        next_item = dequeue(my_queue)
        print(f"Dequeued {next_item}")
        print(f"Current queue: {my_queue}")

    empty_dequeue = dequeue(my_queue)
    if empty_dequeue is None:
        print("Attempted to dequeue from an empty queue, as expected.")

