def parse_url_params(url_string):
    query_params = {}
    if '?' in url_string:
        try:
            query_string = url_string.split('?', 1)[1]
            if query_string:
                pairs = query_string.split('&')
                for pair in pairs:
                    if '=' in pair:
                        key, value = pair.split('=', 1)
                        query_params[key] = value
                    else:
                        if pair:
