def calculate_triangle_perimeter(side1, side2, side3):
    """Return the perimeter of a triangle described by its three side lengths."""
    sides = (side1, side2, side3)
    for side in sides:
        if not isinstance(side, (int, float)) or isinstance(side, bool):
            raise TypeError("side lengths must be int or float, got %r" % (side,))
        if side <= 0:
            raise ValueError("side lengths must be positive, got %r" % (side,))
    longest = max(sides)
    if sum(sides) - longest <= longest:
        raise ValueError("sides %r violate the triangle inequality" % (sides,))
    return side1 + side2 + side3


def classify_triangle(side1, side2, side3):
    """Return 'equilateral', 'isosceles' or 'scalene' for the given sides."""
    a, b, c = sorted((side1, side2, side3))
    if a == b == c:
        return "equilateral"
    if a == b or b == c:
        return "isosceles"
    return "scalene"


def parse_sides(text):
    """Turn a textual description such as '3, 4, 5' into three numbers."""
    parts = [part.strip() for part in text.replace(";", ",").split(",")]
    parts = [part for part in parts if part]
    if len(parts) != 3:
        raise ValueError("expected exactly three side lengths in %r" % (text,))
    numbers = []
    for part in parts:
        try:
            value = float(part)
        except ValueError:
            raise ValueError("%r is not a number" % (part,))
        if value.is_integer():
            numbers.append(int(value))
        else:
            numbers.append(value)
    return numbers


def format_report(side1, side2, side3):
    """Build a one-line human readable summary for one triangle."""
    perimeter = calculate_triangle_perimeter(side1, side2, side3)
    kind = classify_triangle(side1, side2, side3)
    listed = " + ".join(str(side) for side in (side1, side2, side3))
    return "%s triangle: %s = %s" % (kind.capitalize(), listed, perimeter)


def main():
    descriptions = [
        "3, 4, 5",
        "7.5, 6, 8.5",
        "5; 5; 5",
        "2, 2, 3",
        "1, 2, 10",
        "4, -1, 4",
        "6, 6",
    ]
    for description in descriptions:
        try:
            sides = parse_sides(description)
            line = format_report(*sides)
        except (TypeError, ValueError) as error:
            line = "invalid input (%s)" % (error,)
        print("%-14s -> %s" % (description, line))


if __name__ == "__main__":
    main()

