def count_lines_in_text(text):
    if not text:
        return 0

    line_count = 0
    if '\n' not in text:
        return 1

    try:
        for char_index in range(len(text)):
            if text[char_index] == '\n':
                line_count += 1
        if not text.endswith('\n'):
            line_count += 1
    except TypeError:
        print("Input must be a string.")
        return -1 # Indicate an error

    return line_count

