        ('One\nTwo\nThree\nFour\nFive', 5),
        ('Just one line and a half\n', 1)
    ]

    for input_text, expected_output in test_cases:
        actual_output = count_lines_in_text(input_text)
        if actual_output == expected_output:
            print(f"Test passed for '{input_text[:20]}...': {actual_output}")
