def longest_coin_flip_streak(flips_str):
    if not flips_str:
        return 0

    max_streak = 0
    current_streak = 0
    previous_flip = ''

    for flip in flips_str:
        if flip == previous_flip:
            current_streak += 1
        else:
            if current_streak > max_streak:
                max_streak = current_streak
            current_streak = 1
            previous_flip = flip

    if current_streak > max_streak:
        max_streak = current_streak

    return max_streak

