def is_leap_year(year):
    """Return True when the given Gregorian year is a leap year."""
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

MONTH_NAMES = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


def count_days_in_month(year, month):
    """Return the number of days in the given month of the given year."""
    if month < 1 or month > 12:
        raise ValueError("month must be in the range 1..12")
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def count_days_in_year(year):
    """Return the total number of days in the given year."""
    total = 0
    for month in range(1, 13):
        total += count_days_in_month(year, month)
    return total


def format_month_line(year, month):
    """Return a single aligned report line for one month."""
    name = MONTH_NAMES[month - 1]
    days = count_days_in_month(year, month)
    return "{:>9}  {:>2} days".format(name, days)


def year_report(year):
    """Return a multi-line report of every month length in the year."""
    lines = ["Month lengths for {}".format(year)]
    for month in range(1, 13):
        lines.append(format_month_line(year, month))
    lines.append("Total: {} days".format(count_days_in_year(year)))
    if is_leap_year(year):
        lines.append("{} is a leap year.".format(year))
    else:
        lines.append("{} is a common year.".format(year))
    return "\n".join(lines)


def main():
    for year in (2023, 2024, 1900, 2000):
        print(year_report(year))
        print()


