def calculate_average_no_outliers(numbers, num_to_exclude):
    if not numbers:
        return 0.0

    numbers.sort()

    total_len = len(numbers)
    if 2 * num_to_exclude >= total_len:
        return 0.0

    try:
        if num_to_exclude > 0:
            trimmed_numbers = numbers[num_to_exclude:-num_to_exclude]
        else:
            trimmed_numbers = numbers

        if trimmed_numbers:
            current_sum = 0.0
            for num in trimmed_numbers:
                current_sum += num

            return current_sum / len(trimmed_numbers)
        else:
            # This case should ideally be caught by the 2 * num_to_exclude check
            # but serves as a final safeguard.
            return 0.0
    except IndexError:
        # This might occur if num_to_exclude somehow leads to an empty slice unexpectedly
        # (e.g., numbers[x:-x] with x = len(numbers)/2 for odd length lists)
        return 0.0

