def join_path_components(components):
    cleaned_components = []
    for component in components:
        if component:
            trimmed_component = component.strip('/')
            if trimmed_component:
                cleaned_components.append(trimmed_component)

    if not cleaned_components:
        return ""

    if components[0] == '/':
        final_path = '/' + '/'.join(cleaned_components)
    else:
        try:
            final_path = '/'.join(cleaned_components)
        except TypeError:
            print("Error: components must be strings.")
            raise

    if final_path == '/':
        return '/'
    else:
        while '//' in final_path:
            final_path = final_path.replace('//', '/')
        return final_path

