def validate_inventory(inventory):
    """Return a cleaned copy of the inventory, rejecting malformed entries."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of item_name: stock_level")
    cleaned = {}
    for name, level in inventory.items():
        if not isinstance(name, str):
            raise TypeError("item names must be strings, got %r" % (name,))
        if isinstance(level, bool) or not isinstance(level, int):
            raise TypeError("stock level for %s must be an int" % name)
        if level < 0:
            raise ValueError("stock level for %s cannot be negative" % name)
        key = name.strip()
        if not key:
            raise ValueError("item names cannot be blank")
        cleaned[key] = level
    return cleaned


def get_restock_reminders(inventory, threshold):
    """Return item names whose stock is below threshold, sorted alphabetically."""
    if isinstance(threshold, bool) or not isinstance(threshold, int):
        raise TypeError("threshold must be an int")
    stock = validate_inventory(inventory)
    reminders = []
    for name, level in stock.items():
        if level < threshold:
            reminders.append(name)
    return sorted(reminders)


def restock_quantities(inventory, threshold, target=None):
    """Map each low item to the units needed to reach the target level."""
    if target is None:
        target = threshold
    if target < threshold:
        raise ValueError("target level must not be below the threshold")
    stock = validate_inventory(inventory)
    needed = {}
    for name in get_restock_reminders(stock, threshold):
        needed[name] = target - stock[name]
    return needed


def format_report(inventory, threshold, target=None):
    """Build a human readable restock report as a list of text lines."""
    needed = restock_quantities(inventory, threshold, target)
    if not needed:
        return ["All %d items are adequately stocked." % len(inventory)]
    width = max(len(name) for name in needed)
    lines = ["Restock report (threshold %d):" % threshold]
    for name in sorted(needed):
        units = needed[name]
        label = "unit" if units == 1 else "units"
        lines.append("  %-*s  order %3d %s" % (width, name, units, label))
    lines.append("  %d item(s) need attention." % len(needed))
    return lines


def main():
    fruit = {'apple': 5, 'banana': 12, 'orange': 3}
    groceries = {'milk': 1, 'bread': 0, 'eggs': 2}
    for inventory, threshold in ((fruit, 5), (groceries, 3)):
        print(get_restock_reminders(inventory, threshold))
    for line in format_report(groceries, 3, target=10):
        print(line)
    for line in format_report(fruit, 2):
        print(line)


if __name__ == "__main__":
    main()

