def is_leap_year(year):
    """Return True if `year` is a leap year in the Gregorian calendar."""
    if not isinstance(year, int) or isinstance(year, bool):
        raise TypeError("year must be an integer")
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def days_in_year(year):
    """Return the number of days in the given year."""
    if is_leap_year(year):
        return 366
    return 365


def days_in_month(year, month):
    """Return the number of days in `month` (1-12) of `year`."""
    if month < 1 or month > 12:
        raise ValueError("month must be between 1 and 12")
    if month == 2:
        return 29 if is_leap_year(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def parse_year(text):
    """Convert a textual year into an integer, rejecting malformed input."""
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty year")
    try:
        return int(stripped)
    except ValueError:
        raise ValueError("not a valid year: %r" % text)


def leap_years_in_range(start, end):
    """Return every leap year in the inclusive range [start, end]."""
    if start > end:
        start, end = end, start
    found = []
    for year in range(start, end + 1):
        if is_leap_year(year):
            found.append(year)
    return found


def format_report(years):
    """Build a human readable report for a sequence of year strings."""
    lines = []
    for raw in years:
        try:
            year = parse_year(raw)
        except ValueError as exc:
            lines.append("skipped (%s)" % exc)
            continue
        verdict = "leap" if is_leap_year(year) else "common"
        lines.append(
            "%d is a %s year: %d days, February has %d"
            % (year, verdict, days_in_year(year), days_in_month(year, 2))
        )
    return "\n".join(lines)


def main():
    samples = ["2000", " 1900 ", "2024", "1999", "twenty"]
    print(format_report(samples))
    decade = leap_years_in_range(2020, 2030)
    print("Leap years 2020-2030: " + ", ".join(str(y) for y in decade))
    total = 0
    for year in decade:
        total += days_in_year(year)
    print("Combined length of those years: %d days" % total)


if __name__ == "__main__":
    main()

