import os
import tempfile


def read_first_n_lines(filepath, n):
    """Return the first n lines of the file at filepath as a list of strings."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    lines = []
    with open(filepath, "r", encoding="utf-8") as handle:
        for line in handle:
            if len(lines) >= n:
                break
            lines.append(line)
    return lines


def write_lines(filepath, texts):
    """Write one line per entry of texts and return the number of bytes written."""
    written = 0
    with open(filepath, "w", encoding="utf-8") as handle:
        for text in texts:
            written += handle.write(text + "\n")
    return written


def count_lines(filepath):
    """Return the total number of lines in the file."""
    total = 0
    with open(filepath, "r", encoding="utf-8") as handle:
        for _line in handle:
            total += 1
    return total


def format_preview(lines, total):
    """Build a human readable report of the previewed lines."""
    report = ["preview: {0} of {1} line(s)".format(len(lines), total)]
    for index, line in enumerate(lines, start=1):
        if line.endswith("\n"):
            body = line[:-1]
            marker = "<NL>"
        else:
            body = line
            marker = "<EOF>"
        report.append("{0:>3}: {1!r}{2}".format(index, body, marker))
    if not lines:
        report.append("    (nothing to show)")
    return "\n".join(report)


def main():
    directory = tempfile.mkdtemp(prefix="first_n_")
    filepath = os.path.join(directory, "data.txt")
    try:
        write_lines(filepath, ["Line 1", "Line 2", "Line 3"])
        total = count_lines(filepath)
        for request in (0, 2, 5):
            lines = read_first_n_lines(filepath, request)
            print("read_first_n_lines({0!r}, {1}) ->".format("data.txt", request))
            print(format_preview(lines, total))
            print()
    finally:
        os.remove(filepath)
        os.rmdir(directory)


if __name__ == "__main__":
    main()

