def contains_sublist(main_list, sub_list):
    if not sub_list:
        return True
    len_main = len(main_list)
    len_sub = len(sub_list)
    if len_sub > len_main:
        return False

    for i in range(len_main - len_sub + 1):
        found_match = True
        try:
            for j in range(len_sub):
                if main_list[i + j] != sub_list[j]:
                    found_match = False
                    break
        except IndexError:
            # This should ideally not be reached if range is calculated correctly,
            # but good practice for unexpected scenarios.
            found_match = False
        if found_match:
            return True
    return False

