def calculate_hamming_distance(s1, s2):
    """Return the number of positions at which s1 and s2 differ."""
    if len(s1) != len(s2):
        raise ValueError("strings must have equal length")
    distance = 0
    for a, b in zip(s1, s2):
        if a != b:
            distance += 1
    return distance


def mismatch_positions(s1, s2):
    """Return the list of indices where s1 and s2 differ."""
    if len(s1) != len(s2):
        raise ValueError("strings must have equal length")
    positions = []
    for index, (a, b) in enumerate(zip(s1, s2)):
        if a != b:
            positions.append(index)
    return positions


def similarity_ratio(s1, s2):
    """Return the fraction of positions where s1 and s2 agree."""
    if not s1:
        return 1.0
    return 1.0 - calculate_hamming_distance(s1, s2) / len(s1)


def mismatch_marker(s1, s2):
    """Build a caret line marking the differing columns."""
    differing = set(mismatch_positions(s1, s2))
    marks = []
    for index in range(len(s1)):
        if index in differing:
            marks.append("^")
        else:
            marks.append(" ")
    return "".join(marks)


def format_report(s1, s2):
    """Render a multi-line comparison report for two equal-length strings."""
    lines = [s1, s2, mismatch_marker(s1, s2)]
    lines.append("distance: {0}".format(calculate_hamming_distance(s1, s2)))
    lines.append("similarity: {0:.2%}".format(similarity_ratio(s1, s2)))
    positions = mismatch_positions(s1, s2)
    if positions:
        joined = ", ".join(str(p) for p in positions)
        lines.append("differing positions: " + joined)
    else:
        lines.append("the strings are identical")
    return "\n".join(lines)


def main():
    pairs = [
        ("karolin", "kathrin"),
        ("python", "python"),
        ("GATTACA", "GACTATA"),
        ("short", "longer"),
    ]
    for s1, s2 in pairs:
        try:
            print(format_report(s1, s2))
        except ValueError as error:
            print("cannot compare {0!r} and {1!r}: {2}".format(s1, s2, error))
        print("-" * 30)


if __name__ == "__main__":
    main()

