def fibonacci_sequence(n):
    """Return a list with the first n numbers of the Fibonacci sequence."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    sequence = []
    current, following = 0, 1
    while len(sequence) < n:
        sequence.append(current)
        current, following = following, current + following
    return sequence


def parse_count(argument):
    """Convert a command line argument into a usable sequence length."""
    text = argument.strip()
    if not text.isdigit():
        raise ValueError("expected a non-negative whole number, got %r" % argument)
    return int(text)


def format_sequence(sequence, per_row=8):
    """Render a sequence as right-aligned columns of at most per_row entries."""
    if not sequence:
        return "(empty sequence)"
    width = max(len(str(value)) for value in sequence)
    lines = []
    for start in range(0, len(sequence), per_row):
        row = sequence[start:start + per_row]
        lines.append(" ".join(str(value).rjust(width) for value in row))
    return "\n".join(lines)


def summarize(sequence):
    """Build a short report about the generated sequence."""
    if not sequence:
        return "No Fibonacci numbers were requested."
    even_total = 0
    for value in sequence:
        if value % 2 == 0:
            even_total += value
    parts = [
        "count=%d" % len(sequence),
        "last=%d" % sequence[-1],
        "sum=%d" % sum(sequence),
        "even_sum=%d" % even_total,
    ]
    return " ".join(parts)


def main(argv):
    if len(argv) > 1:
        requests = argv[1:]
    else:
        requests = ["10"]
    exit_code = 0
    for argument in requests:
        try:
            count = parse_count(argument)
        except ValueError as error:
            print("skipping %r: %s" % (argument, error))
            exit_code = 1
            continue
        sequence = fibonacci_sequence(count)
        print("fibonacci_sequence(%d):" % count)
        print(format_sequence(sequence))
        print(summarize(sequence))
        print()
    return exit_code


if __name__ == "__main__":
    import sys

    sys.exit(main(sys.argv))

