def are_anagrams(s1, s2):
    if not isinstance(s1, str) or not isinstance(s2, str):
        raise TypeError("Both inputs must be strings.")

    # Process first string
    processed_s1 = ""
    for char in s1:
        if 'a' <= char.lower() <= 'z':
            processed_s1 += char.lower()

    # Process second string
    processed_s2 = ""
    for char in s2:
        if 'a' <= char.lower() <= 'z':
            processed_s2 += char.lower()

    if len(processed_s1) != len(processed_s2):
        return False

    # Check character counts
    char_counts = {}
    for char in processed_s1:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    for char in processed_s2:
        if char in char_counts:
            char_counts[char] -= 1
        else:
            return False

    for count in char_counts.values():
        if count != 0:
            return False

    return True

