def trailing_zeros_factorial(n):
    """Count trailing zeros in n! by counting factors of 5."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    count = 0
    power = 5
    while power <= n:
        count += n // power
        power *= 5
    return count


def factor_multiplicity(n, prime):
    """Return the exponent of `prime` in the prime factorization of n!."""
    if prime < 2:
        raise ValueError("prime must be at least 2")
    total = 0
    power = prime
    while power <= n:
        total += n // power
        power *= prime
    return total


def smallest_n_with_zeros(zeros):
    """Return the smallest n such that n! ends with exactly `zeros` zeros."""
    low, high = 0, 5 * (zeros + 1)
    while low < high:
        mid = (low + high) // 2
        if trailing_zeros_factorial(mid) < zeros:
            low = mid + 1
        else:
            high = mid
    if trailing_zeros_factorial(low) != zeros:
        return None
    return low


def parse_inputs(tokens):
    """Convert command-line style tokens into non-negative integers."""
    values = []
    for token in tokens:
        try:
            value = int(token)
        except ValueError:
            print("skipping non-integer input: {0!r}".format(token))
            continue
        if value < 0:
            print("skipping negative input: {0}".format(value))
            continue
        values.append(value)
    return values


def format_report(values):
    """Build aligned report lines for each requested value of n."""
    lines = []
    width = max((len(str(v)) for v in values), default=1)
    for value in values:
        zeros = trailing_zeros_factorial(value)
        twos = factor_multiplicity(value, 2)
        lines.append(
            "{0:>{w}}! ends with {1} zero(s); 2-exponent={2}".format(
                value, zeros, twos, w=width
            )
        )
    return lines


def main(argv):
    values = parse_inputs(argv[1:]) or [5, 10, 25, 100]
    for line in format_report(values):
        print(line)
    for zeros in (1, 2, 5):
        n = smallest_n_with_zeros(zeros)
        if n is None:
            print("no factorial ends with exactly {0} zero(s)".format(zeros))
        else:
            print("smallest n with exactly {0} zero(s): {1}".format(zeros, n))


