class SimpleQueue:
    """A first-in, first-out queue backed by a plain Python list."""

    def __init__(self):
        self._items = []

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            raise IndexError("dequeue from an empty queue")
        return self._items.pop(0)

    def is_empty(self):
        return not self._items

    def __len__(self):
        return len(self._items)


def drain(queue):
    """Remove and return every item of the queue, front to back."""
    drained = []
    while not queue.is_empty():
        drained.append(queue.dequeue())
    return drained


def run_commands(queue, commands):
    """Apply textual commands to a queue and collect a report of the results."""
    report = []
    for line in commands:
        parts = line.split()
        if not parts:
            continue
        action = parts[0].lower()
        if action == "enqueue":
            if len(parts) != 2:
                report.append("error: enqueue needs exactly one argument")
                continue
            queue.enqueue(parts[1])
            report.append("enqueued {}".format(parts[1]))
        elif action == "dequeue":
            try:
                report.append("dequeued {}".format(queue.dequeue()))
            except IndexError as exc:
                report.append("error: {}".format(exc))
        elif action == "size":
            report.append("size {}".format(len(queue)))
        else:
            report.append("error: unknown command {!r}".format(action))
    return report


def main():
