        "enqueue b",
        "size",
        "dequeue",
        "shuffle",
        "enqueue",
    ]
    scripted = SimpleQueue()
    for message in run_commands(scripted, script):
        print(message)
    print("remaining:", drain(scripted))


if __name__ == "__main__":
