import sys


def normalize_name(full_name):
    if not isinstance(full_name, str):
        raise TypeError('full_name must be a string')
    parts = []
    for chunk in full_name.replace('-', ' ').split():
        cleaned = chunk.strip('.,')
        if cleaned:
            parts.append(cleaned)
    return parts


def get_initials(full_name):
    initials = []
    for part in normalize_name(full_name):
        initials.append(part[0].upper())
    return ''.join(initials)


def format_initials(full_name, separator='.'):
    letters = get_initials(full_name)
    if not letters:
        return ''
    return separator.join(letters) + separator


def group_by_initials(names):
    groups = {}
    for name in names:
        key = get_initials(name)
        if key not in groups:
            groups[key] = []
        groups[key].append(' '.join(normalize_name(name)))
    return groups


def build_report(names):
    lines = []
    groups = group_by_initials(names)
    for key in sorted(groups):
        members = groups[key]
        if len(members) == 1:
            lines.append('{0}: {1}'.format(key, members[0]))
        else:
            lines.append('{0}: {1} (shared by {2})'.format(key, ', '.join(sorted(members)), len(members)))
    return lines


def read_names(argv):
    if len(argv) > 1:
        return argv[1:]
    return ['John Doe', 'Alice Mary Smith', 'jane a. doe', 'Mary-Jane Watson']


def main():
    names = read_names(sys.argv)
    for name in names:
        try:
            initials = get_initials(name)
        except TypeError as error:
            print('skipping entry: {0}'.format(error))
            continue
        if not initials:
            print('{0!r} -> no initials found'.format(name))
        else:
            print('{0!r} -> {1} ({2})'.format(name, initials, format_initials(name)))
    print('--- grouped ---')
    for line in build_report(names):
        print(line)


if __name__ == '__main__':
    main()

