class ListNode:
    """A node of a singly linked list."""

    def __init__(self, val=0, next_node=None):
        self.val = val
        self.next = next_node


def build_list(values):
    """Build a linked list from an iterable of values and return its head."""
    head = None
    tail = None
    for value in values:
        node = ListNode(value)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def to_list(head):
    """Collect the values of a linked list into a Python list."""
    values = []
    node = head
    while node is not None:
        values.append(node.val)
        node = node.next
    return values


def format_list(head):
    """Render a linked list as 'a->b->c', or 'None' when empty."""
    values = to_list(head)
    if not values:
        return "None"
    return "->".join(str(value) for value in values)


def remove_nth_from_end(head, n):
    """Remove the nth node from the end of the list and return the new head."""
    if n < 1:
        raise ValueError("n must be a positive integer")
    sentinel = ListNode(0, head)
    lead = sentinel
    for _ in range(n):
        if lead.next is None:
            raise ValueError("n is larger than the length of the list")
        lead = lead.next
    trail = sentinel
    while lead.next is not None:
        lead = lead.next
        trail = trail.next
    trail.next = trail.next.next
    return sentinel.next


def main():
    cases = [([1, 2, 3, 4, 5], 2), ([1], 1), ([7, 8], 2), ([3, 4, 5], 7)]
    for values, n in cases:
        head = build_list(values)
        original = format_list(head)
        try:
            new_head = remove_nth_from_end(head, n)
        except ValueError as error:
            print("{} (n={}) -> error: {}".format(original, n, error))
        else:
            print("{} (n={}) -> {}".format(original, n, format_list(new_head)))


if __name__ == "__main__":
    main()

