def digit_square_sum(n):
    """Return the sum of the squares of the decimal digits of n."""
    total = 0
    while n > 0:
        n, digit = divmod(n, 10)
        total += digit * digit
    return total


def is_happy_number(n):
    """Return True if n is a happy number, False otherwise."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    seen = set()
    while n != 1:
        if n in seen:
            return False
        seen.add(n)
        n = digit_square_sum(n)
    return True


def happy_chain(n):
    """Return the sequence of values visited, stopping at 1 or at a repeat."""
    chain = [n]
    seen = {n}
    while chain[-1] != 1:
        nxt = digit_square_sum(chain[-1])
        chain.append(nxt)
        if nxt in seen:
            break
        seen.add(nxt)
    return chain


def happy_numbers_up_to(limit):
    """Return every happy number in the range 1..limit inclusive."""
    found = []
    for candidate in range(1, limit + 1):
        if is_happy_number(candidate):
            found.append(candidate)
    return found


def describe(n):
    """Build a one-line human readable report for n."""
    chain = happy_chain(n)
    arrow = " -> ".join(str(value) for value in chain)
    if is_happy_number(n):
        verdict = "happy"
    else:
        verdict = "unhappy (cycle detected)"
    return "{0:>4}: {1} [{2}]".format(n, arrow, verdict)


def main():
    for number in (19, 4, 7, 1, 100):
        print(describe(number))
    limit = 50
    happy = happy_numbers_up_to(limit)
    print("Happy numbers up to {0}: {1}".format(limit, happy))
    print("Count: {0}".format(len(happy)))
    for bad in (0, -3):
        try:
            is_happy_number(bad)
        except ValueError as exc:
            print("Rejected {0}: {1}".format(bad, exc))


if __name__ == "__main__":
    main()

