def count_occurrences(items):
    """Return a mapping from element to the number of times it appears."""
    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
    return counts


def find_duplicates(items):
    """Return a list of the elements that appear more than once in items."""
    counts = count_occurrences(items)
    duplicates = []
    for item, total in counts.items():
        if total > 1:
            duplicates.append(item)
    return duplicates


def duplicate_report(items):
    """Return lines describing each duplicated element and its repeat count."""
    counts = count_occurrences(items)
    lines = []
    for item in find_duplicates(items):
        extra = counts[item] - 1
        if extra == 1:
            lines.append("{!r} appears twice".format(item))
        else:
            lines.append("{!r} appears {} times".format(item, counts[item]))
    return lines


def parse_list(text):
    """Turn a comma-separated string into a list, using ints when possible."""
    values = []
    for chunk in text.split(","):
        token = chunk.strip()
        if not token:
            continue
        try:
            values.append(int(token))
        except ValueError:
            values.append(token)
    return values


def describe(text):
    """Print the duplicate analysis of a comma-separated list of values."""
    items = parse_list(text)
    duplicates = find_duplicates(items)
    print("input:      {}".format(items))
    print("duplicates: {}".format(duplicates))
    if duplicates:
        for line in duplicate_report(items):
            print("  - {}".format(line))
    else:
        print("  - every element is unique")


