def normalize_binary(binary_str):
    """Strip surrounding whitespace and an optional '0b' prefix."""
    cleaned = binary_str.strip()
    if cleaned[:2].lower() == "0b":
        cleaned = cleaned[2:]
    return cleaned.replace("_", "")


def validate_binary(binary_str):
    """Return a normalized binary string or raise ValueError."""
    if not isinstance(binary_str, str):
        raise ValueError("binary input must be a string")
    cleaned = normalize_binary(binary_str)
    if cleaned == "":
        raise ValueError("binary input is empty")
    for position, digit in enumerate(cleaned):
        if digit not in "01":
            raise ValueError(
                "invalid digit %r at position %d" % (digit, position)
            )
    return cleaned


def binary_to_decimal(binary_str):
    """Convert a binary string such as '1011' to the integer 11."""
    digits = validate_binary(binary_str)
    value = 0
    for digit in digits:
        value = value * 2 + (1 if digit == "1" else 0)
    return value


def decimal_to_binary(value):
    """Inverse conversion, used to echo the canonical form of a number."""
    if value < 0:
        raise ValueError("only non-negative integers are supported")
    if value == 0:
        return "0"
    bits = []
    while value > 0:
        bits.append(str(value % 2))
        value //= 2
    return "".join(reversed(bits))


def convert_all(inputs):
    """Convert many strings, pairing each input with its result or error."""
    results = []
    for item in inputs:
        try:
            results.append((item, binary_to_decimal(item), None))
        except ValueError as error:
            results.append((item, None, str(error)))
    return results


def format_report(results):
    """Build an aligned text report from convert_all() output."""
    width = max(len(repr(item)) for item, _, _ in results)
    lines = []
    for item, value, error in results:
        label = repr(item).ljust(width)
        if error is None:
            canonical = decimal_to_binary(value)
            lines.append("%s -> %d (canonical %s)" % (label, value, canonical))
        else:
            lines.append("%s -> error: %s" % (label, error))
    return "\n".join(lines)


def main():
    samples = ["1011", "10000", "0b1111_0000", "  101  ", "0", "12", ""]
    print(format_report(convert_all(samples)))


