def reverse_segment(nums, start, end):
    """Reverse nums[start:end+1] in place."""
    while start < end:
        nums[start], nums[end] = nums[end], nums[start]
        start += 1
        end -= 1


def next_permutation(nums):
    """Rearrange nums into the next lexicographically greater permutation.

    If nums is already the highest permutation, it becomes the lowest one.
    The list is modified in place.
    """
    pivot = len(nums) - 2
    while pivot >= 0 and nums[pivot] >= nums[pivot + 1]:
        pivot -= 1
    if pivot >= 0:
        successor = len(nums) - 1
        while nums[successor] <= nums[pivot]:
            successor -= 1
        nums[pivot], nums[successor] = nums[successor], nums[pivot]
    reverse_segment(nums, pivot + 1, len(nums) - 1)
    return nums


def permutation_cycle(nums):
    """Yield every permutation of nums, starting from the sorted order."""
    current = sorted(nums)
    first = tuple(current)
    while True:
        yield tuple(current)
        next_permutation(current)
        if tuple(current) == first:
            return


def validate(nums):
    """Reject inputs that are not lists of mutually comparable numbers."""
    if not isinstance(nums, list):
        raise TypeError("next_permutation expects a list")
    for value in nums:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("only numbers are supported, got %r" % (value,))


def format_row(before, after):
    """Build a one-line report of a single next_permutation step."""
    left = ", ".join(str(value) for value in before)
    right = ", ".join(str(value) for value in after)
    return "[%s] -> [%s]" % (left, right)


def main():
    samples = [[1, 2, 3], [3, 2, 1], [1, 1, 5], [2, 3, 1], [7]]
    for sample in samples:
        validate(sample)
        original = list(sample)
        next_permutation(sample)
        print(format_row(original, sample))

    print()
    for index, permutation in enumerate(permutation_cycle([1, 2, 3]), start=1):
