def count_substring(main_string: str, sub_string: str) -> int:
    """Count overlapping, case-sensitive occurrences of sub_string in main_string."""
    if not isinstance(main_string, str) or not isinstance(sub_string, str):
        raise TypeError("both arguments must be strings")
    if sub_string == "":
        raise ValueError("sub_string must not be empty")
    total = 0
    limit = len(main_string) - len(sub_string)
    for start in range(limit + 1):
        if main_string[start:start + len(sub_string)] == sub_string:
            total += 1
    return total


def occurrence_positions(main_string: str, sub_string: str) -> list:
    """Return the starting indices of every overlapping occurrence."""
    positions = []
    start = main_string.find(sub_string)
    while start != -1:
        positions.append(start)
        start = main_string.find(sub_string, start + 1)
    return positions


def describe_match(main_string: str, sub_string: str) -> str:
    """Build a human readable summary of the search result."""
    try:
        count = count_substring(main_string, sub_string)
    except ValueError:
        return "empty pattern: nothing to search for"
    if count == 0:
        return "{!r} does not occur in {!r}".format(sub_string, main_string)
    positions = occurrence_positions(main_string, sub_string)
    noun = "time" if count == 1 else "times"
    return "{!r} occurs {} {} in {!r} at {}".format(
        sub_string, count, noun, main_string, positions
    )


def summarize(pairs) -> str:
    """Format one report line per (haystack, needle) pair."""
    lines = []
    for main_string, sub_string in pairs:
        lines.append(describe_match(main_string, sub_string))
    return "\n".join(lines)


def most_frequent(main_string: str, candidates) -> str:
    """Return the candidate pattern with the highest occurrence count."""
    best = ""
    best_count = -1
    for candidate in candidates:
        count = count_substring(main_string, candidate)
        if count > best_count:
            best = candidate
            best_count = count
    return best


def main() -> None:
    samples = [
        ("banana", "ana"),
        ("programming", "xyz"),
        ("AaAaAa", "Aa"),
        ("Mississippi", "ss"),
        ("banana", ""),
    ]
    print(summarize(samples))
    words = ["an", "na", "ban", "a"]
    winner = most_frequent("banana", words)
    print("most frequent pattern in 'banana': {!r} ({} hits)".format(
        winner, count_substring("banana", winner)
    ))


if __name__ == "__main__":
    main()

