import random


def generate_random_int(min_val: int, max_val: int) -> int:
    """Return a random integer from the inclusive range [min_val, max_val]."""
    if not isinstance(min_val, int) or not isinstance(max_val, int):
        raise TypeError("min_val and max_val must be integers")
    if min_val > max_val:
        raise ValueError(f"empty range: {min_val} > {max_val}")
    if min_val == max_val:
        return min_val
    return random.randint(min_val, max_val)


def sample_range(min_val: int, max_val: int, count: int) -> list:
    """Draw `count` independent values from the inclusive range."""
    if count < 1:
        raise ValueError("count must be at least 1")
    values = []
    for _ in range(count):
        values.append(generate_random_int(min_val, max_val))
    return values


def tally(values: list) -> dict:
    """Count how often each value occurs."""
    counts = {}
    for value in values:
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1
    return counts


def format_histogram(counts: dict, width: int = 40) -> str:
    """Render the tally as a text histogram, one line per value."""
    if not counts:
        return "(no samples)"
    peak = max(counts.values())
    label_width = max(len(str(value)) for value in counts)
    lines = []
    for value in sorted(counts):
        bar_length = round(counts[value] * width / peak)
        if bar_length == 0 and counts[value] > 0:
            bar_length = 1
        lines.append(
            f"{str(value).rjust(label_width)} | {'#' * bar_length} {counts[value]}"
        )
    return "\n".join(lines)


def describe(values: list) -> str:
    """Summarise a sample with its bounds and mean."""
    total = 0
    for value in values:
        total += value
    mean = total / len(values)
    return f"n={len(values)} min={min(values)} max={max(values)} mean={mean:.2f}"


def main() -> None:
    experiments = [(1, 5, 1000), (10, 10, 3), (-3, 3, 700)]
    for min_val, max_val, count in experiments:
        values = sample_range(min_val, max_val, count)
        print(f"range [{min_val}, {max_val}]")
        print(describe(values))
        print(format_histogram(tally(values)))
        out_of_range = [v for v in values if v < min_val or v > max_val]
        if out_of_range:
            raise AssertionError(f"values outside the range: {out_of_range}")
        print()


if __name__ == "__main__":
    main()

