def has_substring_case_insensitive(main_string: str, sub_string: str) -> bool:
    if not isinstance(main_string, str) or not isinstance(sub_string, str):
        raise TypeError("both arguments must be strings")
    return sub_string.casefold() in main_string.casefold()


def find_all_occurrences(main_string: str, sub_string: str) -> list:
    """Return the start indices of every case-insensitive match."""
    if not sub_string:
        return []
    haystack = main_string.casefold()
    needle = sub_string.casefold()
    positions = []
    start = haystack.find(needle)
    while start != -1:
        positions.append(start)
        start = haystack.find(needle, start + 1)
    return positions


def count_occurrences(main_string: str, sub_string: str) -> int:
    return len(find_all_occurrences(main_string, sub_string))


def filter_matching_lines(lines, sub_string: str) -> list:
    """Keep the (line number, text) pairs whose text contains sub_string."""
    matches = []
    for number, text in enumerate(lines, start=1):
        if has_substring_case_insensitive(text, sub_string):
            matches.append((number, text))
    return matches


def highlight(main_string: str, sub_string: str) -> str:
    """Surround each case-insensitive match with square brackets."""
    positions = find_all_occurrences(main_string, sub_string)
    if not positions:
        return main_string
    width = len(sub_string)
    pieces = []
    cursor = 0
    for start in positions:
        if start < cursor:
            continue
        pieces.append(main_string[cursor:start])
        pieces.append("[" + main_string[start:start + width] + "]")
        cursor = start + width
    pieces.append(main_string[cursor:])
    return "".join(pieces)


def build_report(lines, sub_string: str) -> str:
    matches = filter_matching_lines(lines, sub_string)
    if not matches:
        return "no line contains {!r}".format(sub_string)
    rows = ["matches for {!r}:".format(sub_string)]
    for number, text in matches:
        total = count_occurrences(text, sub_string)
        rows.append("  line {:>2}  ({}x)  {}".format(number, total, highlight(text, sub_string)))
    return "\n".join(rows)


def main() -> None:
    print(has_substring_case_insensitive('Hello World', 'world'))
    print(has_substring_case_insensitive('Python', 'java'))
    document = [
        "Hello World, hello again",
        "Python powers this script",
        "WORLDWIDE shipping available",
        "nothing relevant here",
    ]
    print(build_report(document, "world"))
    print(build_report(document, "java"))


if __name__ == "__main__":
    main()

