def remove_all_elements(data_list: list, element_to_remove) -> list:
    """Return a new list with every occurrence of element_to_remove dropped."""
    if not isinstance(data_list, list):
        raise TypeError("data_list must be a list")
    result = []
    for item in data_list:
        if item != element_to_remove:
            result.append(item)
    return result


def count_occurrences(data_list: list, element) -> int:
    """Count how many entries of data_list compare equal to element."""
    total = 0
    for item in data_list:
        if item == element:
            total += 1
    return total


def remove_several(data_list: list, elements) -> list:
    """Remove every element of `elements` from data_list, one pass per value."""
    cleaned = list(data_list)
    for element in elements:
        cleaned = remove_all_elements(cleaned, element)
    return cleaned


def describe_removal(data_list: list, element) -> str:
    """Build a one-line summary of what removing `element` would do."""
    removed = count_occurrences(data_list, element)
    survivors = remove_all_elements(data_list, element)
    if removed == 0:
        verdict = "nothing to remove"
    elif not survivors:
        verdict = "list becomes empty"
    else:
        verdict = "{} item(s) kept".format(len(survivors))
    return "remove {!r}: {} occurrence(s) dropped, {} -> {}".format(
        element, removed, verdict, survivors
    )


def main() -> None:
    cases = [
        ([1, 2, 3, 2, 4], 2),
